-- Death explosions (ExplosionType ids of this build, checked against their records: the acid deaths carry acid):
-- { id, label }
MOD.enemy.BLASTS = {
    Terminids = { { 71, 'Scavenger acid burst' }, { 310, 'Warrior acid burst' }, { 275, 'Bile Spewer acid burst' },
                  { 276, 'Charger acid burst' } },
    Automatons = { { 10, 'Hulk death (and medium vehicles)' }, { 103, 'Vehicle death (medium, ground)' }, { 13, 'Vehicle death (large, ground)' },
                   { 39, 'Vehicle death (large, air)' }, { 346, 'Vehicle death (huge)' }, { 37, 'Fabricator death' },
                   { 114, 'Dropship death (air)' }, { 153, 'Dropship death (ground)' } },
    Illuminate = { { 311, 'Illusionist death' }, { 61, 'Spawner death' }, { 137, 'Dark Fluid burst' } },
}
function MOD.enemy.blasts_resolve(entry)
    for _, b in ipairs(entry.enemy.blasts) do
        local xrow = tables[T_EXPLOSION] and tables[T_EXPLOSION].index[b[1]]
        if xrow then
            local prefix = 'x' .. b[1] .. '_'
            local did = read_field(field_at(T_EXPLOSION, xrow + 4, 'u32', 100000))
            local qrow = did and did > 0 and tables[T_DAMAGE] and tables[T_DAMAGE].index[did]
            if qrow then damage_rows(entry, b[2], prefix, qrow, 'Explosion') end
            for _, r in ipairs({ { 'inner', 'Inner radius (m)', 16 }, { 'outer', 'Outer radius (m)', 20 },
                                 { 'shockwave', 'Shockwave radius (m)', 24 } }) do
                add_row(entry, b[2], prefix .. r[1], r[2], 'f32', { part(prefix .. r[1], T_EXPLOSION, xrow + r[3], 'f32', 100000) }, 0, 200, 0.1, 1)
            end
            MOD.explosion_extras(entry, b[2], prefix, xrow)
        end
    end
end

function MOD.enemy.faction_resolve(entry)
    for _, s in ipairs(MOD.enemy.FACTION_STATS) do
        local lead = { id = s[2], field = field_at(0, 'enemy:' .. entry.hash .. ':' .. s[2], 'virtual', 1000) }
        local add = s[4] == 'add'
        lead.field.default = add and 0 or 1
        local r = add_row(entry, s[1], s[2], s[3], add and 'u32' or 'f32', { lead }, add and -10 or 0, s[5],
                          add and 1 or 0.05, add and 1 or 0.25)
        r.faction, r.add, r.note = s, add or nil, s[6]
        if s[8] == 'anim' then r.tip = MOD.physics.ANIM_TIP end
        lead.field.signed = add or nil
        if s == MOD.enemy.FACTION_STATS[#MOD.enemy.FACTION_STATS] then   -- under the last row: the blue marks
            r.after = { 'Enemies and values this page changes are marked in blue in the list and on their pages.',
                        "A value changed on an enemy's own page stays red: this page leaves it as it is." }
            r.after_h = #r.after * 16 + 6
        end
    end
end

-- A multiplier row: a value of its own (1: the game's) and the fields it multiplies (row.mult: each written as
-- its game value x the multiplier, or / it for `inverse`).
function MOD.enemy.mult_row(entry, section, id, label, fields, max, inverse, note, key)   -- key: a value pages share
    local lead = { id = id, field = field_at(0, key or ('enemy:' .. entry.hash .. ':' .. id), 'virtual', 1000) }
    lead.field.default = 1
    local p = { lead }
    for n, f in ipairs(fields) do p[#p + 1] = part(id .. '_' .. n, f[1], f[2], f[3] or 'f32', 1000000) end
    local r = add_row(entry, section, id, label, 'f32', p, inverse and 0.05 or 0, max or 10, 0.05, 0.25)
    r.lead, r.mult, r.inverse, r.note = true, true, inverse or nil, note
    return r
end

-- The example difficulties (Enemy Editor presets, added once): { name, { { faction id or 'all', 'page' (faction-wide)
-- / 'spawn' (its Spawning page) / 'floors' (All factions), row id, value }, ... } }
MOD.enemy.EXAMPLES = {
    { 'Default', {} },   -- no changes: loading it puts every enemy and spawning value back to the game's
    { 'Horde', { { 'all', 'spawn', 'reinf_budget', 2 }, { 'all', 'spawn', 'reinf_rate', 2 }, { 'all', 'spawn', 'patrol_rate', 2 },
                 { 'all', 'spawn', 'patrol_max', 2 }, { 'all', 'spawn', 'cap', 1.5 }, { 'all', 'page', 'all_health', 0.8 } } },
    { 'Glass Cannon', { { 'all', 'page', 'all_health', 0.5 }, { 'all', 'page', 'all_damage', 2 } } },
    { 'Elite', { { 'all', 'page', 'all_health', 1.5 }, { 'all', 'page', 'all_armor', 1 }, { 'all', 'page', 'all_damage', 1.25 },
                 { 'all', 'page', 'all_speed', 1.15 }, { 'all', 'page', 'all_sight', 1.5 } } },
}

-- The built-in example presets (MOD.enemy.EXAMPLES, from upstream 4.5.1) as global presets of the library (group
-- 'Built-in'): each holds only its own values ('patch': loading it adds them to your changes, nothing else is reset).
-- 'all': the whole-game enemy page (FFFFFFFB000000FE) for enemy stats, every faction's spawning page for spawning.
-- First start (no marker in the preset folder): put in once; Settings' Restore button: put back as they came.
function MOD.enemy.restore_examples(lib, overwrite)
    if not lib then return 0 end
    local done = 0
    for _, ex in ipairs(MOD.enemy.EXAMPLES) do
        if #ex[2] > 0 then
            local values = {}
            for _, v in ipairs(ex[2]) do
                if v[2] == 'page' then values[#values + 1] = { hash = 'FFFFFFFB000000FE', id = v[3], value = v[4] }
                else
                    for _, f in ipairs({ 2, 8, 4 }) do values[#values + 1] = { hash = string.format('FFFFFFFC%08X', f), id = v[3], value = v[4] } end
                end
            end
            local payload = { values = values, data = { version = 2 }, group = 'Built-in', kind = 'patch',
                              description = MOD.nav.text({ 'Built-in example (enemies and spawning only): loading it adds these values to your changes.',
                                                           '内置示例（只含敌人与刷怪数值）：载入时把这些数值叠加到当前修改上，其余不变。',
                                                           '內建範例（只含敵人與刷怪數值）：載入時把這些數值疊加到目前修改上，其餘不變。' }) }
            local found = nil
            for _, p in ipairs(lib:list()) do if p.name == ex[1] and (p.group or '') == 'Built-in' then found = p end end
            if found and overwrite then
                local ok = lib:replace(found.id, payload)
                if ok then done = done + 1 end
            elseif not found then
                local id = lib:create('global', ex[1], payload, 'patch')
                if id then done = done + 1 end
            end
        end
    end
    return done
end

function MOD.enemy.spawning_resolve(entry)
    if entry.enemy.floors then
        local ft = tables[TYPES.spawn_floor]
        local at = ft and next(ft.index) and ft.index[next(ft.index)]
        if not at then return end
        MOD.enemy.mult_row(entry, 'Lowest rates', 'floor_patrol', 'Lowest patrol frequency (x)',
                           { { TYPES.spawn_floor, at + 80 }, { TYPES.spawn_floor, at + 84 } }, 10, nil,
                           'the faction multipliers cannot slow patrols below this: lower it with them')
        MOD.enemy.mult_row(entry, 'Lowest rates', 'floor_reinf', 'Lowest reinforcement frequency (x)',
                           { { TYPES.spawn_floor, at + 88 }, { TYPES.spawn_floor, at + 92 } }, 10)
        MOD.enemy.mult_row(entry, 'SEAF', 'seaf_reinf', 'SEAF reinforcement cooldown (x)',
                           { { TYPES.spawn_floor, at + 48 }, { TYPES.spawn_floor, at + 52 }, { TYPES.spawn_floor, at + 56 },
                             { TYPES.spawn_floor, at + 60 } }, 10)
        MOD.enemy.mult_row(entry, 'SEAF', 'seaf_wave', 'SEAF wave cooldown (x)',
                           { { TYPES.spawn_floor, at + 64 }, { TYPES.spawn_floor, at + 68 }, { TYPES.spawn_floor, at + 72 },
                             { TYPES.spawn_floor, at + 76 } }, 10)
        return
    end
    local t = tables[TYPES.hivemind]
    if not t then return end
    local top = t.copies[1] + HEADER_BYTES
    local records = {}
    for _, off in pairs(t.index) do
        if peek4(top + off) == entry.enemy.spawning then records[#records + 1] = off end
    end
    table.sort(records)
    if #records == 0 then return end
    for _, s in ipairs(MOD.enemy.SPAWN) do
        if s[5] == 'flag' then
            local p = {}
            for n, off in ipairs(records) do p[n] = part(s[2] .. (n > 1 and ('_' .. n) or ''), TYPES.hivemind, off + s[4], 'flag', 1) end
            local r = add_row(entry, s[1], s[2], s[3], 'flag', p, 0, 1, 1, 1)
            r.lead = true
        else
            local fields = {}
            for _, off in ipairs(records) do
                for k = 0, s[5] == 'one' and 0 or 3 do fields[#fields + 1] = { TYPES.hivemind, off + s[4] + k * 4 } end
            end
            MOD.enemy.mult_row(entry, s[1], s[2], s[3], fields, s[5] == 'one' and 10 or 20, s[5] == 'inverse', s[6])
        end
    end
end

local function resolve(weapon)
    if weapon.stratagem_entity_groups then
        weapon.component_groups=nil;weapon.hidden_rows=nil;weapon.stratagem_entity_groups=nil
        weapon.custom_modified=weapon.stratagem_prior_modified
    end
    if weapon.lazy_components_attached then
        weapon.custom_modified=weapon.component_previous_modified
        weapon.lazy_components_attached,weapon.component_previous_modified=nil,nil
        weapon.legacy_rows,weapon.component_groups,weapon.hidden_rows,weapon.all_component_rows=nil,nil,nil,nil
        weapon.field_keys={}
    end
    weapon.rows, weapon.by_id, weapon.aliases, weapon.backpack, weapon.mines, weapon.legacy = {}, {}, nil, nil, nil, nil
    weapon.swaps = nil
    weapon.grenade_swap = nil
    if weapon.slot == 'Throwables' then resolve_throwable(weapon); return end
    -- a support weapon you place (the C4 Pack): the backpack that shares its loadout package (its
    -- charges), the charge (health, throw distance) and its explosion
    if weapon.slot == 'Support' and KINDS[TYPES.package].placed(weapon.key) then
        local dt = tables[TYPES.deposit]
        for _, k in ipairs(KINDS[TYPES.package].kin(weapon.key)) do
            if dt and dt.index[k] then KINDS[TYPES.jumppack].backpack(weapon, k) end
        end
        if not KINDS[TYPES.seeking].silo_rows(weapon) then unit_rows(weapon, weapon.key, 'Charge', 'charge_') end
        resolve_throwable(weapon, true)
        return
    end
    if weapon.booster then MOD.boosters.resolve(weapon); return end
    if weapon.enemy then
        if weapon.slot == 'Spawning' then MOD.enemy.spawning_resolve(weapon)
        elseif weapon.enemy.faction then MOD.enemy.faction_resolve(weapon)
        elseif weapon.enemy.blasts then MOD.enemy.blasts_resolve(weapon)
        elseif weapon.enemy.gun then resolve_gun(weapon, weapon.key); MOD.enemy.gun_tidy(weapon)
        else MOD.enemy.resolve(weapon) end
        return
    end
    if weapon.passive then KINDS[TYPES.passive].resolve(weapon); return end
    if weapon.kits then MOD.kits.resolve(weapon); return end
    if weapon.player then KINDS[TYPES.avatar].resolve(weapon); return end
    if weapon.orbital_beam then MOD.orbital.beam_resolve(weapon); return end
    if weapon.stratagem then resolve_stratagem(weapon); return end
    if weapon.attachment then
        KINDS[TYPES.items].mod_rows(weapon, 'Attachment', '', weapon.attachment.mods)
        local scope = weapon.attachment.scope   -- zoom: 1 = normal view, 2 = half the field of view; zeroing in m
        for k = 1, 3 do
            local z = scope and scope['236:' .. (112 + k * 4)]
            if z then
                add_row(weapon, 'Scope', 'zoom' .. k, 'Zoom level ' .. k .. ' (x)', 'f32', { { id = 'zoom' .. k, field = field_at(TYPES.deltas, z, 'f32', 1000) } }, 0.1, 100, 0.1, 1).tip =
                    { 'How close this zoom step looks: 1 is the normal view, 2 twice as close, 4 four times.' }
            end
        end
        for k = 1, 3 do
            local z = scope and scope['236:' .. (336 + k * 4)]
            if z then
                add_row(weapon, 'Scope', 'zero' .. k, 'Zeroing distance ' .. k .. ' (m)', 'f32', { { id = 'zero' .. k, field = field_at(TYPES.deltas, z, 'f32', 100000) } }, 0, 5000, 5, 50).tip =
                    { 'The range the sights are set for at this step (you switch steps in game). At that range the shot lands',
                      'on the crosshair; closer or farther it lands a bit high or low. Does not change the zoom.' }
            end
        end
        -- per zoom level: how quickly the view follows your aim (+316; 0.6 on most optics, the 10x sniper scopes'
        -- 0.8 / 1 / 1.25; high zoom with a high follow speed spins the view, issue #89)
        for k = 1, 3 do
            local z = scope and scope['236:' .. (312 + k * 4)]
            if z then
                local r = add_row(weapon, 'Scope', 'follow' .. k, 'Zoom level ' .. k .. ' follow speed', 'f32', { { id = 'follow' .. k, field = field_at(TYPES.deltas, z, 'f32', 1000) } }, 0.01, 10, 0.05, 0.25)
                r.tip = { 'How quickly the scoped view catches up when you move your aim at this zoom (0.6 on most optics).',
                          'Lower it if a high zoom spins the view.' }
            end
        end
        return
    end
    -- sentries and emplacements (listed as weapons on the Stratagems tab): their body, then their gun
    if weapon.slot == 'Stratagems' then
        local parts = {}
        for k, def in ipairs(weapon.sentry_defs or {}) do
            parts[k] = part(k == 1 and 'cooldown' or 'cooldown' .. k, def.kind, def.off + 104, 'f32', 100000)
        end
        if parts[1] then add_row(weapon, 'Stratagem', 'cooldown', 'Cooldown (s)', 'f32', parts, 0, 10000, 1, 10) end
        if weapon.sentry_defs[1] then MOD.code.row(weapon, weapon.sentry_defs[1]) end
        if weapon.sentry_defs[1] then MOD.callin_rows(weapon, weapon.sentry_defs) end
        if weapon.sentry_defs[1] then MOD.extra.row(weapon, weapon.sentry_defs[1]) end
        unit_rows(weapon, KINDS[TYPES.health].body(weapon.key) or weapon.key, weapon.name:find('^E/') and 'Emplacement' or 'Sentry', 'unit_')
        -- how long it stays once deployed (HellpodPayloadComponentData +4; SHODAN Offline Integration)
        local pt = tables[TYPES.payload]
        local pat = pt and pt.index[weapon.key]
        local life = pat and default_of(field_at(TYPES.payload, pat + 4, 'f32', 100000))
        if life and life > 0 and life <= 7200 then
            add_row(weapon, weapon.name:find('^E/') and 'Emplacement' or 'Sentry', 'unit_lifetime', 'Time deployed (s)', 'f32',
                    { part('unit_lifetime', TYPES.payload, pat + 4, 'f32', 100000) }, 1, 7200, 5, 30)
        end
    end
    -- Separate EXO mounted-arm durability and the Breakthrough physical shield.
    local exo, arm_name = weapon.name:match('^(EXO%-%d%d .+): (.+)$')
    if weapon.mounted and MOD.exo_mounted[exo] and (arm_name == 'Left arm' or arm_name == 'Right arm') then
        local ht = tables[TYPES.health]
        local at = ht and ht.index[weapon.key]
        if at then
            local hp = default_of(field_at(TYPES.health, at, 'u32', 10000000))
            local armor = default_of(field_at(TYPES.health, at + 280, 'u32', 100))
            if hp and hp > 0 and hp <= 1000000 and armor and armor <= 10 then
                -- the arm's own zone (+520) takes the hits: with health of its own (-1: none, the arm's) it leads,
                -- the arm's values follow (the Patriot's arm went at its zone's 800 with the arm's at 5000, in game)
                local health_parts = { part('arm_health', TYPES.health, at, 'u32', 10000000) }
                local armor_parts = { part('arm_armor', TYPES.health, at + 280, 'u32', 100) }
                local zone_hp = default_of(field_at(TYPES.health, at + 520 + 232, 'u32', 10000000))
                if zone_hp and zone_hp > 0 then
                    table.insert(health_parts, 1, part('arm_zone_health', TYPES.health, at + 520 + 232, 'u32', 10000000))
                    table.insert(armor_parts, 1, part('arm_zone_armor', TYPES.health, at + 520 + 216, 'u32', 100))
                end
                local hp_row = add_row(weapon, 'Arm durability', 'arm_health', 'Arm health', 'u32', health_parts, 1, 1000000, 50, 500)
                local armor_row = add_row(weapon, 'Arm durability', 'arm_armor', 'Arm armor', 'u32', armor_parts, 0, 10, 1, 1)
                hp_row.lead, armor_row.lead = true, true
                if exo == 'EXO-55 Breakthrough Exosuit' and arm_name == 'Left arm' then
                    local shield_arm_armor = default_of(field_at(TYPES.health, at + 520 + 216, 'u32', 100))
                    local plate_hp = default_of(field_at(TYPES.health, at + 520 + 552 + 232, 'u32', 10000000))
                    local plate_armor = default_of(field_at(TYPES.health, at + 520 + 552 + 216, 'u32', 100))
                    if shield_arm_armor and shield_arm_armor <= 10 and plate_hp and plate_hp > 0
                       and plate_hp <= 1000000 and plate_armor and plate_armor <= 10 then
                        add_row(weapon, 'Physical shield', 'shield_arm_armor', 'Shield arm zone armor', 'u32',
                                { part('shield_arm_armor', TYPES.health, at + 520 + 216, 'u32', 100) }, 0, 10, 1, 1)
                        add_row(weapon, 'Physical shield', 'shield_plate_health', 'Shield plate health', 'u32',
                                { part('shield_plate_health', TYPES.health, at + 520 + 552 + 232, 'u32', 10000000) }, 1, 1000000, 250, 1000)
                        add_row(weapon, 'Physical shield', 'shield_plate_armor', 'Shield plate armor', 'u32',
                                { part('shield_plate_armor', TYPES.health, at + 520 + 552 + 216, 'u32', 100) }, 0, 10, 1, 1)
                    end
                end
            end
        end
    end
    resolve_gun(weapon, weapon.key)
    if not weapon.mounted and (weapon.slot == 'Primary' or weapon.slot == 'Secondary') then
        MOD.slot.row(weapon)
        if weapon.slot == 'Primary' then MOD.holster.row(weapon) end
    end
end

-- The shots a weapon fires besides its projectile, read as the game had them: a second ammo type
-- (rounds +68 when not +64's: the SG-20 Halt's stun rounds, toggled in game; named for a stun it
-- applies) and a patterned magazine's other rounds (magazine +0 type 1, +4: 32 projectiles fired in
-- turn: the MG-43's and Bullet Storm's tracers, the machine gun sentries'). { id, prow, name, prefix,
-- field (the second ammo type's) or slots (the pattern's fields, every round's) }, nil when none.
KINDS[T_ROUNDS].extra = function(rounds, magazine, projectile)
    local list = {}
    local function prow_of(id) return id and id > 0 and tables[T_PROJECTILE] and tables[T_PROJECTILE].index[id] end
    local f = rounds and field_at(T_ROUNDS, rounds + 68, 'u32', 100000)
    local alt = f and default_of(f)
    if prow_of(alt) and alt ~= projectile then
        local did = read_field(field_at(T_PROJECTILE, prow_of(alt) + 60, 'u32', 100000))
        local drow = did and tables[T_DAMAGE] and tables[T_DAMAGE].index[did]
        local stun = nil
        for i = 0, 3 do
            local kind = drow and read_field(field_at(T_DAMAGE, drow + 44 + i * 8, 'u32', 100000))
            stun = stun or (kind and KINDS[T_STATUS].stuns[kind])
        end
        list[#list + 1] = { id = alt, prow = prow_of(alt), name = stun and 'Stun rounds' or 'Second ammo', prefix = 'a2_', field = f }
    end
    if magazine and default_of(field_at(T_MAGAZINE, magazine, 'u32', 100000)) == 1 then
        local slots, other = {}, nil
        for k = 0, 31 do
            local slot = field_at(T_MAGAZINE, magazine + 4 + k * 4, 'u32', 100000)
            local id = default_of(slot)
            if id and id > 0 then
                slots[#slots + 1] = slot
                if id ~= projectile then other = other or id end
            end
        end
        if prow_of(other) then
            list[#list + 1] = { id = other, prow = prow_of(other), name = 'Tracer rounds', prefix = 't_', slots = slots }
        elseif #slots > 0 then
            list[#list + 1] = { slots = slots }   -- every round its projectile: only the swap writes them
        end
    end
    return #list > 0 and list or nil
end

-- Projectile swap (the last row of a weapon that fires projectiles): one row writing every field the
-- weapon's projectile comes from (its rounds record, ammo type, fire mode, charge stages) with another
-- weapon's projectile. The stat rows above stay the weapon's own projectile's. Choices:
-- KINDS[T_PROJECTILE].choices, every listed weapon's own projectiles by name (built after resolving).
-- Weapons with a second firing mode (the "programmable ammo" weapon function: the Autocannon's flak,
-- the Recoilless Rifle's HE) fire the fire mode's +576 in it: a second swap row for that one. `extra`
-- (KINDS[T_ROUNDS].extra): a patterned magazine's rounds take the swapped projectile too (every one of
-- them), a second ammo type has its own row.
KINDS[T_PROJECTILE].swap_row = function(weapon, sources, shots, fire, extra)
    if #sources == 0 or not (weapon.projectile or shots) then return end
    local main = nil
    for _, src in ipairs(sources) do
        if shots and src.id == 'proj_c' .. shots[#shots].last then main = main or src end
        if not shots and src.own == weapon.projectile then main = main or src end
    end
    main = main or sources[1]
    local parts = { { id = main.id, field = main.field } }
    for _, src in ipairs(sources) do
        if src ~= main then parts[#parts + 1] = { id = src.id, field = src.field } end
    end
    local ammo = nil
    for _, shot in ipairs(extra or {}) do
        for k, slot in ipairs(shot.slots or {}) do parts[#parts + 1] = { id = 'proj_mag' .. k, field = slot } end
        if shot.field then ammo = shot end
    end
    local function swap(id, label, row_parts)
        local row = add_row(weapon, 'Projectile swap', id, label, 'u32', row_parts, 1, 100000, 1, 10)
        row.choice = true
        weapon.swaps = weapon.swaps or {}
        weapon.swaps[#weapon.swaps + 1] = row
        row.note = function(others)
            local spec, now, own = KINDS[T_PROJECTILE], read_field(row_parts[1].field), default_of(row_parts[1].field)
            local shot = spec.by_id and spec.by_id[now]
            local text = now == own and "its own. - / + : fire another weapon's"
                         or ('fires: ' .. (shot and shot.label or ('projectile ' .. tostring(now))) .. '. The rows above stay its own')
            if #others > 0 then text = text .. '; ammo type shared with ' .. table.concat(others, ', ', 1, math.min(2, #others)) end
            return text
        end
        return row
    end
    local row = swap('projectile', 'Projectile fired (id)', parts)
    local alt = fire and field_at(T_FIRE, fire + 576, 'u32', 100000)
    local second = alt and default_of(alt)
    if second and second > 0 then
        row = swap('projectile_2', 'Second mode fires (id)', { { id = 'projectile_2', field = alt } })
    else
        second = nil
    end
    if ammo then
        local id = 'projectile_' .. ammo.prefix:sub(1, -2)
        local row_parts = { { id = id, field = ammo.field } }
        if ammo.delta then row_parts[2] = { id = id .. '_ammo', field = ammo.delta } end
        row = swap(id, ammo.name .. ' fire (id)', row_parts)
    end
    -- under the last row: what a swap changes and what it keeps (drawn below it, `after_h` units)
    row.after = { "Swapping makes the shot the chosen weapon's, your edits to it included: damage,",
                  'armor penetration, forces, velocity, drag, gravity, pellets and explosions. Kept: this',
                  "weapon's fire rate, ammo, handling and heat. To tune the shot, edit the chosen weapon." }
    row.after_h = #row.after * 16 + 6
    weapon.own_shots = {}
    for _, shot in ipairs(shots or { { id = weapon.projectile } }) do
        weapon.own_shots[#weapon.own_shots + 1] = { id = shot.id, key = weapon.key,
            label = shots and (weapon.name .. ' (' .. shot.name:lower() .. ')') or weapon.name }
    end
    if second then weapon.own_shots[#weapon.own_shots + 1] = { id = second, key = weapon.key, label = weapon.name .. ' (second mode)' } end
    if ammo then
        weapon.own_shots[#weapon.own_shots + 1] = { id = ammo.id, key = weapon.key, label = weapon.name .. ' (' .. ammo.name:lower() .. ')' }
    end
end

-- The choices: every own projectile once (the first weapon's name, by name), in name order.
KINDS[T_PROJECTILE].list_choices = function()
    local list, by = {}, {}
    for _, w in ipairs(weapons) do
        for _, shot in ipairs(w.own_shots or {}) do
            if not by[shot.id] then by[shot.id] = shot; list[#list + 1] = shot end
        end
    end
    table.sort(list, function(a, b) return a.label:lower() < b.label:lower() end)
    KINDS[T_PROJECTILE].choices, KINDS[T_PROJECTILE].by_id = list, by
end

-- The projectile `n` choices on from `id` (from either end when `id` is not one).
KINDS[T_PROJECTILE].step = function(id, n)
    local list, at = KINDS[T_PROJECTILE].choices or {}, nil
    for k, shot in ipairs(list) do if shot.id == id then at = k end end
    if #list == 0 then return id end
    at = at or (n > 0 and 0 or #list + 1)
    return list[math.max(1, math.min(#list, at + n))].id
end

-- Records (CarbonAnime, PR #58): the projectile, explosion and status records themselves, by id. Their names: a
-- projectile's the game's name of its round (MOD.round_names), else the first weapon that fires it; an explosion's
-- the first weapon that sets it off, else the round that does; a status's its own (Burning, Gas, stuns).
MOD.records = { pages = {}, list = nil, cache = nil, KINDS = { T_PROJECTILE, T_EXPLOSION, T_STATUS, T_DAMAGE, TYPES.arc, T_BEAM },
                WORD = { [T_PROJECTILE] = 'Projectile', [T_EXPLOSION] = 'Explosion', [T_STATUS] = 'Status',
                         [T_DAMAGE] = 'Damage', [TYPES.arc] = 'Arc', [T_BEAM] = 'Beam' },
                PREFIX = { [T_PROJECTILE] = 'F1', [T_EXPLOSION] = 'F2', [T_STATUS] = 'F3',
                           [T_DAMAGE] = 'F4', [TYPES.arc] = 'F5', [T_BEAM] = 'F6' } }
-- Enum/record row ids (轨道飞鹰 / 游戏数据): external "planning" names from record_names.json / .txt.
MOD.record_names = require('record_names')
MOD.name_ids = require('name_ids')
function MOD.record_names.is_tab(tab)
    return tab == 'RecDamage' or tab == 'RecProjectile' or tab == 'RecExplosion' or tab == 'RecArc'
        or tab == 'RecBeam' or tab == 'RecStatus' or tab == 'RecStratagem' or tab == 'Orbital'
        or tab == 'Eagle' or tab == 'OrbitalBeam' or tab == 'Stratagems' or tab == 'Mechas' or tab == 'Records'
end
function MOD.record_names.type_of(page)
    if page.component_index~=nil then return page.component_type end
    if page.stratagem then
        local family = page.stratagem.family
        if family == 'orbital' then return 'bombardment' end
        if family == 'eagle' then return 'eagle' end
        return 'stratagem'
    end
    if page.stratagem_type then return 'stratagem' end
    if page.orbital_beam then return 'orbital' end
    local kind = page.kind
    if kind == T_DAMAGE then return 'damage'
    elseif kind == T_PROJECTILE then return 'projectile'
    elseif kind == T_EXPLOSION then return 'explosion'
    elseif kind == T_STATUS then return 'status'
    elseif kind == TYPES.arc then return 'arc'
    elseif kind == T_BEAM then return 'beam'
    elseif kind == T_STRATAGEM then return 'stratagem' end
end
-- The payload component's own record key (EntityHash): Bombardment for an orbital barrage, EagleComponent
-- (or EagleSpawner) for an Eagle strike. Hex is the display/jump id; decimal is accepted by the name files too.
function MOD.record_names.payload_component(page)
    local s = page.stratagem
    if not s then return nil end
    local family = s.family
    local function key_hex(key) return string.format('%08X%08X', u32(key, 4), u32(key, 0)) end
    for _, key in ipairs(s.payloads or {}) do
        local hex = key_hex(key)
        if family == 'orbital' and tables[TYPES.bombard] and tables[TYPES.bombard].index[key] then return hex, key end
        if family == 'eagle' and MOD.eagle_components and MOD.eagle_components.by_entity
           and MOD.eagle_components.by_entity[hex] then return hex, key end
    end
    for _, key in ipairs(s.payloads or {}) do
        local hex = key_hex(key)
        if family == 'orbital' and tables[T_ORBITAL] and tables[T_ORBITAL].index[key] then return hex, key end
        if family == 'eagle' and MOD.eagle_spawner_components and MOD.eagle_spawner_components.by_entity
           and MOD.eagle_spawner_components.by_entity[hex] then return hex, key end
    end
end
function MOD.record_names.decimal_of(page)
    local _, key = MOD.record_names.payload_component(page)
    return key and MOD.orbital.decimal(key)
end
function MOD.record_names.id_of(page)
    if page.component_index~=nil then return page.component_index end
    if page.stratagem then
        local family = page.stratagem.family
        if family == 'orbital' or family == 'eagle' then return MOD.record_names.payload_component(page) end
        local def = page.stratagem.def
        return def and peek4(def.at) or page.stratagem.id
    end
    if page.orbital_beam then return page.hash end
    if page.stratagem_type or page.record then return page.id end
end
function MOD.record_names.is_page(page)
    return MOD.record_names.type_of(page) ~= nil and MOD.record_names.id_of(page) ~= nil
end
function MOD.record_names.ensure()
    if not MOD.record_names.loaded then
        local dir = data_dir('StatEditor')
        local names_dir = rawget(_G, 'SHODAN_NAMES_DIRECTORY')
        if dir then pcall(MOD.record_names.load, dir, names_dir) end
    end
end
function MOD.record_names.name_of(page)
    if page.component_index==nil and not page.record and not page.stratagem_type then
        local hash=page.entity_hash or(page.orbital_beam and page.hash)
        local catalog=MOD.component_catalog
        if catalog then catalog:refresh()end
        local item=hash and catalog and(catalog.config.entities[page.entity_id or('E'..hash)]or catalog.config.entities[hash])
        if item and item.name then
            local n=item.name
            return type(n)=='table'and(n[catalog.language]or n.en or n['zh-Hans']or select(2,next(n)))or n
        end
    end
    local t, id = MOD.record_names.type_of(page), MOD.record_names.id_of(page)
    if not t or not id then return nil end
    MOD.record_names.ensure()
    local name = MOD.record_names.name(t, id)
    if not name then
        local decimal = MOD.record_names.decimal_of(page)
        if decimal then name = MOD.record_names.name(t, decimal) end
    end
    if not name and page.orbital_beam then
        name = MOD.record_names.name(t, MOD.orbital.decimal(page.key)) or MOD.record_names.name(t, page.hash)
    end
    return name
end
function MOD.record_names.label(page, tr)
    if page.stratagem_entity_page then
        local label=MOD.record_names.name_of(page)or(tr and tr(page.name)or page.name)
        return page.name==page.entity_hash and('Entity '..page.entity_hash)or(label..' ['..page.entity_hash..']')
    end
    local id, name = MOD.record_names.id_of(page), tr and tr(page.name) or page.name
    local custom = MOD.record_names.name_of(page)
    if custom and custom ~= '' then
        return (id and ('#' .. tostring(id) .. ' · ') or '') .. (tr and tr(custom)or custom)
    end
    if id and not name:find('#' .. tostring(id), 1, true) then return '#' .. tostring(id) .. ' · ' .. name end
    return name
end
function MOD.record_names.search_text(page)
    local id, custom = MOD.record_names.id_of(page), MOD.record_names.name_of(page)
    local decimal = MOD.record_names.decimal_of(page)
    return tostring(page.name or '') .. ' ' .. tostring(page.note or '')
        .. (id and (' ' .. tostring(id)) or '') .. (decimal and (' ' .. tostring(decimal)) or '')
        .. (custom and (' ' .. custom) or '')
        .. (page.component_index==nil and page.component_search and (' '..page.component_search)or'')
        .. (type(id)=='number'and(' 0x'..string.format('%X',id))or'')
        .. (page.component_index==nil and page.entity_hash and(' 0x'..page.entity_hash..' '..tostring(MOD.name_ids.decimal(page.entity_hash)or''))or'')
        .. (page.orbital_beam and page.hash and(' 0x'..page.hash)or'')
        .. (page.orbital_beam and page.key and(' '..MOD.orbital.decimal(page.key))or'')
end
-- Semantic reference types, independent of labels/translations and integer storage.
MOD.references = {
    KINDS = { projectile_id=T_PROJECTILE, explosion_id=T_EXPLOSION, damage_id=T_DAMAGE,
              status_effect_id=T_STATUS, arc_id=TYPES.arc, beam_id=T_BEAM },
    CHOICES = { shrapnel='projectile_id', explosion='explosion_id', status='status_effect_id', stratagem='stratagem_id' },
}
function MOD.references.type_of(row)
    if row.reference_type then return row.reference_type end
    if row.choice == true then return 'projectile_id' end
    return MOD.references.CHOICES[row.choice]
end
-- Display-only references have no writable parts, so presets/resets cannot change a record identity
-- or an internal link that this page only reads to show its existing stats.
function MOD.references.row(entry, section, id, label, kind, offset, ref)
    local f = field_at(kind, offset, 'u32', 100000)
    local row = add_row(entry, section, id, label, 'u32', {}, 0, 100000, 1, 1)
    row.reference_type, row.link_only = ref, true
    row.reference_value = function() return read_field(f) end
    row.label_of = function()
        return MOD.nav.text(({ damage_id={'Damage ID','伤害 ID','傷害 ID'},
            projectile_id={'Projectile ID','射弹 ID','射彈 ID'}, explosion_id={'Explosion ID','爆炸 ID','爆炸 ID'},
            arc_id={'Arc ID','电弧 ID','電弧 ID'}, beam_id={'Beam ID','激光 ID','激光 ID'} })[ref] or label)
    end
    return row
end
function MOD.references.tip(row, own)
    local ref = MOD.references.type_of(row)
    if not ref then return own end
    local lines = { row.label_of and row.label_of() or row.label }
    for _, line in ipairs(own or {}) do lines[#lines + 1] = line end
    lines[#lines + 1] = MOD.nav.text({ 'Type: ', '数值类型：', '數值類型：' }) .. ref
    lines[#lines + 1] = MOD.nav.text({ 'Double-click the ID to open its record; single-click to edit.',
        '双击 ID 跳转到对应记录；单击数值可输入。', '雙擊 ID 跳轉到對應記錄；單擊數值可輸入。' })
    if row.link_only then lines[#lines] = MOD.nav.text({ 'Double-click the ID to open its record (read-only reference).',
        '双击 ID 跳转到对应记录（只读引用）。', '雙擊 ID 跳轉到對應記錄（唯讀引用）。' }) end
    return lines
end
-- the fuse rows' notes (PR #80 by CarbonAnime): a blast proximity works only with the blast angle (+136) at 360
-- (tested in game: the crossbow at 80 and 6 m does not burst in flight, the GL-21 at 360 and 6 m does), and a radius
-- smaller than one step of the round is stepped over
MOD.records.NOTES = {
    angle = '360 fires from any side; with a blast proximity above 0 the round becomes a proximity fuse (measured: 360 and 6 m on the crossbow).',
    weapon_angle = '360 with a proximity above 0: a proximity fuse, off from any side.' }
-- the (?) tips of the fuse rows: what they do (RL-77 Flak 2 m and 0.2 s, the P-34 Breacher's sticky round 1 s)
MOD.records.TIPS = {
    impact = { 'The explosion the round sets off when it hits something. 0: no explosion.' },
    proximity = { 'The round goes off when it passes this close to an enemy, without hitting it. 0: off (the RL-77 uses 2 m).',
                  'Only works with the blast angle at 360, and the distance has to be larger than one step of the round:',
                  'keep it above about speed / frame rate.' },
    delay = { 'How long the round waits after the hit (or after the blast proximity trips) before it goes off.',
              '0: at once. The RL-77 waits 0.2 s, the P-34 Breacher (it sticks and burns first) 1 s.' } }
function MOD.records.ids(kind)
    local ids = {}
    for id in pairs(tables[kind] and tables[kind].index or {}) do
        if type(id) == 'number' and id > 0 then ids[#ids + 1] = id end
    end
    table.sort(ids)
    return ids
end
-- Who uses each record: shots (projectile id -> weapon names), blasts (explosion id -> weapon names), from the
-- weapons' rows (the record a row's field is in) and own shots; rounds (explosion id -> the name of the first named
-- round that sets it off). Built once per resolve.
function MOD.records.users()
    if MOD.records.cache then return MOD.records.cache end
    local shots, blasts, rounds = {}, {}, {}
    local function add(map, id, name)
        if not id or id <= 0 then return end
        local list = map[id] or {}
        map[id] = list
        for _, n in ipairs(list) do if n == name then return end end
        list[#list + 1] = name
    end
    local function locate(kind)
        local spots, stride = {}, KINDS[kind].stride
        for _, id in ipairs(MOD.records.ids(kind)) do spots[#spots + 1] = { at = tables[kind].index[id], id = id } end
        table.sort(spots, function(a, b) return a.at < b.at end)
        return function(offset)
            local lo, hi = 1, #spots
            while lo <= hi do
                local mid = math.floor((lo + hi) / 2)
                local spot = spots[mid]
                if offset < spot.at then hi = mid - 1
                elseif offset >= spot.at + stride then lo = mid + 1
                else return spot.id end
            end
        end
    end
    local shot_at, blast_at = locate(T_PROJECTILE), locate(T_EXPLOSION)
    for _, w in ipairs(weapons) do
        if #w.rows > 0 and not w.name:match('^%(') then   -- not the '(Not Used)' dummies
            for _, shot in ipairs(w.own_shots or {}) do add(shots, shot.id, w.name) end
            for _, row in ipairs(w.rows) do
                for _, q in ipairs(row.parts) do
                    if q.field.kind == T_PROJECTILE then add(shots, shot_at(q.field.offset), w.name)
                    elseif q.field.kind == T_EXPLOSION then add(blasts, blast_at(q.field.offset), w.name) end
                end
            end
        end
    end
    for _, id in ipairs(MOD.records.ids(T_PROJECTILE)) do
        local name, at = MOD.round_names and MOD.round_names[id], tables[T_PROJECTILE].index[id]
        for _, off in ipairs(name and { 144, 156 } or {}) do
            local x = read_field(field_at(T_PROJECTILE, at + off, 'u32', 100000))
            if x and x > 0 and not rounds[x] then rounds[x] = name end
        end
    end
    MOD.records.cache = { shots = shots, blasts = blasts, rounds = rounds }
    return MOD.records.cache
end
-- A record's name (English), or nil.
function MOD.records.name(kind, id)
    local u = MOD.records.users()
    if kind == T_PROJECTILE then return MOD.round_names and MOD.round_names[id] or (u.shots[id] or {})[1]
    elseif kind == T_EXPLOSION then return (u.blasts[id] or {})[1] or u.rounds[id] end
    if kind == T_STATUS then
        if state.lang and state.lang() == 'zh-Hans' and MOD.status.by[id] then return MOD.status.by[id].name end
        return KINDS[T_STATUS].names[id] or KINDS[T_STATUS].stuns[id]or(MOD.status_component and MOD.status_component.name(id))
    end
end
-- A choice's label in a note: '#12 · 10g Sabot' (the name in the panel's language), 'none (no explosion)'.
function MOD.records.label(kind, id)
    local what = kind == T_EXPLOSION and 'explosion' or 'projectile'
    if not id or id <= 0 then return 'none (no ' .. what .. ')' end
    if not (tables[kind] and tables[kind].index[id]) then return what .. ' ' .. id .. ' (not in this game build)' end
    local name = MOD.records.name(kind, id)
    return '#' .. id .. (name and (' · ' .. (state.tr and state.tr(name) or name)) or '')
end
-- The id `n` on from `id` among none (0) and every record of the kind (from either end when `id` is not one).
function MOD.records.step(kind, id, n)
    local list = MOD.records.ids(kind)
    table.insert(list, 1, 0)
    local at = nil
    for k, x in ipairs(list) do if x == id then at = k end end
    at = at or (n > 0 and 0 or #list + 1)
    return list[math.max(1, math.min(#list, at + n))]
end
-- A weapon page's explosion id sections ('Projectile explosion id', ...) last, below its projectile swap.
function MOD.records.ids_last(weapon)
    local rows, last = {}, {}
    for _, row in ipairs(weapon.rows) do
        local list = row.section:find(' explosion id$') and last or rows
        list[#list + 1] = row
    end
    for _, row in ipairs(last) do rows[#rows + 1] = row end
    weapon.rows = rows
end
-- An explosion's shrapnel rows (explosion row `xrow`, ids `pre` ..): the projectile every piece is, then how many.
function MOD.records.shrapnel_rows(entry, section, pre, xrow)
    local piece = add_row(entry, section, pre .. '_projectile', 'Shrapnel projectile (id)', 'u32',
                          { part(pre .. '_projectile', T_EXPLOSION, xrow + 84, 'u32', 100000) }, 0, 100000, 1, 10)
    piece.choice = 'shrapnel'
    piece.note = function()
        local id = read_field(piece.parts[1].field)
        return (id or 0) > 0 and ('each piece is ' .. MOD.records.label(T_PROJECTILE, id)) or 'no shrapnel'
    end
    add_row(entry, section, pre .. '_count', 'Shrapnel pieces', 'u32', { part(pre .. '_count', T_EXPLOSION, xrow + 80, 'u32', 10000) },
            0, 500, 1, 5)
end
-- A record page's rows (page.kind, page.id).
MOD.projectile={schema=require('projectile_components')}
function MOD.projectile.rows(page,at)
    local C=MOD.projectile.schema
    if not C.check_layout((rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE')or{}).schemas)then return nil end
    page.rows={} -- keep the old inline config bindings, without expanding referenced components
    local function emit(row,s,typ)
        local field,off,group=s[1],s[2],s[4]
        row.component='ProjectileType'
        row.component_of=function()return MOD.nav.text({'ProjectileType','射弹类型（ProjectileType）','射彈類型（ProjectileType）'})end
        row.section='ProjectileType:'..group
        row.section_of=function()return MOD.nav.text(C.GROUPS[group])end
        row.label_of=function()return MOD.nav.text({field=='type'and'Projectile ID'or field:gsub('_',' '),s[5],s[6]})end
        row.tip_of=function()
            local lines={field,MOD.nav.text({s[5],s[5],s[6]})..' / '..field,'ProjectileInfo +'..off..' · '..typ}
            if group=='unknown'then lines[#lines+1]=MOD.nav.text({'Meaning unknown; named by offset in the reference export.','含义尚未确认；按参考文件中的偏移命名。','含義尚未確認；按參考檔案中的偏移命名。'})end
            if field=='status_effect_volume_template'or field=='effect_damage_type'then lines[#lines+1]=MOD.nav.text({
                'Template/effect enum, not a status-effect or damage record ID.','这是模板/特效枚举，不是状态效果或伤害记录 ID。','這是範本/特效列舉，不是狀態效果或傷害記錄 ID。'})end
            return lines
        end
        return row
    end
    for _,s in ipairs(C.FIELDS)do
        local name,off,storage,id=s[1],s[2],s[3],s[7]or s[1]:gsub('%.','_')
        local row
        if storage=='id'then
            row=MOD.references.row(page,'Projectile',id,'Projectile ID',T_PROJECTILE,at+off,'projectile_id')
        elseif storage=='u64' then
            local parts={part(id..'_lo',T_PROJECTILE,at+off,'u32',4294967295),part(id..'_hi',T_PROJECTILE,at+off+4,'u32',4294967295)}
            for _,p in ipairs(parts)do p.field.limit=4294967295 end
            row=add_row(page,'Projectile',id,name,'u64',parts,0,4294967295,1,1)
            row.hash64,row.lead=true,true
        else
            local p=part(id,T_PROJECTILE,at+off,storage,storage=='f32'and 1e12 or storage:match('^bit')and 1 or 4294967295)
            p.field.limit=storage=='f32'and 1e12 or storage:match('^bit')and 1 or 4294967295
            local signed=storage=='f32'and(s[4]=='unknown'or s[4]=='attachment'or name=='gravity_multiplier')
            if signed then p.field.signed=true end
            local value=read_field(p.field)or 0
            local max=storage=='u16'and 65535 or storage=='u8'and 255 or storage:match('^bit')and 1 or storage=='f32'and 1e9 or 4294967295
            row=add_row(page,'Projectile',id,name,p.field.storage,{p},math.min(signed and -1e9 or 0,value),math.max(max,value),storage=='f32'and .1 or 1,storage=='f32'and 1 or 10)
            if s[8]then
                row.reference_type,row.choice=s[8],'reference'
                local kind=MOD.references.KINDS[s[8]]
                p.field.allowed=setmetatable({[0]=true,[value]=true,why='No matching record in this game build.'},{__index=function(_,target)
                    return tables[kind]and tables[kind].index[target]~=nil
                end})
            end
        end
        emit(row,s,storage=='u64'and'uint64 (exact decimal)'or storage)
        if name=='projectile_flags_1'or name=='projectile_flags_2'then
            for _,b in ipairs(C.BITS)do if b[2]==off then
                local flag=add_row(page,'Projectile',b[1],b[1],'flag',{},0,1,1,1)
                flag.parts={{id=id,field=row.parts[1].field,row=flag}}
                flag.packed_flag=2^b[3]
                emit(flag,{b[1],b[2],nil,b[4],b[5],b[6]},'bit '..b[3]..' of '..storage)
            end end
        end
    end
    require('typeid_groups').sort(C,page.rows)
    return true
end
MOD.explosion={schema=require('explosion_components')}
function MOD.explosion.shakes(at)
    local t=tables[T_EXPLOSION]
    if not t then return nil,nil,'table unavailable'end
    local base=t.copies[1]+HEADER_BYTES
    local lo,hi,count,pad=peek4(base+at+40),peek4(base+at+44),peek4(base+at+48),peek4(base+at+52)
    if not(lo and hi and count and pad)or count>4096 or pad~=0 then return nil,nil,'invalid array count'end
    if count==0 then return 0,0 end
    local target=lo+hi*4294967296
    if target>=t.payload then target=target-base end
    local records=peek4(base+8)
    if not records or target<16+records*152 or target+count*8>t.payload then return nil,nil,'array outside table'end
    return target,count
end
function MOD.explosion.rows(page,at)
    local C=MOD.explosion.schema
    if not C.check_layout((rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE')or{}).schemas)then return nil end
    page.rows={}
    local function emit(row,s,typ)
        local field,off,group=s[1],s[2],s[4]
        row.component='ExplosionType'
        row.component_of=function()return MOD.nav.text({'ExplosionType','爆炸类型（ExplosionType）','爆炸類型（ExplosionType）'})end
        row.section='ExplosionType:'..group
        row.section_of=function()return MOD.nav.text(C.GROUPS[group])end
        row.label_of=function()return MOD.nav.text({field=='type'and'Explosion ID'or field=='shake_assets'and'Camera shake asset count'or field:gsub('_',' '),s[5],s[6]})end
        row.tip_of=function()
            local lines={field,MOD.nav.text({s[5],s[5],s[6]})..' / '..field,'ExplosionInfo +'..off..' · '..typ}
            if group=='unknown'or field:match('^unk_')then lines[#lines+1]=MOD.nav.text({'Meaning unknown; current type-library offset and storage verified.','含义尚未确认；已核对当前类型库的偏移和存储类型。','含義尚未確認；已核對目前型別庫的偏移與儲存型別。'})end
            if field=='persistent_status_volume'or field=='hit_effect_damage_type'then lines[#lines+1]=MOD.nav.text({
                'Template/effect enum, not a status-effect or damage record ID.','这是模板/特效枚举，不是状态效果或伤害记录 ID。','這是範本/特效列舉，不是狀態效果或傷害記錄 ID。'})end
            return lines
        end
        return row
    end
    local function hash(s,offset,id,typ)
        local parts={part(id..'_lo',T_EXPLOSION,offset,'u32',4294967295),part(id..'_hi',T_EXPLOSION,offset+4,'u32',4294967295)}
        for _,p in ipairs(parts)do p.field.limit=4294967295 end
        local row=add_row(page,'Explosion',id,s[1],'u64',parts,0,4294967295,1,1)
        row.hash64,row.lead=true,true
        return emit(row,s,typ or'uint64 (exact decimal)')
    end
    for _,s in ipairs(C.FIELDS)do
        local name,off,storage,id=s[1],s[2],s[3],s[7]or s[1]
        if storage=='array'then
            local target,count,why=MOD.explosion.shakes(at)
            local row=emit(add_row(page,'Explosion',id,name,'u32',{},0,0,1,1),s,'array<uint64>; count read-only')
            row.empty=true;row.readonly_text=count and tostring(count)or('('..tostring(why)..')')
            for i=1,count or 0 do
                hash({'shake_assets['..i..']',40,'u64','shake','震屏资源 '..i..' 哈希','震屏資源 '..i..' 雜湊'},target+(i-1)*8,
                    'shake_asset_'..i,'array<uint64> element; payload +'..(target+(i-1)*8)..' (exact decimal)')
            end
        elseif storage=='u64' then hash(s,at+off,id)
        else
            local row
            if storage=='id'then row=MOD.references.row(page,'Explosion',id,'Explosion ID',T_EXPLOSION,at+off,'explosion_id')
            else
                local limit=storage=='f32'and 1e12 or storage=='i8'and 128 or storage:match('^bit')and 1 or 4294967295
                local p=part(id,T_EXPLOSION,at+off,storage,limit);p.field.limit=limit
                local signed=storage=='f32'or storage=='i8'
                if signed then p.field.signed=true end
                local value=read_field(p.field)or 0
                local max=storage=='i8'and 127 or storage=='u8'and 255 or storage:match('^bit')and 1 or storage=='f32'and 1e9 or 4294967295
                local min=storage=='i8'and -128 or storage=='f32'and s[4]=='unknown'and -1e9 or 0
                row=add_row(page,'Explosion',id,name,p.field.storage,{p},math.min(min,value),math.max(max,value),storage=='f32'and .1 or 1,storage=='f32'and 1 or 10)
                if s[8]then
                    row.reference_type,row.choice=s[8],'reference'
                    local kind=MOD.references.KINDS[s[8]]
                    p.field.allowed=setmetatable({[0]=true,[value]=true,why='No matching record in this game build.'},{__index=function(_,target)
                        return tables[kind]and tables[kind].index[target]~=nil
                    end})
                end
            end
            emit(row,s,storage)
            for _,b in ipairs(C.BITS)do if b[2]==off then
                local flag=add_row(page,'Explosion',b[1],b[1],'flag',{},0,1,1,1)
                flag.parts={{id=id,field=row.parts[1].field,row=flag}};flag.packed_flag=2^b[3]
                emit(flag,{b[1],b[2],nil,b[4],b[5],b[6]},'bit '..b[3]..' of uint8')
            end end
        end
    end
    require('typeid_groups').sort(C,page.rows)
    return true
end
