            if name=='explosion_effect_path'then lines[#lines+1]=MOD.nav.text({'Particle resource hash, not an explosion record ID.','这是粒子特效资源哈希，不是爆炸记录 ID。','這是粒子特效資源雜湊，不是爆炸記錄 ID。'})end
