            if off>=16 and off<=36 then lines[#lines+1]=MOD.nav.text({'The old focal_shoulder_width has no unique mapping to these six current floats.','旧版 focal_shoulder_width 无法唯一映射到这六个新版浮点字段。','舊版 focal_shoulder_width 無法唯一映射到這六個新版浮點欄位。'})end
            return lines
        end
    end
    require('typeid_groups').sort(C,page.rows)
    return true
end
MOD.status_component={schema=require('status_components')}
function MOD.status_component.position(at,off,size)
    local t=tables[T_STATUS];local base=t and t.copies[1]+HEADER_BYTES
    if not base then return nil,'table unavailable'end
    local lo,hi=peek4(base+at+off),peek4(base+at+off+4)
    if not(lo and hi)then return nil,'pointer unavailable'end
    if lo==0 and hi==0 then return nil,'empty pointer'end
    local target=lo+hi*4294967296
    if target>=t.payload then target=target-base end
    local records=peek4(base+8)
    if not records or target<16+records*160 or target+size>t.payload then return nil,'pointer outside table'end
    return target
end
function MOD.status_component.debug_name(at)
    local pos,why=MOD.status_component.position(at,8,1)
    if not pos then return why=='empty pointer'and''or nil,why end
    local t=tables[T_STATUS]
    local text=api.read(t.copies[1]+HEADER_BYTES+pos,math.min(1024,t.payload-pos))
    return text and text:match('^([^%z]*)%z')or nil,'unterminated string'
end
function MOD.status_component.name(id)
    if not MOD.status_component.schema.check_layout((rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE')or{}).schemas)then return nil end
    local t=tables[T_STATUS];local at=t and t.index[id]
    local text=at and MOD.status_component.debug_name(at)
    return text and text~=''and text or nil
end
function MOD.status_component.array(at,desc)
    local t=tables[T_STATUS];local base=t and t.copies[1]+HEADER_BYTES
    if not base then return nil,nil,'table unavailable'end
    local n,pad=peek4(base+at+desc.offset+8),peek4(base+at+desc.offset+12)
    if not n or n>4096 or pad~=0 then return nil,nil,'invalid array count'end
    if n==0 then return 0,0 end
    local pos,why=MOD.status_component.position(at,desc.offset,n*desc.stride)
    if not pos then return nil,nil,why end
    return pos,n
end
function MOD.status_component.rows(page,at)
    local C=MOD.status_component.schema
    if not C.check_layout((rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE')or{}).schemas)then return nil end
    page.rows={}
    local function emit(row,s,typ)
        row.component='StatusEffectType'
        row.component_of=function()return MOD.nav.text({'StatusEffectType','状态效果类型（StatusEffectType）','狀態效果類型（StatusEffectType）'})end
        row.section='StatusEffectType:'..s[4]
        row.section_of=function()return MOD.nav.text(C.GROUPS[s[4]])end
        row.label_of=function()return MOD.nav.text({s[1]=='type'and'Status effect ID'or s[1]=='damage_info_type'and'Damage ID'or s[1]:gsub('_',' '),s[5],s[6]})end
        row.tip_of=function()
            local lines={s[1],MOD.nav.text({s[5],s[5],s[6]})..' / '..s[1],'StatusEffectInfo +'..s[2]..' · '..typ}
            if s[4]=='unknown'then lines[#lines+1]=MOD.nav.text({'Meaning unknown; current record and nested layouts verified.','含义尚未确认；已核对当前记录及嵌套结构。','含義尚未確認；已核對目前記錄及巢狀結構。'})end
            return lines
        end
        return row
    end
    local function scalar(s,offset,id,typ)
        local storage=s[3];local row
        if storage=='u64'then
            local parts={part(id..'_lo',T_STATUS,offset,'u32',4294967295),part(id..'_hi',T_STATUS,offset+4,'u32',4294967295)}
            for _,p in ipairs(parts)do p.field.limit=4294967295 end
            row=add_row(page,'Status',id,s[1],'u64',parts,0,4294967295,1,1);row.hash64,row.lead=true,true
        else
            local limit=storage=='f32'and 1e12 or storage:match('^bit')and 1 or 4294967295
            local p=part(id,T_STATUS,offset,storage,limit);p.field.limit=limit
            if storage=='f32'then p.field.signed=true end
            local value=read_field(p.field)or 0
            local max=storage=='u8'and 255 or storage:match('^bit')and 1 or storage=='f32'and 1e9 or 4294967295
            local min=storage=='f32'and(s[4]=='unknown'or s[4]=='modifiers')and -1e9 or 0
            row=add_row(page,'Status',id,s[1],p.field.storage,{p},math.min(min,value),math.max(max,value),storage=='f32'and .1 or 1,storage=='f32'and 1 or 10)
            if s[8]then
                row.reference_type,row.choice=s[8],'reference';local kind=MOD.references.KINDS[s[8]]
                p.field.allowed=setmetatable({[0]=true,[value]=true,why='No matching record in this game build.'},{__index=function(_,target)
                    return tables[kind]and tables[kind].index[target]~=nil
                end})
            end
        end
        return emit(row,s,typ or(storage=='u64'and'uint64 (exact decimal)'or storage))
    end
    for _,s in ipairs(C.FIELDS)do
        local name,off,storage,id=s[1],s[2],s[3],s[7]or s[1]
        if storage=='id'then emit(MOD.references.row(page,'Status',id,'Status effect ID',T_STATUS,at,'status_effect_id'),s,'StatusEffectType (read-only)')
        elseif storage=='string'then
            local row=emit(add_row(page,'Status',id,name,'u32',{},0,0,1,1),s,'UTF-8 string; read-only')
            row.empty=true;row.readonly_text=function()local text,why=MOD.status_component.debug_name(at);return text or'('..tostring(why)..')'end
        elseif storage=='array'then
            local desc;for _,a in ipairs(C.ARRAYS)do if a.offset==off then desc=a;break end end
            local pos,n,why=MOD.status_component.array(at,desc)
            local row=emit(add_row(page,'Status',id..'_count',name,'u32',{},0,0,1,1),s,'array; count read-only')
            row.empty=true;row.readonly_text=n and tostring(n)or'('..tostring(why)..')'
            for i=1,n or 0 do for _,child in ipairs(desc.fields)do
                local field=name..'['..i..'].'..child[1]
                local prefix=off==112 and{'属性倍率 '..i..'：','屬性倍率 '..i..'：'}or{'未知项 '..i..'：','未知項 '..i..'：'}
                scalar({field,off,child[3],s[4],prefix[1]..child[4],prefix[2]..child[5]},pos+(i-1)*desc.stride+child[2],
                    name..'_'..i..'_'..child[1],'array element +'..child[2]..'; '..child[3]..'; payload +'..(pos+(i-1)*desc.stride+child[2]))
            end end
        else
            local row=scalar(s,at+off,id)
            if off==104 then for _,b in ipairs(C.BITS)do
                local flag=add_row(page,'Status',b[1],b[1],'flag',{},0,1,1,1)
                flag.parts={{id=id,field=row.parts[1].field,row=flag}};flag.packed_flag=2^b[3]
                emit(flag,{b[1],104,nil,b[4],b[5],b[6]},'bit '..b[3]..' of uint8')
            end end
        end
    end
    require('typeid_groups').sort(C,page.rows)
    return true
end
function MOD.records.rows(page)
    if page.stratagem_type then
        page.rows,page.by_id={},{}
        page.rows=MOD.stratagem.rows(page,page.def)or{}
        return
    end
    local kind, at = page.kind, tables[page.kind] and tables[page.kind].index[page.id]
    page.rows, page.by_id, page.hidden_rows = {}, {}, nil
    if not at then return end
    local function num(section, id, label, off, storage, max, small, big)
        return add_row(page, section, id, label, storage, { part(id, kind, at + off, storage, 100000) }, 0, max, small, big)
    end
    local function hurt(off, section, what, count)
        local d = read_field(field_at(kind, at + off, 'u32', 100000))
        local drow = d and d > 0 and tables[T_DAMAGE] and tables[T_DAMAGE].index[d]
        if not drow or not MOD.damage.enabled(page)then MOD.references.row(page, section, 'damage_ref', 'Damage ID', kind, at + off, 'damage_id')end
        if not drow then return end
        damage_rows(page, section, '', drow, what, count)
        if count == nil then status_rows(page, section, '', drow, what == 'Explosion' and 'blast' or 'hit') end
    end
    if kind == T_PROJECTILE then
        for _, r in ipairs({ { 'calibre', 'Calibre (mm)', 24, 'f32', 1000, 0.1, 1 }, { 'pellets', 'Projectiles per shot', 28, 'u32', 200, 1, 5 },
                             { 'velocity', 'Velocity (m/s)', 32, 'f32', 100000, 10, 100 }, { 'mass', 'Mass (kg)', 36, 'f32', 10000, 0.1, 1 },
                             { 'drag', 'Drag factor', 40, 'f32', 100, 0.05, 0.5 }, { 'gravity', 'Gravity factor', 44, 'f32', 100, 0.05, 0.5 },
                             { 'lifetime', 'Lifetime (s)', 56, 'f32', 1000, 0.1, 1 },
                             { 'pen_slowdown', 'Penetration slowdown', 64, 'f32', 100, 0.05, 0.25 } }) do
            num('Projectile', r[1], r[2], r[3], r[4], r[5], r[6], r[7])
        end
        hurt(60, 'Damage')
        local impact = add_row(page, 'Explosion id', 'impact_explosion', 'Impact explosion (id)', 'u32',
                               { part('impact_explosion', kind, at + 144, 'u32', 100000) }, 0, 100000, 1, 10)
        impact.choice = 'explosion'
        impact.note = function()
            return 'sets off: ' .. MOD.records.label(T_EXPLOSION, read_field(impact.parts[1].field))
        end
        impact.tip = MOD.records.TIPS.impact
        num('Explosion id', 'fuse_proximity', 'Blast proximity (m)', 148, 'f32', 200, 0.1, 1).tip = MOD.records.TIPS.proximity
        num('Explosion id', 'fuse_delay', 'Blast delay (s)', 152, 'f32', 30, 0.05, 0.5).tip = MOD.records.TIPS.delay
        local expiry = add_row(page, 'Explosion id', 'expiry_explosion', 'Expiry explosion (id)', 'u32',
                               { part('expiry_explosion', kind, at + 156, 'u32', 100000) }, 0, 100000, 1, 10)
        expiry.choice = 'explosion'
        num('Explosion id', 'arming', 'Arming distance (m)', 160, 'f32', 200, 0.1, 1)
        num('Explosion id', 'blast_angle', 'Blast angle (deg)', 136, 'f32', 360, 1, 10).note = MOD.records.NOTES.angle
    elseif kind == T_EXPLOSION then
        hurt(4, 'Explosion', 'Explosion')
        for _, r in ipairs({ { 'inner', 'Inner radius (m)', 16 }, { 'outer', 'Outer radius (m)', 20 },
                             { 'shockwave', 'Shockwave radius (m)', 24 } }) do
            num('Radius', r[1], r[2], r[3], 'f32', 200, 0.1, 1)
        end
        num('Shape', 'cone', 'Cone angle (deg)', 28, 'f32', 360, 1, 10)
        num('Shape', 'shake', 'Camera shake radius (m)', 32, 'f32', 200, 0.1, 1)
        MOD.records.shrapnel_rows(page, 'Shrapnel', 'shrapnel', at)
        MOD.references.row(page, 'Arc', 'arc_ref', 'Arc ID', kind, at + 120, 'arc_id')
    elseif kind == T_DAMAGE then
        damage_rows(page, 'Damage', '', at)
        local own_rows = #page.rows
        status_rows(page, 'Damage', '', at, 'hit')
        if MOD.damage.enabled(page)then
            -- Keep old config/preset bindings, while the ID page displays only its own component.
            for i=#page.rows,own_rows+1,-1 do table.remove(page.rows)end
        end
    elseif kind == TYPES.arc then
        hurt(36, 'Damage', 'Arc')
        num('Arc', 'arc_range', 'Range (m)', 8, 'f32', 1000, 1, 5)
        num('Arc', 'arc_chain', 'Chain length', 28, 'u32', 20, 1, 1)
        num('Arc', 'arc_split', 'Chain split', 32, 'u32', 20, 1, 1)
    elseif kind == T_BEAM then
        hurt(12, 'Damage')
    elseif kind == T_STATUS then
        local name = MOD.records.name(kind, page.id) or 'Status'
        hurt(44, name, name, 6)   -- no forces: a status has none
        num(name, 'duration', name .. ' duration (s)', 40, 'f32', 600, 0.5, 5)
    end
    if kind==T_PROJECTILE then MOD.projectile.rows(page,at)end
    if kind==T_EXPLOSION then MOD.explosion.rows(page,at)end
    if kind==TYPES.arc then MOD.arc.rows(page,at)end
    if kind==T_BEAM then MOD.beam.rows(page,at)end
    if kind==T_STATUS then MOD.status_component.rows(page,at)end
end
-- An unnamed record still needs something readable beside its number. Use the loaded
-- values as a description, without claiming to know which weapon or effect it belongs to.
function MOD.records.unnamed(page)
    local function value(id)
        local part = page.by_id[id]
        local v = part and default_of(part.field)
        return v and v == v and math.abs(v) < math.huge and v or nil
    end
    if page.kind == T_PROJECTILE then
        local calibre, damage, durable = value('calibre'), value('damage'), value('durable')
        if calibre and damage and durable then
            return string.format('Unnamed: %gmm; %g/%g damage', calibre, damage, durable)
        end
        return 'Unnamed projectile'
    elseif page.kind == T_EXPLOSION then
        local outer = value('outer')
        if outer then return string.format('Unnamed: %gm blast', outer) end
        return 'Unnamed explosion'
    end
    if page.kind ~= T_STATUS then return 'Unnamed ' .. MOD.records.WORD[page.kind]:lower() end
    local duration = value('duration')
    return duration and string.format('Unnamed: %gs effect', duration) or 'Unnamed status effect'
end

-- A record page's title and note: 'Projectile #12 · 10g Sabot', 'Fired by: ...'.
function MOD.records.title(page)
    if page.stratagem_type then return end
    local name = MOD.records.name(page.kind, page.id)
    local old = page.kind == T_PROJECTILE or page.kind == T_EXPLOSION or page.kind == T_STATUS
    if old and not name and state.lang and state.lang() == 'zh-Hans' then name = MOD.records.unnamed(page) end
    local word = MOD.records.WORD[page.kind]
    if not old then word = MOD.nav.text(({
        [T_DAMAGE]={'Damage','伤害','傷害'}, [TYPES.arc]={'Arc','电弧','電弧'}, [T_BEAM]={'Beam','激光','激光'}
    })[page.kind]) end
    page.name = word .. ' #' .. page.id .. (name and (' · ' .. name) or '')
    local u = MOD.records.users()
    local users = page.kind == T_PROJECTILE and u.shots[page.id] or page.kind == T_EXPLOSION and u.blasts[page.id]
    if not old then page.note = MOD.nav.text({ 'Record type: ', '记录类型：', '記錄類型：' }) .. word .. ' #' .. page.id
    elseif page.kind == T_STATUS then page.note = ''
    elseif not users then page.note = 'Not used by any weapon or stratagem in this list.'
    else
        page.note = (page.kind == T_PROJECTILE and 'Fired by: ' or 'Set off by: ') .. table.concat(users, ', ', 1, math.min(3, #users)) ..
                    (#users > 3 and (', +' .. (#users - 3)) or '')
    end
end
-- The page of a record (built on first use; hash: 'F1' projectile / 'F2' explosion / 'F3' status + 14 hex digits).
function MOD.records.page(kind, id)
    local hash = string.format('%s%014X', MOD.records.PREFIX[kind], id)
    local page = MOD.records.pages[hash]
    if page then return page end
    if not (tables[kind] and tables[kind].index[id]) then return nil end
    page = { slot = 'Records', hash = hash, kind = kind, id = id, record = true }
    MOD.records.rows(page)
    MOD.records.title(page)
    MOD.records.pages[hash] = page
    return page
end
function MOD.records.find(hash)
    if type(hash) ~= 'string' or #hash ~= 16 then return nil end
    if MOD.component_records and MOD.component_records.pages[hash]then return MOD.component_records.pages[hash]end
    if hash:sub(1,2)=='F7'and hash:sub(3):match('^%x+$')then return MOD.stratagem.page(tonumber(hash:sub(3),16))end
    local mark, digits = hash:match('^(F[123456])(%x+)$')
    if not mark then return nil end
    for kind, prefix in pairs(MOD.records.PREFIX) do
        if prefix == mark then return MOD.records.page(kind, tonumber(digits, 16)) end
    end
end
-- Every record page, projectiles, explosions then statuses, by id (the Records tab; built when first opened).
function MOD.records.all()
    if MOD.records.list then return MOD.records.list end
    local list = {}
    for _, kind in ipairs(MOD.records.KINDS) do
        for _, id in ipairs(MOD.records.ids(kind)) do
            local page = MOD.records.page(kind, id)
            if page and #page.rows > 0 then list[#list + 1] = page end
        end
    end
    for _,page in ipairs(MOD.stratagem.all())do list[#list+1]=page end
    MOD.records.list = list
    return list
end
-- After every resolve: who uses what again, and the pages built so far read again (a rescan moves the tables).
function MOD.records.refresh()
    MOD.records.cache, MOD.records.list = nil, nil
    MOD.stratagem.list=nil
    for _,page in pairs(MOD.stratagem.pages)do page.stale=true;MOD.stratagem.page(page.id)end
    for _, page in pairs(MOD.records.pages) do
        MOD.records.rows(page)
        MOD.records.title(page)
    end
end
-- a record page's values saved in config.txt or a preset: its page, built when first named
setmetatable(by_hash, { __index = function(_, hash) return MOD.records.find(hash) end })

-- ProjectileWeaponComponent +40 is a full 64-bit entity reference. Keep both
-- halves together through read/write/reset/presets; a Lua number cannot hold the hash.
-- Use the grenade entity and native release/activation lifecycle. Special grenade
-- behaviors still require gameplay validation; reference writes alone are insufficient.
KINDS[TYPES.throwable].grenade_row = function(weapon, fire)
    local spec = KINDS[TYPES.throwable]
    -- (offline: no row; a swapped grenade needs its assets loaded by the running game)
    if MOD.offline or not fire or not spec.grenade_hosts[weapon.hash] then return end
    local f = field_at(T_FIRE, fire + 40, 'grenade', #spec.grenade_hashes)
    if default_of(f) == nil then
        log('grenade swap: unknown original entity on ' .. weapon.name)
        return
    end
    spec.fields = spec.fields or {}
    spec.fields[f.key] = f
    local row = add_row(weapon, 'Grenade swap', 'grenade', 'Grenade fired (choice)', 'u32',
                        { { id = 'grenade', field = f } }, 0, #spec.grenade_hashes, 1, 10)
    row.choice = 'grenade'
    weapon.grenade_swap = row
    row.note = function()
        local id = f.pending_value or read_field(f)
        local shot = spec.by_id[id]
        return (f.pending_value and 'loading: ' or 'fires: ') .. (shot and shot.label or 'normal projectile')
    end
    row.after = { '0 = normal projectile; - / + selects a throwable grenade by name above.',
                  'Grenade selection takes priority over Projectile swap. Fire rate, ammo and handling stay.',
                  'Edit the grenade on Throwables to tune it. Assets load before selection applies.',
                  'Throwable launching is supported in solo missions only.' }
    row.after_h = #row.after * 16 + 6
end

-- Resolves weapons from `next` on until the deadline; true once all are done.
local function resolve_some(progress, deadline)
    if progress.next == 1 then
        for _, f in pairs(fields) do f.users = {} end
        KINDS[TYPES.custom].cache = {}
        KINDS[TYPES.throwable].prepare_grenades()
    end
    while progress.next <= #weapons do
        resolve(weapons[progress.next])
        MOD.records.ids_last(weapons[progress.next])
        progress.next = progress.next + 1
        if api.now() >= deadline then break end
    end
    if progress.next <= #weapons then return false end
    KINDS[T_PROJECTILE].list_choices()
    MOD.records.refresh()
    local usable, strats = 0, 0
    state.attachments, state.throwables, state.passives, state.vehicles = 0, 0, 0, 0
    for _, weapon in ipairs(weapons) do
        if #weapon.rows > 0 then
            if weapon.stratagem and weapon.stratagem.vehicle then state.vehicles = state.vehicles + 1
            elseif weapon.stratagem or weapon.mounted or weapon.orbital_beam then strats = strats + ((weapon.mounted or weapon.orbital_beam) and 0 or 1)
            elseif weapon.attachment then state.attachments = (state.attachments or 0) + 1
            elseif weapon.slot == 'Throwables' then state.throwables = (state.throwables or 0) + 1
            elseif weapon.passive then state.passives = state.passives + 1
            else usable = usable + 1 end
        end
    end
    state.weapons, state.stratagems = usable, strats
    return true
end

-- Other weapons whose values change along with this row.
local function shared_with(weapon, row)
    if weapon.component_entry then return{}end
    local names, seen = {}, { [weapon] = true }
    if weapon.health_component or weapon.drown_component or weapon.shield_component or weapon.component_view then
        for _,p in ipairs(row.parts)do if p.health_owner then seen[p.health_owner.weapon]=true end end
    end
    for _, p in ipairs(row.parts) do
        for _, other in ipairs(p.field.users) do
            if not seen[other] and not other.component_entry and not other.health_component and not other.drown_component and not other.shield_component and not other.component_view and (weapon.record or not other.record) then seen[other] = true; names[#names + 1] = other.name end
        end
    end
    return names
end

-- A time row (row.span) holds a rate; it shows and takes span / rate seconds.
local function as_time(span, rate)
    if span == nil or rate == nil or rate <= 0 then return nil end
    return span / rate
end

-- A row's value (the mean of its parts); default = true: the game's own value instead.
local function row_value(row, default)
    if row.custom_value then return row.custom_value(default)end
    if row.empty then return nil end   -- (a document's field the editor has no stat for)
    if row.button_slot then
        local value=(default and default_of or read_field)(row.parts[1].field)
        return (MOD.code.arrows(value)or{})[row.button_slot]or 0
    end
    if row.reference_value then return row.reference_value() end
    if not row.parts or #row.parts==0 then return nil end
    local get = default and default_of or read_field
    if row.packed_flag then
        local v=get(row.parts[1].field)
        return v and math.floor(v/row.packed_flag)%2 or nil
    end
    if row.choice == 'grenade' and not default and row.parts[1].field.pending_value ~= nil then
        return row.parts[1].field.pending_value
    end
    if row.choice and MOD.choice_value[row.choice] then return MOD.choice_value[row.choice](row, default) end
    if row.choice or row.lead then   -- lead: the others scale with it
        local v = get(row.parts[1].field)
        return (v and row.scale) and v * row.scale + 0 or v
    end
    if row.span then
        local rate = get(row.parts[1].field)
        if row.never and rate == 0 then return 0 end   -- (a drain of 0: shown as Never)
        return as_time((default and row.span_default or row.span)(), rate and rate + (row.rate_plus or 0))
    end
    local sum = 0
    for _, p in ipairs(row.parts) do
        local v = get(p.field)
        if v == nil then return nil end
        sum = sum + v
    end
    if row.zero and sum == 0 then return row.zero end   -- 0 stands for that (a reload played as animated)
    return sum / #row.parts * (row.scale or 1) + 0   -- (+ 0: no -0 shown)
end

-- ---------------------------------------------------------------- config
-- One line per changed value: <weapon hash> <stat> <value>   # weapon name
-- plus `hotkey <key>`. Written after every change, read once at start.
local overrides = {}    -- list of { hash, id, value }
local hotkey_name = 'F8'
local config_dirty_at = nil
-- The Settings page's choices, saved in config.txt with the changes. changes: apply the changes
-- (off: every value is the game's, the changes are kept); block_input: the game gets no keyboard /
-- mouse input while the panel is open; size: panel height, % of the screen's; side: 'left' / 'right';
-- opacity: background, %; last: the tab and page each editor was left on (reopened there; 'stat' / 'enemy'),
-- enemy_last: the editor left in; lang: the panel's language, 'en'
-- or the id of a translation: fixed by the build (a language's release, MOD.lang), not a choice; offline (every
-- language built in) a choice, saved as 'lang'; cache_clear_on_exit: drop the changes the editor keeps between
-- runs when it closes (off: they stay, as before).
local settings = { changes = true, block_input = true, size = 80, side = 'right', opacity = 90,
                   component_show_missing = true, component_category = 'all', weapon_category = 'all', enemy_category = 'all',
                   arc_mp = true, updates = 'ask', update_channel = 'releases', cache_clear_on_exit = false,
                   stacks = {}, own_off = {}, hidden = {}, lang = MOD.lang or MOD.offline and rawget(_G, 'SHODAN_OFFLINE_LANG') or 'en',
                   last = { stat = {}, enemy = {} }, enemy_last = false,
                   -- the settings page's two links: this fork, then the original it is built on
                   FORK = 'https://github.com/Thodmcniujiao/SHODAN-Stat-Editor',
                   GITHUB = 'https://github.com/SHODAN-HORAI/SHODAN-Stat-Editor',
                   -- offline (bottom-right Settings): font_px, the body text's size in panel pixels (16: as designed; the
                   -- rest of the text follows); render_height, the resolution drawn at (pixels high, 0: the window's own)
                   font_px = 16, render_height = 0,
                   RANGE = { size = { 50, 100 }, opacity = { 10, 100 }, font_px = { 10, 28 }, render_height = { 360, 4320 } } }

-- Translations (MOD.langs, built from lang/*.json): the panel's text by its English text, so every
-- branch still runs on English and config.txt / presets stay the same in every language. A lookup:
-- exact (and lower, the lowercased names sentences carry), '* ' + exact (a changed item), whole-sentence
-- patterns (numbers and names built at run time; %1-%4 are translated again, %L1 a ', ' list of them),
-- then prefix and suffix.
-- Each text is looked up once per language (the panel redraws often).
do
    local LANG = {}
    for _, l in ipairs(MOD.langs or {}) do   -- and by the upper / lower case English ('DAMAGE', sentences)
        LANG[l.id], l.upper = l, {}
        for e, t in pairs(l.exact) do
            l.upper[e:upper()] = l.upper[e:upper()] or t
            l.lower[e:lower()] = l.lower[e:lower()] or t
        end
    end
    settings.LANGS = LANG
    local tr_cache, tr_count = {}, 0
    local function translate(v, depth)
        local l = LANG[settings.lang]
        if not l or depth > (settings.lang == 'zh-Hans' and 6 or 3) then return v end
        local t = l.exact[v] or l.lower[v] or l.upper[v] or (settings.lang == 'zh-Hans' and l.lower[v:lower()])
        if t then return t end
        if v:sub(1, 2) == '* ' and l.exact[v:sub(3)] then return '* ' .. l.exact[v:sub(3)] end
        for _, p in ipairs(l.patterns) do
            local caps = { v:match(p[1]) }
            if caps[1] then
                return (p[2]:gsub('%%(L?)([1-9])', function(list, k)
                    local x = caps[tonumber(k)]
                    if not x or x == '' then return '' end
                    if list == '' then return translate(x, depth + 1) end
                    local out = {}   -- %L1: a ', ' list of names, each translated
                    for name in (x .. ', '):gmatch('(.-), ') do out[#out + 1] = translate(name, depth + 1) end
                    return table.concat(out, l.list or ', ')
                end))
            end
        end
        for _, p in ipairs(l.prefix) do
            if v:sub(1, #p[1]) == p[1] then v = p[2] .. v:sub(#p[1] + 1); break end
        end
        for _, p in ipairs(l.suffix) do
            if #v > #p[1] and v:sub(-#p[1]) == p[1] then return v:sub(1, #v - #p[1]) .. p[2] end
        end
        return v
    end
    if MOD.offline then   -- for the host's own text and fonts
        state.tr = function(v) return settings.tr(v) end
        state.lang = function() return settings.lang end
        state.updates = function() return settings.updates end   -- the host's updater: 'ask' or 'auto'
        state.update_channel = function() return settings.update_channel end   -- 'releases' or 'commits'
        state.stacks = function() return settings.stacks end   -- passive id -> { passive ids stacked on it }
        state.own_off = function() return settings.own_off end -- passive id -> true: its own effects left out
        state.entity_demolition_enabled = function() return settings.changes end
        state.preload_touch=function()state.writes=state.writes+1 end
        state.demolition_labels = function()
            local out = {}
            for _, w in ipairs(weapons) do
                if w.key and #w.key == 8 then out[string.format('%08X%08X', u32(w.key, 4), u32(w.key, 0))] = w.name end
            end
            return out
        end
        -- stratagem type -> { arrow, ... }: every call-in code set here (hostdata.lua M.codes writes them)
        state.codes = function()
            local out = {}
            for _, f in pairs(fields) do
                if f.def and f.storage == 'virtual' and f.value ~= nil and f.value ~= f.default then
                    local arrows, t = MOD.code.arrows(f.value), peek4(f.def.at)
                    if arrows and t then out[t] = arrows end
                end
            end
            return out
        end
    end
    function settings.tr(v)
        if MOD.planet.labels[v]then return require('component_view').pick(settings.lang,MOD.planet.labels[v])end
        local planet_name=MOD.planet.translate_name(v,settings.lang);if planet_name then return planet_name end
        local spawn_name=require('spawn_components').translate_name(v,settings.lang);if spawn_name then return spawn_name end
        if MOD.enemy.LABELS and MOD.enemy.LABELS[v]then return MOD.nav.text(MOD.enemy.LABELS[v])end
        if MOD.preload.labels and MOD.preload.labels[v]then return require('component_view').pick(settings.lang,MOD.preload.labels[v])end
        local package_name=MOD.preload.translate_name(v,settings.lang);if package_name then return package_name end
        if v=='Helldiver / character subtitle'then return settings.lang=='zh-Hans'and'绝地潜兵／角色字幕'or settings.lang=='zh-Hant'and'絕地潛兵／角色字幕'or v end
        if v=='CharacterNameFields'then return settings.lang=='zh-Hans'and'角色名称字段'or settings.lang=='zh-Hant'and'角色名稱欄位'or'Character names'end
        if v=='FontStyleFields'then return settings.lang=='zh-Hans'and'字体样式字段'or settings.lang=='zh-Hant'and'字型樣式欄位'or'Font styles'end
        if v=='IdentityRpcInfo'then return settings.lang=='zh-Hans'and'网络接口参考'or settings.lang=='zh-Hant'and'網路介面參考'or'Network reference'end
        if v=='HealthComponents'then return settings.lang=='zh-Hans'and'生命组件'or settings.lang=='zh-Hant'and'生命組件'or'Health components'end
        if v=='DrownComponents'then return settings.lang=='zh-Hans'and'淹没组件'or settings.lang=='zh-Hant'and'淹沒組件'or'Drownable components'end
        if v=='ShieldComponents'then return settings.lang=='zh-Hans'and'护盾组件'or settings.lang=='zh-Hant'and'護盾組件'or'Shield components'end
        if v=='ThrowableComponents'then return settings.lang=='zh-Hans'and'投掷物组件'or settings.lang=='zh-Hant'and'投擲物組件'or'Throwable'end
        if v=='ThrowerComponents'then return settings.lang=='zh-Hans'and'投掷器组件'or settings.lang=='zh-Hant'and'投擲器組件'or'Thrower'end
        if v=='MinefieldComponents'then return settings.lang=='zh-Hans'and'地雷组件'or settings.lang=='zh-Hant'and'地雷組件'or'Minefield'end
        if v=='MineSpawnerComponents'then return settings.lang=='zh-Hans'and'地雷生成器组件'or settings.lang=='zh-Hant'and'地雷生成器組件'or'Mine spawner'end
        if v=='FactionComponents'then return settings.lang=='zh-Hans'and'阵营组件'or settings.lang=='zh-Hant'and'陣營組件'or'Faction components'end
        if v=='MountComponents'then return settings.lang=='zh-Hans'and'挂载组件'or settings.lang=='zh-Hant'and'掛載組件'or'Mount components'end
        if v=='InventoryComponents'then return settings.lang=='zh-Hans'and'物品栏组件'or settings.lang=='zh-Hant'and'物品欄組件'or'Inventory components'end
        if v=='SensorEyeComponents'then return settings.lang=='zh-Hans'and'视觉传感组件'or settings.lang=='zh-Hant'and'視覺感測組件'or'Sensor eyes'end
        if v=='TurretComponents'then return settings.lang=='zh-Hans'and'炮塔组件'or settings.lang=='zh-Hant'and'砲塔組件'or'Turret components'end
        if v=='EagleComponents'then return settings.lang=='zh-Hans'and'飞鹰组件'or settings.lang=='zh-Hant'and'飛鷹組件'or'Eagle components'end
        if v=='EagleSpawnerComponents'then return settings.lang=='zh-Hans'and'飞鹰生成器组件'or settings.lang=='zh-Hant'and'飛鷹生成器組件'or'Eagle spawner'end
        local tab_label=MOD.component_tab_label and MOD.component_tab_label[v]   -- (the weapon components' tabs)
        if tab_label then return settings.lang=='zh-Hans'and tab_label[2]or settings.lang=='zh-Hant'and tab_label[3]or tab_label[1]end
        if v=='DemolitionComponents'then return settings.lang=='zh-Hans'and'实体拆毁'or settings.lang=='zh-Hant'and'實體拆毀'or'Demolition'end
        if settings.lang == 'en' or not LANG[settings.lang] then return v end
        local cache = tr_cache[settings.lang]
        if not cache or tr_count > 5000 then cache, tr_count = {}, 0; tr_cache = { [settings.lang] = cache } end
        local t = cache[v]
        if not t then t = translate(v, 0); cache[v], tr_count = t, tr_count + 1 end
        return t
    end
end

-- unlocks: items the game has but does not offer, by id, on / off (settings.unlock, below). Each: config
-- name, a stratagem (its number in game.dll's stratagem list, key and record key in the item registry)
-- or equipment (model = entity hash high / low; template: the model, or key and class, of an item of
-- the same kind whose registry row a new row is copied from)
settings.UNLOCKS = {
    { id = 'incinerator', name = 'M-104 Incinerator FRV', config = 'incinerator_frv',
      strat = 135, key = 0xA9A97CD7, record = 0xDA0600D7 },
    { id = 'ombudsman', name = 'P-41 Ombudsman', config = 'unlock_ombudsman',
      model = { 0xBDE1F253, 0x4280300D }, template = { 0x05E4E5C2, 0xDB6E44A2 } },   -- template: P-2 Peacemaker
    { id = 'caltrops', name = 'G-11 Caltrops', config = 'unlock_caltrops',
      model = { 0x2968DEBA, 0x6D6C2F09 }, template = { 0x4CE9EAB7, 0x85A79B7B } },   -- template: G-6 Frag
    { id = 'shear', name = 'LAS-22 Shear', config = 'unlock_shear',   -- its key checked; template: the LAS-5 Scythe's key
      model = { 0x7E3145A5, 0xBAA4B948 }, key = 0x7DE53646, template_key = 0xE673DCC8, class = 1 },
}
settings.unlocks = {}
-- one switch for them all (Settings: "Unlock unused items"): on while any is (old configs saved each)
function settings.unlock_any()
    for _, item in ipairs(settings.UNLOCKS) do if settings.unlocks[item.id] then return true end end
    return false
end
function settings.unlock_all(on)
    for _, item in ipairs(settings.UNLOCKS) do settings.unlocks[item.id] = on end
end

local function config_path()
    local dir = data_dir('StatEditor')
    return dir and dir .. '/config.txt'
end

local function number_text(v)
    return string.format('%.17g',v)
end

function settings.set_percent(name, value)
    local r = settings.RANGE[name]
    local v = math.floor(value + 0.5)
    settings[name] = math.max(r[1], math.min(r[2], v))
    return settings[name] ~= v
end
-- the window's size, the text's size and the render resolution, to the host (offline/host.lua: SHODAN_DISPLAY)
settings.DISPLAY = { font_px = { 'Font size', '字体大小', '字型大小' }, render_height = { 'Resolution', '分辨率大小', '解析度大小' } }
function settings.apply_display()
    local d = rawget(_G, 'SHODAN_DISPLAY')
    if not (MOD.offline and d and d.apply) then return end
    pcall(d.apply, settings.font_px / 16, settings.render_height)
end
-- the resolution drawn at now: width, height (the window's own when render_height is 0)
function settings.display_size()
    local d = rawget(_G, 'SHODAN_DISPLAY')
    local ok, info = pcall(function() return d and d.get and d.get() end)
    if ok and type(info) == 'table' and info.w then return info.w, info.h end
    return nil
end
-- a typed resolution: '1080', '1060x1080' (its height counts: the width is the panel's shape) or 0 / empty: the window's
function settings.set_render(text)
    local w, h = tostring(text or ''):match('^%s*(%d+)%s*[xX%*]%s*(%d+)%s*$')
    h = tonumber(h or tostring(text or ''):match('^%s*(%d+)%s*$'))
    if not h or h == 0 then settings.render_height = 0; return false end
    local r = settings.RANGE.render_height
    settings.render_height = math.max(r[1], math.min(r[2], math.floor(h)))
    return settings.render_height ~= h
end

local function save_config()
    config_dirty_at = nil
    local path = config_path()
    if not path then return end
    local lines = {
        '# SHODAN Stat Editor settings. Changed through the in-game panel; applied at every start.',
        '# Lines: <weapon hash> <stat> <value>. Delete a line (or this file) to go back to the game\'s value.',
        '# The first lines are the Settings page\'s choices.',
        'hotkey ' .. hotkey_name,
    }
    local function onoff(v) return v and 'on' or 'off' end
    for _, line in ipairs({ 'changes ' .. onoff(settings.changes), 'block_input ' .. onoff(settings.block_input),
                            'panel_size ' .. settings.size, 'panel_side ' .. settings.side,
                            'panel_opacity ' .. settings.opacity,
                            'arc_chains_multiplayer ' .. onoff(settings.arc_mp) }) do
        lines[#lines + 1] = line
    end
    if MOD.offline then lines[#lines + 1] = 'lang ' .. settings.lang end
    if MOD.offline then
        for _, k in ipairs({ 'font_px', 'render_height' }) do lines[#lines + 1] = k .. ' ' .. settings[k] end
        lines[#lines+1]='component_show_missing '..onoff(settings.component_show_missing)
        lines[#lines+1]='component_category '..settings.component_category
        lines[#lines+1]='weapon_category '..settings.weapon_category
        lines[#lines+1]='enemy_category '..settings.enemy_category
    end
    if MOD.offline then
        lines[#lines + 1] = 'updates ' .. settings.updates
        lines[#lines + 1] = 'update_channel ' .. settings.update_channel
        lines[#lines + 1] = 'cache_clear_on_exit ' .. onoff(settings.cache_clear_on_exit)
        -- passive_stack <passive id> <passive id>,<passive id>...: the passives stacked on it
        local ids, NAMES = {}, KINDS[TYPES.passive].NAMES
        for id in pairs(settings.stacks) do ids[#ids + 1] = id end
        table.sort(ids)
        for _, id in ipairs(ids) do
            local names = {}
            for k, other in ipairs(settings.stacks[id]) do names[k] = NAMES[other] or ('Passive ' .. other) end
            lines[#lines + 1] = 'passive_stack ' .. id .. ' ' .. table.concat(settings.stacks[id], ',') ..
                                '   # ' .. (NAMES[id] or ('Passive ' .. id)) .. ': ' .. table.concat(names, ', ')
        end
        -- passive_own <passive id> off: its own effects left out (only the passives stacked on it apply)
        ids = {}
        for id in pairs(settings.own_off) do ids[#ids + 1] = id end
        table.sort(ids)
        for _, id in ipairs(ids) do
            lines[#lines + 1] = 'passive_own ' .. id .. ' off   # ' .. (NAMES[id] or ('Passive ' .. id))
        end
    end
    lines[#lines + 1] = 'unlock_unused ' .. onoff(settings.unlock_any())
    lines[#lines + 1] = 'several_vehicles ' .. onoff(MOD.vehicles.on)
    lines[#lines + 1] = 'stratagem_bounce ' .. onoff(MOD.tweaks.bounce.on)
    lines[#lines + 1] = 'foliage_pass_through ' .. onoff(MOD.tweaks.foliage.on)
    lines[#lines + 1] = 'sniper_crosshair ' .. onoff(MOD.tweaks.reticle.on)
    -- hide_tabs <tab>,<tab>...: the tabs Settings > Tabs shown turned off
    local hidden = {}
    for tab in pairs(settings.hidden) do hidden[#hidden + 1] = tab end
    table.sort(hidden)
    if #hidden > 0 then lines[#lines + 1] = 'hide_tabs ' .. table.concat(hidden, ',') end
    -- the tab and page each editor was left on, and the editor (reopened there)
    local last = settings.last
    if last.stat.tab then lines[#lines + 1] = 'last_tab ' .. last.stat.tab end
    if last.stat.weapon then lines[#lines + 1] = 'last_weapon ' .. last.stat.weapon end
    if last.enemy.tab then lines[#lines + 1] = 'enemy_tab ' .. last.enemy.tab end
    if last.enemy.weapon then lines[#lines + 1] = 'enemy_page ' .. last.enemy.weapon end
    lines[#lines + 1] = 'editor ' .. (settings.enemy_last and 'enemy' or 'stat')
    for _, o in ipairs(overrides) do
        local weapon = by_hash[o.hash]
        local p = weapon and weapon.by_id[o.id]
        if not o.installed and not (p and p.field.demolition) then
            lines[#lines + 1] = o.hash .. ' ' .. o.id .. ' ' .. number_text(o.value) ..
                                (weapon and ('   # ' .. weapon.name) or '')
        end
    end
    local renamed = {}
    for hash in pairs(MOD.rename.texts) do renamed[#renamed + 1] = hash end
    table.sort(renamed)
    for _, hash in ipairs(renamed) do
        for _, field in ipairs({ 'name', 'desc' }) do
            local v = MOD.rename.texts[hash][field]
            if v then lines[#lines + 1] = 'rename ' .. hash .. ' ' .. field .. ' ' .. v end
        end
    end
    local ok, why = MOD.write_text(path, table.concat(lines, '\r\n') .. '\r\n')
    if not ok then log('could not write ' .. path .. ': ' .. why) end
    return ok, why
end

local function load_config()
    local path = config_path()
    local handle = path and io.open(path, 'rb')
    if not handle then save_config(); return end
    local text = handle:read('*a') or ''
    handle:close()
    local count = 0
    for at, line in MOD.lines_of(text) do
        line = line:gsub('#.*$', '')
        local known = not line:find('%S')
        local key = line:match('^%s*hotkey%s+(%S+)')
        if key then hotkey_name = key; known = true end
        local name, value = line:match('^%s*([%a_]+)%s+(%S+)%s*$')
        if name=='component_show_missing'then settings.component_show_missing=value~='off';known=true end
        if name=='component_category'and value:match('^[%w_-]+$')then settings.component_category=value;known=true end
        if name=='weapon_category'and value:match('^[%w_-]+$')then settings.weapon_category=value;known=true end
        if name=='enemy_category'and value:match('^[%w_-]+$')then settings.enemy_category=value;known=true end
        local target, sources = line:match('^%s*passive_stack%s+(%d+)%s+([%d,]+)%s*$')
        if target and MOD.offline then
            local list, seen = {}, { [tonumber(target)] = true }
            for id in sources:gmatch('%d+') do
                id = tonumber(id)
                if not seen[id] then seen[id], list[#list + 1] = true, id end
            end
            settings.stacks[tonumber(target)] = #list > 0 and list or nil
            known = true
        end
        local own = line:match('^%s*passive_own%s+(%d+)%s+off%s*$')
        if own and MOD.offline then settings.own_off[tonumber(own)], known = true, true end
        if name == 'changes' or name == 'block_input' then
            settings[name] = value ~= 'off'
            known = true
        elseif name == 'remember' then   -- the old Settings choice: always on now
            known = true
        elseif name == 'check_updates' or name == 'updates' and value == 'off' then   -- test builds' (no Off now)
            known = true
        elseif name == 'update_channel' and (value == 'releases' or value == 'commits') then
            settings.update_channel = value
            known = true
        elseif name == 'cache_clear_on_exit' then
            settings.cache_clear_on_exit = value ~= 'off'
            known = true
        elseif name == 'updates' and (value == 'ask' or value == 'auto') then
            settings.updates = value
            known = true
        elseif name == 'arc_chains_multiplayer' then
            settings.arc_mp = value == 'on'
            known = true
        elseif (name == 'panel_size' or name == 'panel_opacity') and MOD.parse_number(value) then
            settings.set_percent(name:sub(7), MOD.parse_number(value))
            known = true
        elseif name == 'font_px' and MOD.parse_number(value) then
            settings.set_percent(name, MOD.parse_number(value))
            known = true
        elseif name == 'render_height' then
            settings.set_render(value)
            known = true
        elseif name == 'window_size' or name == 'font_size' or name == 'render_scale' then   -- (a test build's percents)
            known = true
        elseif name == 'panel_side' and (value == 'left' or value == 'right') then
            settings.side = value
            known = true
        elseif name == 'lang' and MOD.offline and (value == 'en' or settings.LANGS[value]) then
            settings.lang = value
            known = true
        elseif name == 'panel_lang' then   -- the language choice of PR #52's build and of test builds: gone
            known = true                     -- (each language has its own release)
        elseif name == 'last_tab' or name == 'enemy_tab' then
            settings.last[name == 'enemy_tab' and 'enemy' or 'stat'].tab = value
            known = true
        elseif name == 'editor' and (value == 'enemy' or value == 'stat') then
            settings.enemy_last = value == 'enemy'
            known = true
        elseif name == 'hide_tabs' then
            for tab in value:gmatch('[^,%s]+') do settings.hidden[tab] = true end
            known = true
        elseif (name == 'last_weapon' or name == 'enemy_page') and value:find('^%x+$') and #value == 16 then
            settings.last[name == 'enemy_page' and 'enemy' or 'stat'].weapon = value:upper()
            known = true
        elseif name == 'several_vehicles' then
            MOD.vehicles.on = value == 'on'; MOD.vehicles.apply()
            known = true
        elseif name == 'stratagem_bounce' or name == 'foliage_pass_through' or name == 'sniper_crosshair' then
            MOD.tweaks[name == 'stratagem_bounce' and 'bounce' or name == 'sniper_crosshair' and 'reticle' or 'foliage'].on = value == 'on'
            MOD.tweaks.apply()
            known = true
        elseif name == 'unlock_unused' then
            settings.unlock_all(value == 'on')
            known = true
        elseif name then   -- last: any other name would stop here
            for _, item in ipairs(settings.UNLOCKS) do
                -- one line per item before the single switch: any on turns them all on (local test builds
                -- saved incinerator_frv 'off' / 'gunner' / 'supply')
                if name == item.config then
                    if value == 'on' then settings.unlock_all(true) end
                    known = true
                end
            end
        end
        local hash, id, amount = line:match('^%s*(%x%x%x%x%x%x%x%x%x%x%x%x%x%x%x%x)%s+([%w_]+)%s+(%S+)')
        local parsed = hash and MOD.parse_number(amount)
        if parsed then
            overrides[#overrides + 1] = { hash = hash:upper(), id = id, value = parsed }
            count = count + 1
            known = true
        end
        local rhash, field, typed = line:match('^%s*rename%s+(%x+)%s+(%a+)%s+(.-)%s*$')
        if rhash and MOD.offline and (field == 'name' or field == 'desc') and typed ~= '' then
            local t = MOD.rename.texts[rhash:upper()] or {}
            t[field], MOD.rename.texts[rhash:upper()], known = typed, t, true
        end
        if not known then MOD.skipped('config.txt', at, line) end
    end
    log('config: ' .. count .. ' value(s), hotkey ' .. hotkey_name .. (settings.changes and '' or ', changes OFF') ..
        ' (' .. path .. ')')
end

local function mark_config_dirty() config_dirty_at = api.now() + 0.75; MOD.enemy.refresh_due = true end

-- ---------------------------------------------------------------- names and descriptions (offline; upstream 4.5.1)
-- The Name and Description boxes under a page's rows: the game's text ids in its encyclopedia entry (weapons,
-- throwables: +0 name, +8 in capitals, +20 description) and its stratagem's row (+44 name, +40 in capitals, +48
-- description). The host has the game's English texts (SHODAN_TEXTS.texts, by id: offline/game_texts.lua); Install
-- puts the typed ones into every language's strings files, in a patch over the game's archive (Restore deletes it).
-- In config.txt: rename <page hash> name|desc <text>. LIMIT: past it a typed text is still written, with a warning
-- (the game's own are at most about that long); HARD: what a box takes at all (bytes).
MOD.rename = { texts = {}, LIMIT = { name = 60, desc = 400 }, HARD = { name = 1000, desc = 4000 } }
-- a page's text ids ({ id, capitals } lists name and desc) and its game texts (game.name, game.desc), nil without
function MOD.rename.of(w)
    local host = rawget(_G, 'SHODAN_TEXTS')
    local texts = host and host.texts
    if not texts or not w then return nil end
    local out = { name = {}, desc = {} }
    local function add(list, id, caps) if id and texts[id] then list[#list + 1] = { id, caps } end end
    local t = w.key and tables[TYPES.encyclopedia]
    local e = t and t.index[w.key]
    if e then
        local at = t.copies[1] + HEADER_BYTES + e
        add(out.name, peek4(at)); add(out.name, peek4(at + 8), true); add(out.desc, peek4(at + 20))
    end
    local def = w.stratagem and w.stratagem.def
    if def and def.at then add(out.name, peek4(def.at + 44)); add(out.name, peek4(def.at + 40), true); add(out.desc, peek4(def.at + 48)) end
    if #out.name == 0 then return nil end
    out.game = { name = texts[out.name[1][1]], desc = out.desc[1] and texts[out.desc[1][1]] }
    return out
end
-- id -> text of every typed name and description (the host's Install asks: state.rename_map)
function MOD.rename.map()
    local out = {}
    for hash, typed in pairs(MOD.rename.texts) do
        local ids = MOD.rename.of(by_hash[hash])
        for _, field in ipairs(ids and { 'name', 'desc' } or {}) do
            for _, n in ipairs(typed[field] and ids[field] or {}) do out[n[1]] = n[2] and typed[field]:upper() or typed[field] end
        end
    end
    return out
end
state.rename_map = MOD.rename.map
-- a typed text's length in characters (UTF-8)
function MOD.rename.length(text) local n = 0; for _ in text:gmatch('[%z\1-\127\194-\244][\128-\191]*') do n = n + 1 end; return n end
-- a page's typed text (nil, '' or the game's own: back to the game's)
function MOD.rename.set(w, field, text)
    local ids = MOD.rename.of(w)
    if text == '' or (ids and text == ids.game[field]) then text = nil end
    local t = MOD.rename.texts[w.hash] or {}
    if t[field] ~= text then state.writes = state.writes + 1 end   -- (the host: changed since the last install)
    t[field] = text
    MOD.rename.texts[w.hash] = next(t) and t or nil
    mark_config_dirty()
end

-- Only a derived cache for the original page's changed markers, counts and presets.
-- Canonical values live in entity_demolition.txt and are never saved to config.txt.
function MOD.sync_demolition()
    local kept, seen = {}, {}
    for _, o in ipairs(overrides) do
        local w = by_hash[o.hash]
        local p = w and w.by_id[o.id]
        if not (p and p.field.demolition) then kept[#kept + 1] = o end
    end
    local pages={};for _,w in ipairs(weapons)do pages[#pages+1]=w end
    for _,w in ipairs(MOD.component_catalog and MOD.component_catalog.views.demolition or{})do pages[#pages+1]=w end
    for _, w in ipairs(pages) do
        for _, row in ipairs(w.rows) do
            for _, p in ipairs(row.parts) do
                local f = p.field
                if f.demolition and not seen[f.key] then
                    seen[f.key] = true
                    local value = f.demolition:own(f)
                    if value ~= nil then kept[#kept + 1] = {hash=w.hash,id=p.id,value=value,demolition=true} end
                end
            end
        end
    end
    overrides = kept
    state.demolition_revision = (state.demolition_revision or 0) + 1
end
if MOD.offline then state.sync_demolition = MOD.sync_demolition end

-- Drops every override that writes the same memory as (hash, id), then optionally adds one.
local function set_override(weapon, p, value)
    if p.health_owner then weapon,p = p.health_owner.weapon,p.health_owner.part end
    if value~=nil and p.field and p.field.storage=='f32'then
        local stored=read_field(p.field);if stored~=nil then value=stored end
        if value==default_of(p.field)then value=nil end
    end
    if p.field and p.field.demolition then
        -- write_field already committed the exact input, including an explicit baseline.
        -- Resets use the bridge explicitly; nil here only means the old cache needs no entry.
        if value ~= nil then return p.field.demolition:write(p.field, value) end
        return true
    end
    if value==nil and p.field.installed_value~=nil then value=default_of(p.field)end
    local kept = {}
    for _, o in ipairs(overrides) do
        local other = by_hash[o.hash]
        local op = other and other.by_id[o.id]
        if not (op and op.field == p.field) and not (o.hash == weapon.hash and o.id == p.id) then
            kept[#kept + 1] = o
        end
    end
    if value ~= nil then kept[#kept + 1] = { hash = weapon.hash, id = p.id, value = value,
        installed=p.field.installed_value~=nil and value==p.field.installed_value or nil } end
    overrides = kept
    if p.field and p.field.storage == 'grenade' then MOD.queue_grenade(weapon, p, value) end
    mark_config_dirty()
end

-- Installed values come from authenticated game files, never from the disposable
-- editor cache. Keep the original defaults for Reset and stage cached edits last.
function MOD.installed_rows()
    local source=MOD.offline and rawget(_G,'SHODAN_INSTALLED_VALUES')
    if not source or not next(source.blocks)then return end
    for _,w in ipairs(weapons)do
        if w.ensure_rows and w.component_kind_hash and w.component_offset and w.component_size
           and source:changed(tables[w.component_kind_hash],w.component_offset,w.component_size)then w.ensure_rows()end
    end
end
function MOD.restore_installed(work,deadline)
    local source=MOD.offline and rawget(_G,'SHODAN_INSTALLED_VALUES')
    if not source or not settings.changes or not next(source.blocks)then return true end
    work=work or{}
    if not work.installed_keys then
        work.installed_keys,work.installed_at,work.installed_cached={},1,{}
        local kept={}
        for _,o in ipairs(overrides)do if not o.installed then
            kept[#kept+1]=o
            local w=by_hash[o.hash]
            for _,p in ipairs(w and MOD.parts_of(w,o.id)or{})do work.installed_cached[p.field.key]=true end
        end end
        overrides=kept
        for key in pairs(fields)do work.installed_keys[#work.installed_keys+1]=key end
    end
    local writes=state.writes
    while work.installed_at<=#work.installed_keys do
        local f=fields[work.installed_keys[work.installed_at]]
        local value=source:value(f,tables[f.kind]);f.installed_value=nil
        if value~=nil and MOD.numeric.valid(f,value)and value~=default_of(f)then
            local owner,part
            for _,w in ipairs(f.users)do if by_hash[w.hash]==w then
                for _,p in pairs(w.by_id)do if p.field==f then owner,part=w,p;break end end
                if part then break end
            end end
            if part and write_field(f,value)then
                f.installed_value=value
                if not work.installed_cached[f.key]then
                    if part.health_owner then owner,part=part.health_owner.weapon,part.health_owner.part end
                    overrides[#overrides+1]={hash=owner.hash,id=part.id,value=value,installed=true}
                end
            end
        end
        work.installed_at=work.installed_at+1
        if work.installed_at%256==0 and api.now()>=deadline then state.writes=writes;return false end
    end
    state.writes=writes;MOD.page_changed_cache=nil
    return true
end
if MOD.offline then state.installed_committed=function()
    local source=rawget(_G,'SHODAN_INSTALLED_VALUES');if not source then return end
    for _,f in pairs(fields)do
        local value=source:value(f,tables[f.kind])
        f.installed_value=value~=nil and MOD.numeric.valid(f,value)and value or nil
    end
    local kept={}
    for _,o in ipairs(overrides)do
        local w=by_hash[o.hash];local p=w and w.by_id[o.id]
        if not p or p.field.demolition or o.value~=default_of(p.field)then
            o.installed=p and p.field.installed_value~=nil and o.value==p.field.installed_value or nil
            kept[#kept+1]=o
        end
    end
    overrides=kept;MOD.page_changed_cache=nil
end end

-- Writes the faction-wide rows' fields (MOD.enemy.FACTION_STATS): each covered field as its game value x the row
-- (armor: + the row), but for the fields another page has a change on (that page's value stands). Run once the
-- saved values are applied and after every change (MOD.enemy.refresh_due).
function MOD.enemy.faction_refresh()
    MOD.enemy.refresh_due = nil
    local owned, by_all, covered, plan = {}, {}, {}, {}
    for _, o in ipairs(overrides) do
        local page = by_hash[o.hash]
        local p = page and not (page.enemy and page.enemy.faction) and page.by_id[o.id]
        if p and p.field then owned[p.field.key] = true end
    end
    for _, page in ipairs(weapons) do
        if page.enemy and page.enemy.faction then
            -- its fields, gathered once: per stat, every covered part of the faction's pages
            if not page.enemy.targets then
                local targets = {}
                for _, r in ipairs(page.rows) do targets[r.id] = { list = {}, seen = {} } end
                for _, other in ipairs(weapons) do
                    if other.enemy and not other.enemy.faction
                       and (page.enemy.global and MOD.ENEMY_SLOTS[other.slot] or other.slot == page.slot) then
                        for _, r in ipairs(other.rows) do
                            for _, p in ipairs(r.parts) do
                                for _, s in ipairs(MOD.enemy.FACTION_STATS) do
                                    local t = targets[s[2]]
                                    if t and p.field and p.field.storage ~= 'virtual' and not t.seen[p.field.key] and s[7](other, r, p) then
                                        t.seen[p.field.key] = true
                                        t.list[#t.list + 1] = p.field
                                    end
                                end
                            end
                        end
                    end
                end
                page.enemy.targets = targets
            end
            -- (each field's factor and offset, gathered over every page first: the whole-game page's and its
            -- faction page's multiply, their armor steps add)
            for _, r in ipairs(page.rows) do
                local v = read_field(r.parts[1].field) or (r.add and 0 or 1)
                for _, f in ipairs(page.enemy.targets[r.id].list) do
                    local e = plan[f.key]
                    if not e then e = { f = f, mult = 1, add = 0 }; plan[f.key] = e; plan[#plan + 1] = e end
                    if r.add then e.add, e.is_add = e.add + v, true else e.mult = e.mult * v end
                end
            end
        end
    end
    for _, e in ipairs(plan) do
        local f = e.f
        local d = default_of(f)
        local new = d and d * e.mult
        if d and e.is_add then new = d + e.add end
        if new and f.storage == 'u32' then new = math.floor(new + 0.5) end
        if new then new=MOD.numeric.clamp(f,new)end
        local moved = new and new ~= d
        if moved then covered[f.key] = true end
        if new and not owned[f.key] then
            local now = read_field(f)
            if now == nil or now ~= new then write_field(f, new) end
            if moved then by_all[f.key] = true end
        end
    end
    MOD.weapon_sway_refresh(owned, by_all)
    -- the pages with a value only a faction-wide row changed (their name in the list: MOD.enemy.ALL_INK)
    local pages = {}
    for _, page in ipairs(weapons) do
        if page.enemy and not page.enemy.faction then
            for _, r in ipairs(page.rows) do
                if MOD.enemy.by_all_value(r, by_all, owned) then pages[page.hash] = true; break end
            end
        end
    end
    MOD.enemy.by_all, MOD.enemy.owned, MOD.enemy.by_all_pages, MOD.enemy.covered = by_all, owned, pages, covered
    -- a page's value kept at the game's own (MOD.enemy.keep_own) once no faction-wide row moves it: dropped
    local kept = {}
    for _, o in ipairs(overrides) do
        local page = by_hash[o.hash]
        local p = page and page.enemy and not page.enemy.faction and page.by_id[o.id]
        local d = p and p.field and default_of(p.field)
        if not (d and not covered[p.field.key] and o.value == d) then kept[#kept + 1] = o end
    end
    if #kept < #overrides then overrides = kept; mark_config_dirty() end
end

-- A row's value when only a faction-wide row changed it (none of its fields has a change of a page's own), else
-- nil. A multiplier row: the factor its fields got (its own value stays the game's 1).
function MOD.enemy.by_all_value(row, by_all, owned)
    by_all, owned = by_all or MOD.enemy.by_all, owned or MOD.enemy.owned
    if not by_all then return nil end
    local hit = nil
    for _, p in ipairs(row.parts) do
        if p.field and owned[p.field.key] then return nil end
        if p.field and by_all[p.field.key] then hit = hit or p end
    end
    if not hit then return nil end
    if row.lead then
        if row.parts[1] == hit then return row_value(row) end
        local d, v = default_of(hit.field), read_field(hit.field)
        if not (d and v) or d == 0 or v == 0 then return nil end
        return row.inverse and d / v or v / d
    end
    return row_value(row)
end

-- The value to keep as a change: nil when it is the game's own.
local function unless_default(value, default)
    if default ~= nil and value == default then return nil end
    return value
end

-- The value to keep as a page's own change: its game value too where an 'All <faction>' row moves the field
-- (set back to the game's value on purpose: kept, so the faction-wide row leaves it), else unless_default's.
function MOD.enemy.keep_own(weapon, p, value, default)
    if p.health_owner and p.health_owner.part ~= p then return MOD.enemy.keep_own(p.health_owner.weapon,p.health_owner.part,value,default) end
    if weapon.enemy and not weapon.enemy.faction and p.field and MOD.enemy.covered and MOD.enemy.covered[p.field.key] then
        return value
    end
    return unless_default(value, default)
end

-- Whether a row holds a page's own change at the game's value where a faction-wide row moves it (shown as changed)
function MOD.enemy.pinned(row)
    local covered, owned = MOD.enemy.covered, MOD.enemy.owned
    if not (covered and owned) then return false end
    for _, p in ipairs(row.parts) do
        if p.field and covered[p.field.key] and owned[p.field.key] then return true end
    end
    return false
end

-- A multiplier row's fields written from its own value (a preset holding only that: the examples).
function MOD.enemy.mult_fields(weapon, row, value)
    for k = 2, #row.parts do
        local p = row.parts[k]
        local d = default_of(p.field)
        if d ~= nil then
            local new = row.inverse and d / value or d * value
            if write_field(p.field, new) then set_override(weapon, p, unless_default(new, d)) end
        end
    end
end

-- A row whose value is the span of time rows (row.keeps: the Hover Pack's recharge time, its fuel):
-- their times before it changes, then (keep_times) their rates rewritten so the times stay.
function MOD.times_of(row)
    if not row.keeps then return nil end
    local times = {}
    for n, k in ipairs(row.keeps) do times[n] = row_value(k) end
    return { rows = row.keeps, times = times }
end

function MOD.keep_times(weapon, keep)
    if not keep then return end
    for n, k in ipairs(keep.rows) do
        local span, p = k.span(), k.parts[1]
        if keep.times[n] and keep.times[n] > 0 and span and span > 0 then   -- (no time to keep at 0)
            local new, d = span / keep.times[n] - (k.rate_plus or 0), default_of(p.field)
            if d and new == d then new = d end
            if write_field(p.field, new) then set_override(weapon, p, unless_default(new, d)) end
        end
    end
end

-- Wind-up weapons (the Maxigun): its wind-up / wind-down times (`spin`: its WeaponWindUp record), and
-- WeaponData +387 (`data`: its record), set on the Maxigun alone: it stops you while you fire (HD2Runtime 0.30)
function MOD.spin_rows(weapon, data, spin)
    if spin then
        for _, t in ipairs({ { 'spin_up', 'Wind-up time (s)', 0 }, { 'spin_down', 'Wind-down time (s)', 4 } }) do
            add_row(weapon, 'Wind-up', t[1], t[2], 'f32', { part(t[1], TYPES.windup, spin + t[3], 'f32', 3600) }, 0.01, 60, 0.05, 0.25)
        end
    end
    local still = part('stationary', T_WEAPON, data + 387, 'flag', 1)
    if default_of(still.field) == 1 then
        add_row(weapon, 'Handling', 'stationary', 'Stops you while firing', 'flag', { still }, 0, 1, 1, 1)
    end
end

-- The parts a saved id names: its own (a swap row's first: the whole row's, all one value, so a field
-- the row gained later follows a value saved without it: the SG-20 Halt's ammo types), else (an id saved
-- before the weapon's magazine attachments had rows of their own: 'capacity', once every magazine's)
-- each of theirs. nil: none.
function MOD.parts_of(weapon, id)
    if weapon.ensure_rows then weapon.ensure_rows() end   -- (a component page whose rows are made when needed)
    local own = weapon.by_id[id]
    if own and own.row and own.row.choice and not own.row.each and own.row.parts[1] == own then return own.row.parts end   -- (each: every part its own value)
    if own then return { own } end
    local out = {}
    for _, listed in ipairs(weapon.legacy and weapon.legacy[id] or {}) do out[#out + 1] = weapon.by_id[listed] end
    return out[1] and out or nil
end

-- For other mods: the game's own value of a stat, named as in config.txt (weapon hash, stat id), as
-- read at startup before this mod wrote anything. nil: no such weapon / stat, or its table not found.
function state.vanilla(hash, id)
    local weapon = type(hash) == 'string' and by_hash[hash:upper()]
    local parts = weapon and type(id) == 'string' and MOD.parts_of(weapon,id)
    local p = parts and parts[1]
    return p and default_of(p.field) or nil
end

local pending = {}      -- config values not applied yet (tables still being written)
local apply_at = 1

-- Reuse the saved-value retry queue while a grenade's package loads. New selections,
-- reset and presets cancel older requests for the same field, including shared hosts.
function MOD.queue_grenade(weapon, p, value)
    apply_at = 1
    for n = #pending, 1, -1 do
        local o = pending[n]
        local other = by_hash[o.hash]
        local op = other and other.by_id[o.id]
        if op and op.field == p.field then table.remove(pending, n) end
    end
    p.field.pending_value = nil
    if settings.changes and value ~= nil and KINDS[TYPES.throwable].entity_bytes(value)
       and read_field(p.field) ~= value then
        p.field.pending_value = value
        pending[#pending + 1] = { hash = weapon.hash, id = p.id, value = value, after = api.now() + 1 }
    end
end

function MOD.clear_grenade_pending()
    for _, f in pairs(fields) do if f.storage == 'grenade' then f.pending_value = nil end end
end

-- Applies pending values until the deadline (the rest wait for the next call); true when the
-- whole list was gone through once. Values that could not be written yet are tried again
-- later (the table may still be filling), up to 30 times.
local function apply_config(deadline)
    while apply_at <= #pending do
        local o = pending[apply_at]
        local weapon = by_hash[o.hash]
        local parts = weapon and MOD.parts_of(weapon, o.id)
        local keep = false
        if o.after and api.now() < o.after then
            keep = true   -- a grenade choice still settling
        elseif not weapon then
            log('config: unknown weapon ' .. o.hash); state.refused = state.refused + 1
        elseif not parts then
            log('config: ' .. weapon.name .. ' has no stat ' .. o.id); state.refused = state.refused + 1
        else
            local ok, why = true, nil
            for _, p in ipairs(parts) do
                default_of(p.field)
                local done, failed = write_field(p.field, o.value)
                ok, why = ok and done, why or failed
            end
            if ok then
                for _, p in ipairs(parts) do
                    if p.field.storage == 'grenade' then p.field.pending_value = nil end
                end
                state.applied = state.applied + 1
                if parts[1].id ~= o.id then   -- saved under an old id: kept under the attachments' own from now on
                    set_override(weapon, { id = o.id }, nil)
                    for _, p in ipairs(parts) do set_override(weapon, p, unless_default(o.value, default_of(p.field))) end
                end
            else
                o.tries = (o.tries or 0) + 1
                keep = o.tries < 30
                if keep then
                    for _, p in ipairs(parts) do
                        if p.field.storage == 'grenade' then p.field.pending_value = o.value end
                    end
                end
                if not keep then
                    for _, p in ipairs(parts) do
                        if p.field.storage == 'grenade' then
                            p.field.pending_value = nil
                            -- the choice stays saved (tried again next start); say so, the row now shows the projectile
                            MOD.notify(weapon.name .. ': grenade not applied (' .. tostring(why) .. ')', 6)
                        end
                    end
                    log('config: ' .. weapon.name .. ' ' .. o.id .. ' not applied: ' .. why); state.refused = state.refused + 1
                end
            end
        end
        if keep then apply_at = apply_at + 1 else table.remove(pending, apply_at) end
        if deadline and api.now() >= deadline then break end
    end
    if apply_at <= #pending then return false end
    apply_at = 1
    return true
end

-- ---------------------------------------------------------------- loadout slot (issue #82)
-- The loadout list (LoadoutEntryComponentData): keyed by entity, records of 32 bytes (+0 id, +4 type:
-- 1 primary, 2 support, 3 secondary, 4 throwable, 5 gear, 6 backpack), more records than buckets, so its
-- bucket count is the one whose keys all sit near their home bucket (key % count). The type is the armory
-- slot the weapon is listed in: the Slot row moves it (primary, secondary or support).
TYPES.loadout = 0x4F2CF417
-- the Enemy Editor's spawning: HiveMindComponentData (a faction's spawn pressure, one per mission type) and the
-- lowest-rate record (0xD74E6E1A, one 96-byte record: +80/+84 patrols, +88/+92 reinforcements)
TYPES.hivemind, TYPES.spawn_floor = 0xD0207221, 0xD74E6E1A
KINDS[TYPES.hivemind] = { name = 'hive mind', stride = 1084, keyed = true }
KINDS[TYPES.spawn_floor] = { name = 'spawn floor', stride = 96, keyed = true }
-- the enemy pages' other tables (filediver's typelib layouts; strides checked on the current build):
-- AiCharacter (+0 preferred / +4 maximum speed), AiEnemy (each AI state's speed; 736 bytes in this build),
-- Unit (+8 / +12 scale), Inventory (+0 / +8 weapons carried), SensorEar (+4 hearing),
-- SquadTransportFormation (2 formations of 24: +4 rows, +8 columns)
TYPES.ai_character, TYPES.ai_enemy = 0x5FEF63C4, 0x9D0EEFB5
TYPES.unit, TYPES.inventory, TYPES.ear, TYPES.transport = 0x4437574D, 0x8ADAB43B, 0xC8033E7F, 0x498CE7C7
KINDS[TYPES.ai_character] = { name = 'AI character', stride = 80, keyed = true }
KINDS[TYPES.ai_enemy] = { name = 'enemy AI', stride = 736, keyed = true }
KINDS[TYPES.unit] = { name = 'unit', stride = 136, keyed = true }
KINDS[TYPES.inventory] = { name = 'inventory', stride = 144, keyed = true }
KINDS[TYPES.ear] = { name = 'hearing', stride = 16, keyed = true }
KINDS[TYPES.transport] = { name = 'transport', stride = 48, keyed = true }
-- whose side a unit is on (FactionComponentData, 152-byte records: +0 up to 3 factions of 4 bytes; 0 none,
-- 1 Super Earth, 2 Terminids, 4 Illuminate, 8 Automatons). From 127MU's and CarbonAnime's forks. Only the
-- first is shown; a unit whose first is none gets no row.
MOD.faction = { NAMES = { [1] = 'Super Earth', [2] = 'Terminids', [4] = 'Illuminate', [8] = 'Automatons' }, ORDER = { 1, 2, 4, 8 } }
-- 'Faction: <sides>' for any value (its bits named, others by number)
function MOD.faction.label(v)
    if v == nil then return 'Faction: ?' end
    local names, rest = {}, v
    for _, b in ipairs(MOD.faction.ORDER) do
        if math.floor(rest / b) % 2 == 1 then names[#names + 1] = MOD.faction.NAMES[b]; rest = rest - b end
    end
    if rest ~= 0 or #names == 0 then names[#names + 1] = tostring(rest) end
    if #names == 1 then return 'Faction: ' .. names[1] end   -- (one side: the translated 'Faction: <side>')
    for k, n in ipairs(names) do names[k] = MOD.nav.text(n) end
    return MOD.nav.text('Faction') .. (tostring(settings.lang):find('^zh') and '：' or ': ') .. table.concat(names, ' + ')
end
function MOD.faction.row(entry, section, id, keys)
    local t, p = tables[TYPES.faction], {}
    for n, key in ipairs(keys) do
        local at = t and t.index[key]
        if at then p[#p + 1] = part(#p == 0 and id or (id .. '_' .. n), TYPES.faction, at, 'u32', 255) end
    end
    if #p == 0 or not MOD.faction.NAMES[default_of(p[1].field) or 0] then return end
    -- (no allowed values on the field: 实体组件 › 阵营 edits the same one, any value)
    local r = add_row(entry, section, id, 'Faction', 'u32', p, 0, 255, 1, 1)
    r.choice = 'faction'
    r.label_of = function() return MOD.faction.label(read_field(p[1].field)) end
    r.note = 'who it fights for: units of other sides attack it, and it attacks them'
    r.tip = { 'Arrows step through 1 Super Earth, 2 Terminids, 4 Illuminate, 8 Automatons. Typed: any value 0-255 '
              .. '(the sides are bits: 10 = Terminids and Automatons; 0 = none).' }
end
-- stratagem jammers (StratagemBlockerComponentData): +0 the stratagem kind blocked (7: every kind), +12 the
-- radius, +16 active from the start; 4 bytes after the records
TYPES.jammer = 0x8C5F8AB7
KINDS[TYPES.jammer] = { name = 'jammer', stride = 20, keyed = true, slack = 4 }
-- stratagem scramblers (StratagemScramblerComponentData, 28-byte records): +0 the stratagem kind scrambled, +12 the
-- radius, +16 its strength, +24 the status effect it puts on Helldivers in range
TYPES.scrambler = 0x595A2910
KINDS[TYPES.scrambler] = { name = 'scrambler', stride = 28, keyed = true }
-- target retention (0xFF67A367, 24-byte records; Gameplay Reforged's tank tracking): +16 how fast a lost target is
-- forgotten (1: the game's; 0.5 keeps tracking twice as long); the enemy Leviathan's flight path
-- (CurveNavigationComponentData, one 752-byte record): +20 the height above its route (40)
TYPES.retention, TYPES.curve = 0xFF67A367, 0x333C9A62
KINDS[TYPES.retention] = { name = 'target retention', stride = 24, keyed = true }
KINDS[TYPES.curve] = { name = 'flight path', stride = 752, keyed = true }
-- hit reactions (HitReactComponentData, 4836 bytes): +4 six reactions of 36 bytes (+0 the hit size: 1 light .. 4
-- massive, +4 the force a hit needs to stagger, +8 whether it staggers, +12 cooldown, +16 duration)
TYPES.hitreact = 0xD57D0101
KINDS[TYPES.hitreact] = { name = 'hit reaction', stride = 4836, keyed = true }
-- status effects taken (StatusEffectReceiverComponentData, 46600 bytes): 8 body parts of 5816 bytes from +0 (+0 the
-- part's name), each with 33 susceptibilities of 176 bytes from +8 (+140 the kind: 6 fire, 10 acid, 12 fire (bots),
-- 20 electric, 27 / 28 gas; +144 / +148 thresholds, +168 the damage it takes from it (x))
-- suppression: SensorDangerComponentData (12 bytes, 4 after the records): +0 the most danger it builds, +4 the radius
-- around it where shots count, +8 reacts to near misses (bool byte); TargetingComponentData (64 bytes): +36 how much
-- danger throws off its aim, +40 how fast that wears off (per second), +44 the most it can
TYPES.danger, TYPES.targeting = 0xC677F538, 0x2C0968D2
KINDS[TYPES.danger] = { name = 'danger sensor', stride = 12, keyed = true, slack = 4 }
KINDS[TYPES.targeting] = { name = 'targeting', stride = 64, keyed = true }
TYPES.status_rx = 0x6062C233
KINDS[TYPES.status_rx] = { name = 'status effects taken', stride = 46600, keyed = true }
KINDS[TYPES.loadout] = { name = 'loadout', stride = 32 }

KINDS[TYPES.loadout].parse = function(blob, stride)
    local total, count, live, keys, found = #blob, 0, 0, {}, nil
    while count * 16 + 16 <= total do
        local at = count * 16
        local slot, pad = u32(blob, at + 8), u32(blob, at + 12)
        if pad ~= 0 or slot > 100000 then break end
        local lo, hi = u32(blob, at), u32(blob, at + 4)
        count = count + 1
        if lo ~= 0 or hi ~= 0 then live = live + 1; keys[live] = { count - 1, lo, hi, slot } end
        local records = math.floor((total - count * 16) / stride)
        if count == 2 * live and count >= 64 and records > 0 then   -- (a few buckets always sit near home)
            local fits = true
            for k = 1, live do
                local b = keys[k]
                local home = ((b[3] % count) * (4294967296 % count) + b[2]) % count
                if (b[1] - home) % count >= 16 or b[4] >= records then fits = false; break end
            end
            if fits then
                if found then return nil, 'two layouts fit' end
                found = count
            end
        end
    end
    if not found then return nil, 'no layout fits' end
    local index, entries = {}, 0
    for k = 0, found - 1 do
        local key = blob:sub(k * 16 + 1, k * 16 + 8)
        if key ~= string.rep('\0', 8) and not index[key] then
            index[key] = found * 16 + u32(blob, k * 16 + 8) * stride
            entries = entries + 1
        end
    end
    return index, entries
end

-- Primary and secondary weapons only: a support weapon put in another slot is not listed there (the armory
-- lists the weapons your account owns, and support weapons come with their stratagem; tested 2026-10-24).
MOD.slot = { NAMES = { [1] = 'Primary', [3] = 'Secondary' } }

-- Which slot a support weapon goes to when you pick it up (SHODAN Offline Integration): InteractableComponentData,
-- 8 zones of 136 bytes from +8, +40 the interaction (1 primary, 2 secondary, 3 support). Secondary made weapons
-- vanish, so only 1 and 3; only on a record with one weapon pickup zone
TYPES.interactable = 0xFCCA29DB
-- the names' and descriptions' text ids (EncyclopediaEntryComponentData, 56 bytes: +0 name, +8 in capitals, +20
-- description; MOD.rename)
TYPES.encyclopedia = 0x8A40FE2F
if MOD.offline then KINDS[TYPES.encyclopedia] = KINDS[TYPES.encyclopedia] or { name = 'encyclopedia', stride = 56, keyed = true } end
KINDS[TYPES.interactable] = { name = 'pickup', stride = 1104, keyed = true }
function MOD.slot.pickup_row(weapon, key)
    local t = tables[TYPES.interactable]
    local off = t and KINDS[TYPES.interactable].stride == 1104 and t.index[key]
    if not off then return end
    local found, count = nil, 0
    for zone = 0, 7 do
        local at = off + 8 + zone * 136
        local kind = peek4(t.copies[1] + HEADER_BYTES + at + 40)
        if (peek4(t.copies[1] + HEADER_BYTES + at) or 0) ~= 0 and kind and kind >= 1 and kind <= 3 then
            found, count = at + 40, count + 1
        end
    end
    local p = count == 1 and part('pickup_slot', TYPES.interactable, found, 'u32', 3)
    if not p or default_of(p.field) ~= 3 then return end
    p.field.limit = 4294967295
    local r = add_row(weapon, 'Pickup', 'pickup_slot', 'Picked up into', 'u32', { p }, 0, 255, 1, 1)
    r.label_of = function()
        local v = read_field(p.field)
        return 'Picked up into: ' .. (({ [1] = 'Primary slot', [2] = 'Secondary slot', [3] = 'Support slot' })[v] or tostring(v))
    end
    r.tip = { 'The interaction its pickup zone is (Interactable, the zone\'s +40): 1 primary slot, in place of your primary; '
              .. '2 secondary (the weapon has vanished); 3 the support slot. Any other value is written as typed.' }
end

function MOD.slot.row(weapon)
    local t = tables[TYPES.loadout]
    local off = t and t.index[weapon.key]
    if not off then return end
    local f = field_at(TYPES.loadout, off + 4, 'u32', 100000)
    if not MOD.slot.NAMES[default_of(f) or 0] then return end
    local row = add_row(weapon, 'Loadout', 'slot', 'Slot (choice)', 'u32', { part('slot', TYPES.loadout, off + 4, 'u32', 100000) }, 0, 255, 2, 2)
    row.choice = 'slot'
    row.label_of = function() return 'Slot: ' .. (MOD.slot.NAMES[read_field(f) or 0] or tostring(read_field(f))) end
    row.note = 'the armory list it is in: 1 primary, 3 secondary'
    MOD.slot.place(weapon, row)
end
-- at the bottom, above the projectile swap
function MOD.slot.place(weapon, row)
    table.remove(weapon.rows)
    local at = #weapon.rows + 1
    for k, r in ipairs(weapon.rows) do if r.section == 'Projectile swap' then at = k; break end end
    table.insert(weapon.rows, at, row)
end

-- A pod with one weapon on the rack's left (node 76C6D1E3, side 2: the Leveller, Meltagun, Breaching Hammer): 2 puts a
-- copy on the right (slot 1 = slot 0's 64 bytes with the right's node 7FE13CFF, side 1, as the Commando's) and
-- drops both (+556 2). Parts: slot 1's 16 words, then +556.
MOD.pod = { LEFT = 0x76C6D1E3, RIGHT = 0x7FE13CFF }
function MOD.pod.twin_row(entry, rack)
    local parts = {}
    for w = 0, 15 do parts[#parts + 1] = part('pod_twin' .. (w > 0 and ('_' .. w) or ''), TYPES.rack, rack + 64 + w * 4, 'u32', 4294967295) end
    parts[#parts + 1] = part('pod_twin_count', TYPES.rack, rack + 556, 'u32', 8)
    local row = add_row(entry, 'Hellpod', 'pod_twin', 'Items per drop', 'u32', parts, 1, 2, 1, 1)
    row.choice, row.each, row.rack = 'pod_twin', true, rack
    row.note = '2 puts a second one on the other side of the pod'
    -- the count itself, free (0-8, the rack's slots); the right slot's 16 words: 实体组件 › 地狱舱 › 挂架
    add_row(entry, 'Hellpod', 'pod_twin_count_raw', 'Items per drop (count)', 'u32', { parts[17] }, 0, 8, 1, 1).note =
        'spawn_payload_size: how many of the rack\'s slots come down'
end
function MOD.pod.value(row, default)
    local get = default and default_of or read_field
    return (get(row.parts[3].field) == MOD.pod.RIGHT and (get(row.parts[17].field) or 0) >= 2) and 2 or 1
end

-- Holster position (issue #101): a primary carried on the back, or on the hip where pistols hang. EquipmentComponent
-- +28 the holster node (primaries EC864C61, pistols CCF501C7), +32 / +44 its rotation (deg) / position offsets
-- (pistols: none). Hip writes the pistols' node and no offsets; Back puts the weapon's own back.
MOD.holster = { BACK = 0xEC864C61, HIP = 0xCCF501C7, NAMES = { [0] = 'Back', [1] = 'Hip' } }
function MOD.holster.row(weapon)
    local t = tables[TYPES.equipment]
    local off = t and t.index[weapon.key]
    if not off or default_of(field_at(TYPES.equipment, off + 28, 'u32', 4294967295)) ~= MOD.holster.BACK then return end
    local parts = { part('holster', TYPES.equipment, off + 28, 'u32', 4294967295) }
    for k = 1, 6 do
        parts[k + 1] = part('holster_' .. k, TYPES.equipment, off + 28 + 4 * k, 'f32', 100000)
        parts[k + 1].field.signed, parts[k + 1].field.limit = true, math.max(parts[k + 1].field.limit or 0, 100000)
    end
    local row = add_row(weapon, 'Loadout', 'holster', 'Holster position (choice)', 'u32', parts, 0, 1, 1, 1)
    row.choice, row.each = 'holster', true
    row.label_of = function() return 'Holster: ' .. MOD.holster.NAMES[MOD.holster.value(row)] end
    row.note = 'where it hangs when put away: 0 on the back, 1 on the hip'
    MOD.slot.place(weapon, row)
    -- the same seven fields, each free (the choice above writes them together; a value set here is saved once,
    -- whichever row set it)
    local node = add_row(weapon, 'Loadout', 'holster_node', 'Holster node (hash)', 'u32', { parts[1] }, 0, 4294967295, 1, 1)
    node.note = 'the wielder node it hangs from: EC864C61 back, CCF501C7 hip (pistols)'
    MOD.slot.place(weapon, node)
    for k, l in ipairs({ 'Holster rotation X (deg)', 'Holster rotation Y (deg)', 'Holster rotation Z (deg)',
                         'Holster offset X (m)', 'Holster offset Y (m)', 'Holster offset Z (m)' }) do
        MOD.slot.place(weapon, add_row(weapon, 'Loadout', 'holster_' .. k .. '_raw', l, 'f32', { parts[k + 1] },
                                       k <= 3 and -360 or -10, k <= 3 and 360 or 10, k <= 3 and 1 or 0.01, k <= 3 and 5 or 0.05))
    end
end
function MOD.holster.value(row, default)
    return (default and default_of or read_field)(row.parts[1].field) == MOD.holster.HIP and 1 or 0
end
-- a choice row whose value is not its first part's (row_value)
MOD.choice_value = { holster = MOD.holster.value, pod_twin = MOD.pod.value }

-- ---------------------------------------------------------------- scan client
-- Once the tables are in: resolve every weapon, then apply the saved values, a slice per frame.
local progress = nil

-- The lists built once every table is found: one step per frame (phase 'building'), so no frame
-- carries them all. Each step: { name, function, what failing means }.
local function become_ready(final)
    state.build_steps = {
        { 'stratagems', build_stratagems, 'stratagems: not listed: ' },
        { 'attachments', KINDS[TYPES.items].build, 'attachments: not listed: ' },
        { 'passives', KINDS[TYPES.passive].build, 'armor passives: not listed: ' },
        { 'armor weight', MOD.kits.build, 'armor weight: not listed: ' },
        { 'boosters', MOD.boosters.build, 'boosters: not listed: ' },
        { 'enemies', MOD.enemy.build, 'enemies: not listed: ' },
    }
    set_status('building', 'listing stratagems, attachments and armor passives')
end

-- The next build step; once all are done, weapons are resolved and saved values applied.
function state.build_some()
    local build_steps = state.build_steps
    local step = table.remove(build_steps, 1)
    if step then
        local ok, why = pcall(step[2])
        if not ok then log(step[3] .. tostring(why)) end
        if #build_steps > 0 then return end
    end
    state.build_steps = nil
    progress = { next = 1 }
    pending, apply_at = {}, 1
    if settings.changes then
        for _, o in ipairs(overrides) do pending[#pending + 1] = { hash = o.hash, id = o.id, value = o.value } end
    end
    set_status('preparing', 'resolving weapons and applying saved values')
end

-- Every field's game value, read before this mod writes any: otherwise a field's default is read
-- when first needed, and holds another mod's value if one edited it first (an ammo mod's damage).
-- Reset, "was" and changes off then go back to the game's own value. Fields already read keep theirs.
function MOD.snapshot_defaults(progress, deadline)
    if not progress.keys then
        progress.keys, progress.read = {}, 1
        for key in pairs(fields) do progress.keys[#progress.keys + 1] = key end
    end
    local keys = progress.keys
    while progress.read <= #keys do
        default_of(fields[keys[progress.read]])
        progress.read = progress.read + 1
        if progress.read % 256 == 0 and api.now() >= deadline then return false end
    end
    return true
end

local function prepare(deadline)
    if not progress.resolved then
        if not progress.base_resolved then
            if not resolve_some(progress, deadline) then return end
            progress.base_resolved=true
        end
        if MOD.offline then
            if not require('startup_work').run(progress,deadline,api.now,function()
            local function drop_page(page)
                if by_hash[page.hash]==page then by_hash[page.hash]=nil end
                for _,r in ipairs(page.rows or{})do
                    for _,p in ipairs(r.parts or{})do
                        local users=p.field and p.field.users
                        if users then
                            for i=#users,1,-1 do if users[i]==page then table.remove(users,i) end end
                        end
                    end
                end
            end
            for _,page in ipairs(MOD.component_catalog and MOD.component_catalog.all_views or{})do
                drop_page(page)
            end
            for _,page in ipairs(MOD.health_components and MOD.health_components.pages or {})do
                drop_page(page)
            end
            for _,page in ipairs(MOD.drown_components and MOD.drown_components.pages or {})do
                drop_page(page)
            end
            for _,page in ipairs(MOD.shield_components and MOD.shield_components.pages or {})do
                drop_page(page)
            end
            for _,views in ipairs({MOD.throwable_components or{},MOD.thrower_components or{},MOD.minefield_components or{},
                    MOD.mine_spawner_components or{},MOD.faction_components or{},MOD.mount_components or{},
                    MOD.inventory_components or{},MOD.sensor_eye_components or{},MOD.turret_components or{},
                    MOD.eagle_components or{},MOD.eagle_spawner_components or{}})do
                for _,page in ipairs(views.pages or {})do drop_page(page) end
            end
            MOD.health_components=require('health_components').build({table=tables[TYPES.health],kind=TYPES.health,
                weapons=weapons,by_hash=by_hash,field_at=field_at,read=read_field,add_row=add_row,
                schemas=(rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE')or{}).schemas,log=log,
                wrap=function(...)return MOD.component_groups.wrap(...)end,
                translate=settings.tr,
                names=rawget(_G,'SHODAN_COMPONENT_NAMES'),zone_name=MOD.enemy.zone_name,lang=function()return settings.lang end,
                zone_present=function(offset)
                    local t=tables[TYPES.health]
                    return t and (peek4(t.copies[1]+HEADER_BYTES+offset)or 0)~=0
                end})
            state.health_component_count=#MOD.health_components.pages
            -- 淹没: DrownableComponentData, every entity that has it (the helldiver's water stats, generalised)
            MOD.drown_components=require('drown_components').build({table=tables[TYPES.drown],kind=TYPES.drown,
                weapons=weapons,by_hash=by_hash,field_at=field_at,read=read_field,add_row=add_row,log=log,
                schemas=(rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE')or{}).schemas,
                names=rawget(_G,'SHODAN_COMPONENT_NAMES'),lang=function()return settings.lang end})
            state.drown_component_count=#MOD.drown_components.pages
            -- 护盾: ShieldComponentData, every entity that has it, every field of its record
            MOD.shield_components=require('shield_components').build({table=tables[TYPES.shield],kind=TYPES.shield,
                weapons=weapons,by_hash=by_hash,field_at=field_at,read=read_field,add_row=add_row,log=log,
                schemas=(rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE')or{}).schemas,
                status_name=function(id)local ok,name=pcall(MOD.status_component.name,id);return ok and name or nil end,
                names=rawget(_G,'SHODAN_COMPONENT_NAMES'),lang=function()return settings.lang end})
            state.shield_component_count=#MOD.shield_components.pages
            -- 投掷物: ThrowableComponentData and ThrowerComponentData, every field of their records
            for _,views in pairs(MOD.weapon_component_views or{})do
                for _,page in ipairs(views.pages or {})do drop_page(page) end
            end
            local function view(spec,kind,lazy)
                return require('component_view').build(type(spec)=='string'and require(spec)or spec,{table=tables[kind],kind=kind,lazy_rows=true,
                    weapons=weapons,by_hash=by_hash,field_at=field_at,read=read_field,add_row=add_row,log=log,
                    default_of=default_of,schemas=(rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE')or{}).schemas,
                    -- an ID of another record (the mines' explosion): its badge, double-click to open it, only IDs
                    -- this game build has
                    reference=function(row,ref,f,value)
                        row.reference_type=ref
                        local t=tables[MOD.references.KINDS[ref]]
                        if not t then return end
                        row.choice='reference'
                        f.allowed=f.allowed or setmetatable({[0]=true,[value]=true,why='No matching record in this game build.'},
                            {__index=function(_,target)return t~=nil and t.index[target]~=nil end})
                    end,
                    -- a field an original page reads as a choice (the SEAF weapons): the choice's name
                    choice_label=function(choice,value)
                        if choice~='gun'then return nil end
                        local g=MOD.enemy.gun_choices().by_id[value or 0]
                        return g and g.label
                    end,
                    names=rawget(_G,'SHODAN_COMPONENT_NAMES'),lang=function()return settings.lang end})
            end
            MOD.throwable_components=view('throwable_components',TYPES.throwable)
            MOD.thrower_components=view('thrower_components',TYPES.thrower)
            -- 地雷: MinefieldComponentData (a mine) and MineSpawnerComponentData (how a minefield lays them out)
            MOD.minefield_components=view('minefield_components',TYPES.minefield)
            MOD.mine_spawner_components=view('mine_spawner_components',TYPES.mine_spawner)
            -- 阵营: FactionComponentData
            MOD.faction_components=view('faction_components',TYPES.faction)
            -- 挂载: MountComponentData
            MOD.mount_components=view('mount_components',TYPES.mount)
            -- 背包: InventoryComponentData (default equipment, stims)
            MOD.inventory_components=view('inventory_components',TYPES.inventory)
            -- 炮塔与制导: SensorEyeComponentData and TurretComponentData
            MOD.sensor_eye_components=view('sensor_eye_components',TYPES.sensor)
            MOD.turret_components=view('turret_components',TYPES.turret)
            -- 飞鹰: EagleComponentData and EagleSpawnerComponentData
            MOD.eagle_components=view('eagle_components',TYPES.eagle)
            MOD.eagle_spawner_components=view('eagle_spawner_components',TYPES.eagle_spawner)
            -- 武器组件 / 武器类型 / 武器配件: every weapon component (rows made when a page is first shown)
            MOD.weapon_component_views,MOD.weapon_component_kinds={},{}
            for _,spec in ipairs(MOD.weapon_components.SPECS)do
                MOD.weapon_component_views[spec.KEY]=view(spec,spec.HASH,true)
                MOD.weapon_component_kinds[#MOD.weapon_component_kinds+1]={kind=spec.KEY,slot=spec.SLOT}
            end
            MOD.component_catalog=require('entity_catalog').build({health=MOD.health_components,drown=MOD.drown_components,
                shield=MOD.shield_components,throwable=MOD.throwable_components,thrower=MOD.thrower_components,
                minefield=MOD.minefield_components,mine_spawner=MOD.mine_spawner_components,faction=MOD.faction_components,
                mount=MOD.mount_components,inventory=MOD.inventory_components,sensor_eye=MOD.sensor_eye_components,
                turret=MOD.turret_components,eagle=MOD.eagle_components,eagle_spawner=MOD.eagle_spawner_components,
                extra_views=MOD.weapon_component_views,extra_kinds=MOD.weapon_component_kinds,
                metadata=rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE'),bridge=rawget(_G,'SHODAN_DEMOLITION_BRIDGE'),
                weapons=weapons,by_hash=by_hash,add_row=add_row,lang=function()return settings.lang end})
            state.component_entity_count=#MOD.component_catalog.records
            MOD.attach_weapon_components()
            MOD.attach_eagle_components()
            MOD.attach_stratagem_components()
            MOD.build_component_records()
            MOD.record_names.seed_tables()
            MOD.identity.build({tables=tables,font_list=KINDS[MOD.identity.FONT].list,weapons=weapons,
                by_hash=by_hash,field_at=field_at,read=read_field,add_row=add_row,default_of=default_of,
                schemas=(rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE')or{}).schemas,
                names=rawget(_G,'SHODAN_COMPONENT_NAMES'),lang=function()return settings.lang end,log=log,
                bytes=function(kind)local t=tables[kind];return api.read(t.copies[1]+HEADER_BYTES,t.payload)end})
            MOD.preload.build({tables=tables,kinds=KINDS,stratagem_groups=stratagem_groups,weapons=weapons,
                query=function()return state.preload_query and state.preload_query()or''end,
                by_hash=by_hash,field_at=field_at,read=read_field,add_row=add_row,default_of=default_of,
                schemas=(rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE')or{}).schemas,
                names=rawget(_G,'SHODAN_COMPONENT_NAMES'),lang=function()return settings.lang end,log=log,
                bytes=function(kind)local t=tables[kind];return api.read(t.copies[1]+HEADER_BYTES,t.payload)end})
            MOD.planet.build({tables=tables,kinds=KINDS,weapons=weapons,by_hash=by_hash,field_at=field_at,
                read=read_field,add_row=add_row,default_of=default_of,
                schemas=(rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE')or{}).schemas,
                names=rawget(_G,'SHODAN_COMPONENT_NAMES'),lang=function()return settings.lang end,log=log,
                bytes=function(kind)local t=tables[kind];return api.read(t.copies[1]+HEADER_BYTES,t.payload)end})
            MOD.player_save_view.build({weapons=weapons,by_hash=by_hash,kit_names=MOD.kit_names or{},
                tr=settings.tr,lang=function()return settings.lang end})
            end)then return end
        end
        progress.resolved = true
    end
    if not progress.demolition_migrated then
        local bridge = MOD.offline and rawget(_G, 'SHODAN_DEMOLITION_BRIDGE')
        if bridge then
            local records, kept = {}, {}
            for _, o in ipairs(overrides) do
                local w = by_hash[o.hash]
                local p = w and w.by_id[o.id]
                if p and p.field.demolition and not o.demolition then
                    records[#records + 1] = {field=p.field,value=o.value}
                else kept[#kept + 1] = o end
            end
            local ok, why = bridge:migrate(records)
            if not ok then set_status('gave_up', 'Demolition settings migration failed: ' .. tostring(why)); return end
            overrides = kept
            local ordinary = {}
            for _, o in ipairs(pending) do
                local w = by_hash[o.hash]
                local p = w and w.by_id[o.id]
                if not (p and p.field.demolition) then ordinary[#ordinary + 1] = o end
            end
            pending, apply_at = ordinary, 1
            MOD.sync_demolition()
            if #records > 0 then
                local saved, problem = save_config()
                if not saved then set_status('gave_up', 'Could not save unified demolition settings: ' .. tostring(problem)); return end
            end
        end
        progress.demolition_migrated = true
    end
    if not progress.installed_rows then MOD.installed_rows();progress.installed_rows=true end
    if not MOD.snapshot_defaults(progress, deadline) then return end
    if not MOD.restore_installed(progress,deadline)then return end
    if api.now() >= deadline or not apply_config(deadline) then return end
    progress = nil
    MOD.enemy.faction_refresh()
    local missing = {}
    for _, kind in ipairs(KIND_ORDER) do
        if not tables[kind] then missing[#missing + 1] = KINDS[kind].name end
    end
    for _, w in ipairs(weapons) do
        if w.stratagem and not w.stratagem.def and not w.stratagem.native and #STRATAGEMS > 0 and w.stratagem.family ~= 'support' then
            log('stratagem ' .. w.name .. ' (' .. w.hash .. '): definition not found; cooldown not editable')
        elseif w.stratagem and w.stratagem.def and w.stratagem.nodes[1] == nil then
            local keys = {}
            for k, key in ipairs(w.stratagem.payloads) do keys[k] = string.format('%08X%08X', u32(key, 4), u32(key, 0)) end
            log('stratagem ' .. w.name .. ' (' .. w.hash .. '): ' .. #w.rows .. ' rows, payloads ' .. table.concat(keys, ' '))
        end
    end
    set_status('ready', state.weapons .. ' weapons, ' .. (state.throwables or 0) .. ' throwables, ' ..
               (state.stratagems or 0) .. ' stratagems, ' .. (state.vehicles or 0) .. ' vehicles, ' ..
               (state.attachments or 0) .. ' attachments and ' ..
               (state.passives or 0) .. ' armor passives editable; ' ..
               state.applied .. ' saved value(s) applied' ..
               (#pending > 0 and (', ' .. #pending .. ' waiting') or '') ..
               (#missing > 0 and ('; tables not found: ' .. table.concat(missing, ', ')) or ''))
end

local function searching() return state.phase == 'searching' end

local function wants(kind, address)
    local permitted = rawget(_G, 'SHODAN_OFFLINE_TABLE_ADDRESS')
    if MOD.offline and type(permitted) == 'function' and not permitted(address) then return false end
    return KINDS[kind] ~= nil and not parsed_blocks[address]
end

local function handle_table(address, kind, payload, blob)
    local permitted = rawget(_G, 'SHODAN_OFFLINE_TABLE_ADDRESS')
    if MOD.offline and type(permitted) == 'function' and not permitted(address) then return end
    local spec = KINDS[kind]
    if not spec or parsed_blocks[address] then return end
    if spec.found then   -- one of many tables taken by address (the destruction settings)
        spec.found[#spec.found + 1] = address
        parsed_blocks[address] = true
        return
    end
    local parse = spec.parse or (spec.keyed and parse_keyed or parse_rows)
    local started = api.now()
    local index, info, records_layout = parse(blob, spec.stride, spec, address)
    -- game build 25988413 (2026-10-20) changed some records: its layouts are tried after the first one, and the
    -- one that fits is kept (`offsets`: where fields moved, old offset -> new)
    for _, layout in ipairs(not index and spec.layouts or {}) do
        local was = { spec.stride, spec.slack, spec.offsets }
        spec.stride, spec.slack, spec.offsets = layout.stride, layout.slack, layout.offsets
        index, info, records_layout = parse(blob, spec.stride, spec, address)
        if index then
            log(string.format('%s: layout of game build 25988413 (%d bytes a record)', spec.name, spec.stride))
            break
        end
        spec.stride, spec.slack, spec.offsets = was[1], was[2], was[3]
    end
    local took = (api.now() - started) * 1000
    if not index then
        log(spec.name .. ' table at ' .. hex(address) .. ' not usable yet: ' .. info)
        return
    end
    local table_type = kind
    if spec.groups then
        -- each group is its own table; copies of one group have its size and first row
        local list = kind == T_STRATAGEM and stratagem_groups or spec.list
        kind = spec.group_key and spec.group_key(blob,address)
               or ((kind == T_STRATAGEM and 'stratagems' or spec.name) .. ' ' .. payload .. ' ' .. (u32(blob, 16 + (spec.id_at or 0)) or 0))
        if not tables[kind] then list[#list + 1] = kind end
    end
    local entry = tables[kind]
    if entry and entry.payload ~= payload then
        log(spec.name .. ' table at ' .. hex(address) .. ' has another size; ignored')
        parsed_blocks[address] = true
        return
    end
    if not entry then
        entry = { payload = payload, index = index, entries = info, copies = {}, type = table_type, records_layout=records_layout }
        tables[kind] = entry
        state.tables = state.tables + 1
    end
    entry.copies[#entry.copies + 1] = address
    parsed_blocks[address] = true
    log(string.format('%s table at %s: %d entries (parsed in %.2f ms)', spec.name, hex(address), info, took))
end

local function after_pass(pass, final)
    if not searching() then return end
    if have_all_tables() or final then become_ready(final) end
end

-- Offline buffers are already known to the host. Parse those exact headers in
-- bounded batches; no process-wide discovery or startup frame delay is needed.
function state.read_offline_tables(deadline)
    local scan = state.offline_scan
    if not scan then
        local provider = rawget(_G, 'SHODAN_OFFLINE_TABLES')
        assert(type(provider) == 'function', 'Offline table source is unavailable')
        local blocks = provider()
        assert(type(blocks) == 'table' and #blocks > 0, 'No loaded game tables')
        scan = { blocks = blocks, next = 1, started = api.now() }
        state.offline_scan = scan
    end
    while scan.next <= #scan.blocks do
        local block = scan.blocks[scan.next]
        local address, kind, payload = block.address, block.kind, block.payload
        assert(type(address) == 'number' and address > 65536 and type(kind) == 'number'
            and type(payload) == 'number' and payload >= 0, 'Invalid offline table descriptor')
        if payload >= 16 and payload <= MAX_PAYLOAD and wants(kind, address) then
            local header = api.read(address, HEADER_BYTES)
            assert(header and header:sub(1, 8) == NEEDLE and u32(header, 8) == kind
                and u32(header, 12) == payload, 'Loaded game table header changed')
            local blob = assert(api.read(address + HEADER_BYTES, payload), 'Could not read loaded game table')
            handle_table(address, kind, payload, blob)
        end
        scan.next = scan.next + 1
        if scan.next <= #scan.blocks and api.now() >= deadline then return end
    end
    state.offline_table_count = #scan.blocks
    log(string.format('offline: %d registered tables processed in %.2f ms',#scan.blocks,(api.now()-scan.started)*1000))
    state.offline_scan = nil
    after_pass(1, true)
end

-- The tables are still where they were (checked when the panel opens); if not, scan again.
local hub = nil
local function tables_intact()
    for kind, entry in pairs(tables) do
        for _, block in ipairs(entry.fixed and {} or entry.copies) do   -- (fixed: the host's own buffer, no header)
            local header = api.read(block, HEADER_BYTES)
            if not header or header:sub(1, 8) ~= NEEDLE or u32(header, 8) ~= entry.type or u32(header, 12) ~= entry.payload then
                return false
            end
        end
    end
    return true
end

local function rescan()
    log('a settings table moved; scanning again')
    tables, parsed_blocks, stratagem_groups = {}, {}, {}
    KINDS[TYPES.items].list = {}
    KINDS[TYPES.passive].list = {}
    KINDS[TYPES.kit].list = {}
    KINDS[MOD.identity.FONT].list = {}
    MOD.preload.clear(KINDS)
    MOD.planet.clear(KINDS)
    KINDS[TYPES.destruction].found, KINDS[TYPES.destruction].told = {}, nil
    state.tables = 0
    state.offline_scan = nil
    set_status('searching', 'a table moved; scanning again')
    if hub then hub.wake() end
end

-- ---------------------------------------------------------------- windows input
local user, own_pid = nil, nil
local point, rect, pid = nil, nil, nil

local function build_input()
    for _, declaration in ipairs({
        'void *GetForegroundWindow(void);',
        'uint32_t GetWindowThreadProcessId(void*,void*);',
        'uint32_t GetCurrentProcessId(void);',
        'int GetCursorPos(void*);',
        'int ScreenToClient(void*,void*);',
        'int GetClientRect(void*,void*);',
        'int16_t GetAsyncKeyState(int key);',
        'int16_t GetKeyState(int key);',
        'uint32_t MapVirtualKeyW(uint32_t code, uint32_t type);',
        'int ToUnicode(uint32_t vk, uint32_t scan, const uint8_t *state, uint16_t *text, int size, uint32_t flags);',
        'int ShowCursor(int show);',
        'int ClipCursor(const void *rect);',
        'int GetClipCursor(void *rect);',
        'void *GetModuleHandleA(const char *name);',
        'typedef struct { uint16_t page; uint16_t usage; uint32_t flags; void *target; } shodan_raw_device;',
        'uint32_t GetRegisteredRawInputDevices(shodan_raw_device *devices, uint32_t *count, uint32_t size);',
        'int RegisterRawInputDevices(const shodan_raw_device *devices, uint32_t count, uint32_t size);',
        'uint32_t GetDoubleClickTime(void);',
        'uint32_t GetCurrentThreadId(void);',
        'intptr_t GetWindowLongPtrW(void *window, int index);',
        'intptr_t SetWindowLongPtrW(void *window, int index, intptr_t value);',
        'void *GetProcAddress(void *module, const char *name);',
        'void *VirtualAlloc(void *address, size_t size, uint32_t type, uint32_t protect);',
        'int FlushInstructionCache(void *process, const void *address, size_t size);',
        'void *GetCurrentProcess(void);',
        'void *ShellExecuteW(void *window, const uint16_t *op, const uint16_t *file, const uint16_t *params, const uint16_t *dir, int show);',
        'int OpenClipboard(void *owner);',
        'int EmptyClipboard(void);',
        'void *SetClipboardData(uint32_t format, void *data);',
        'void *GetClipboardData(uint32_t format);',
        'int CloseClipboard(void);',
        'void *GlobalAlloc(uint32_t flags, size_t bytes);',
        'void *GlobalLock(void *data);',
        'int GlobalUnlock(void *data);',
        'size_t GlobalSize(void *data);',
        'int MultiByteToWideChar(uint32_t page, uint32_t flags, const char *text, int bytes, uint16_t *wide, int chars);',
        'int WideCharToMultiByte(uint32_t page, uint32_t flags, const uint16_t *wide, int chars, char *text, int bytes, const char *def, void *used);',
    }) do pcall(ffi.cdef, declaration) end
    user = ffi.load('user32')
    own_pid = ffi.load('kernel32').GetCurrentProcessId()
    point, rect, pid = ffi.new('int32_t[2]'), ffi.new('int32_t[4]'), ffi.new('uint32_t[1]')
end

local function focused_window()
    local window = user.GetForegroundWindow()
    if window == nil then return nil end
    if user.GetWindowThreadProcessId(window, ffi.cast('void *', pid)) == 0 or pid[0] ~= own_pid then return nil end
    return window
end

-- UTF-8 text as a zero-ended UTF-16 string (and its length in characters, the zero included)
function settings.wide(text)
    local kernel = ffi.load('kernel32')
    local n = kernel.MultiByteToWideChar(65001, 0, text, -1, nil, 0)
    local out = ffi.new('uint16_t[?]', math.max(1, n))
    kernel.MultiByteToWideChar(65001, 0, text, -1, out, n)
    return out, n
end

-- Opens a link or folder with Windows' default program (the browser, Explorer).
function settings.open(target)
    local ok = pcall(function()
        ffi.load('shell32').ShellExecuteW(nil, (settings.wide('open')), (settings.wide(target)), nil, nil, 1)
    end)
    return ok
end

-- Puts text on the clipboard.
function settings.copy(text)
    local kernel = ffi.load('kernel32')
    local wide, n = settings.wide(text)
    local data = kernel.GlobalAlloc(0x0002, n * 2)          -- GMEM_MOVEABLE
    if data == nil then return false end
    local at = kernel.GlobalLock(data)
    if at == nil then return false end
    ffi.copy(at, wide, n * 2)
    kernel.GlobalUnlock(data)
    if user.OpenClipboard(nil) == 0 then return false end
    user.EmptyClipboard()
    local ok = user.SetClipboardData(13, data) ~= nil      -- CF_UNICODETEXT
    user.CloseClipboard()
    return ok
end

-- Reads UTF-8 text from the clipboard (nil when unavailable).
function settings.paste()
    local kernel = ffi.load('kernel32')
    if user.OpenClipboard(nil) == 0 then return nil end
    local data = user.GetClipboardData(13)                  -- CF_UNICODETEXT
    if data == nil then user.CloseClipboard(); return nil end
    local at = kernel.GlobalLock(data)
    if at == nil then user.CloseClipboard(); return nil end
    local wide = ffi.cast('const uint16_t *', at)
    local max_chars = math.floor(tonumber(kernel.GlobalSize(data)) / 2)
    local len = 0
    while len < max_chars and wide[len] ~= 0 do len = len + 1 end
    local text = ''
    if len > 0 then
        local n = kernel.WideCharToMultiByte(65001, 0, wide, len, nil, 0, nil, nil)
        if n > 0 then
            local buf = ffi.new('char[?]', n)
            kernel.WideCharToMultiByte(65001, 0, wide, len, buf, n, nil, nil)
            text = ffi.string(buf, n)
        end
    end
    kernel.GlobalUnlock(data)
    user.CloseClipboard()
    return text
end

local VK = { Up = 0x26, Down = 0x28, Left = 0x25, Right = 0x27, PageUp = 0x21, PageDown = 0x22,
             Delete = 0x2E, Shift = 0x10, Insert = 0x2D, Home = 0x24, End = 0x23, Pause = 0x13,
             ScrollLock = 0x91, Ctrl = 0x11, Enter = 0x0D, Backspace = 0x08, Escape = 0x1B }
for n = 1, 12 do VK['F' .. n] = 0x6F + n end
for n = 0, 9 do VK['Key' .. n] = 0x30 + n end

local function key_down(vk) return user.GetAsyncKeyState(vk) < 0 end

-- Typing (preset names): the keys that can make a character (space, digits, letters, numpad,
-- punctuation), turned into text by the player's keyboard layout with Shift, Caps Lock and
-- AltGr as they are. '#' is left out (it starts a comment in the preset files).
local TEXT_KEYS = { 0x20, 0xE2 }
for vk = 0x30, 0x39 do TEXT_KEYS[#TEXT_KEYS + 1] = vk end
for vk = 0x41, 0x5A do TEXT_KEYS[#TEXT_KEYS + 1] = vk end
for vk = 0x60, 0x6F do TEXT_KEYS[#TEXT_KEYS + 1] = vk end
for vk = 0xBA, 0xC0 do TEXT_KEYS[#TEXT_KEYS + 1] = vk end
for vk = 0xDB, 0xDF do TEXT_KEYS[#TEXT_KEYS + 1] = vk end
for _, vk in ipairs(TEXT_KEYS) do VK['T' .. vk] = vk end
local key_char
do
    local key_state, key_text = nil, nil

    local function utf8_char(c)
        if c < 0x80 then return string.char(c) end
        if c < 0x800 then return string.char(0xC0 + math.floor(c / 64), 0x80 + c % 64) end
        return string.char(0xE0 + math.floor(c / 4096), 0x80 + math.floor(c / 64) % 64, 0x80 + c % 64)
    end

    key_char = function(vk)
        if not key_state then key_state, key_text = ffi.new('uint8_t[256]'), ffi.new('uint16_t[4]') end
        ffi.fill(key_state, 256)
        for _, k in ipairs({ 0x10, 0x11, 0x12, 0xA0, 0xA1, 0xA2, 0xA3, 0xA4, 0xA5 }) do
            if key_down(k) then key_state[k] = 0x80 end
        end
        if user.GetKeyState(0x14) % 2 == 1 then key_state[0x14] = 1 end     -- Caps Lock on (low bit)
        key_state[vk] = 0x80
        -- flag 4: leaves the keyboard's own state (dead keys) alone
        if user.ToUnicode(vk, user.MapVirtualKeyW(vk, 0), key_state, key_text, 4, 4) ~= 1 then return nil end
        local c = key_text[0]
        if c < 32 or c == 35 or c == 127 or (c >= 0xD800 and c < 0xE000) then return nil end
        return utf8_char(c)
    end
end

