MOD.enemy.LABELS = { EnemyData = { 'Enemy data', '敌人数据', '敵人數據' }, Enemies = { 'Enemies', '敌人', '敵人' },
                     ['All enemies'] = { 'All enemies', '所有敌人', '所有敵人' },
                     [MOD.enemy.GLOBAL_NOTE] = { MOD.enemy.GLOBAL_NOTE, '一次调整虫族、机器人、光能者的所有敌人，与各阵营页的倍率相乘。在各自页面修改过的敌人保留其数值。',
