function MOD.attach_weapon_components()
    MOD.page_changed_cache=nil
    local primary_specs, fallback_specs = {}, {}
    for _, spec in ipairs(MOD.weapon_components.SPECS) do
        if spec.SUB~='creature'and spec.SUB~='character'then
            primary_specs[#primary_specs + 1] = { spec = spec, view = MOD.weapon_component_views[spec.KEY], sub = spec.SUB or 'weapon' }
        end
    end
    for _, item in ipairs({
        { 'throwable_components', MOD.throwable_components, 'type' },
        { 'thrower_components', MOD.thrower_components, 'type' },
        { 'minefield_components', MOD.minefield_components, 'type' },
        { 'mine_spawner_components', MOD.mine_spawner_components, 'type' },
    }) do
        primary_specs[#primary_specs + 1] = { spec = require(item[1]), view = item[2], sub = item[3] }
    end
    for _, item in ipairs({
        { 'sensor_eye_components', MOD.sensor_eye_components, 'type' },
        { 'turret_components', MOD.turret_components, 'type' },
        { 'mount_components', MOD.mount_components, 'attach' },
        { 'inventory_components', MOD.inventory_components, 'attach' },
        { 'faction_components', MOD.faction_components, 'weapon' },
    }) do
        fallback_specs[#fallback_specs + 1] = { spec = require(item[1]), view = item[2], sub = item[3] }
    end
    require('weapon_component_groups').attach({weapons=weapons,slots=MOD.WEAPON_SLOTS,
        primary=primary_specs,fallback=fallback_specs,subs=MOD.WEAPON_COMP_SUBS,
        wrap=MOD.component_groups.wrap,text=MOD.nav.text,lang=function()return settings.lang end,
        changed=function(page)return MOD.page_changed(page)end})
end
-- The shared presentation of a page's components: a visible group band (组件组), each component collapsed by
-- default, and the component's own parameter groups inside. Used by 轨道编辑 and 飞鹰编辑; the Armory and
-- 人物数据 follow the same rule.
MOD.component_groups = {}
function MOD.component_groups.wrap(entry, groups, sub_label)
    local kept = {}
    for _, g in ipairs(groups) do if #g.rows > 0 or g.ensure_rows then kept[#kept + 1] = g end end
    if #kept == 0 then return end
    local counts={}
    for _,g in ipairs(kept)do if g.sub then counts[g.sub]=(counts[g.sub]or 0)+1 end end
    local sub_key = entry.hash .. ':components'
    local function sub_of() return MOD.nav.text(sub_label) .. ' (' .. #kept .. ')' end
    entry.field_keys = entry.field_keys or {}
    for _, g in ipairs(kept) do
        for _, row in ipairs(g.rows) do
            for _, p in ipairs(row.parts or {}) do
                if p.field and p.field.key then entry.field_keys[p.field.key] = true end
            end
        end
    end
    local function modified(rows)
        for _, r in ipairs(rows) do
            if r.hash64 and MOD.stratagem.hash_text(r)~=MOD.stratagem.hash_text(r,true)then return true end
            local v, d = row_value(r), row_value(r, true)
            if type(v) == 'number' and type(d) == 'number' and v ~= d then return true end
        end
        return false
    end
    for _, g in ipairs(kept) do
        local group_sub=g.sub or sub_key
        local group_sub_of=g.sub_label and function()return MOD.nav.text(g.sub_label)..' ('..counts[g.sub]..')'end or sub_of
        local component_of = function() return (g.label_of and g.label_of()or MOD.nav.text(g.label)) .. (g.hide_type and '' or (' (' .. g.type .. ')')) end
        local modified_fn = function() return g.modified and g.modified()or modified(g.rows) end
        g.load = function()
            if g.loaded then return end
            local rows=g.ensure_rows and g.ensure_rows()or g.rows
            local wrapped={}
            for _,row in ipairs(rows)do
                for _,p in ipairs(row.parts or{})do if p.field and p.field.key then entry.field_keys[p.field.key]=true end end
                wrapped[#wrapped+1]=setmetatable({component_sub=group_sub,component_count=#rows,component=g.type,
                    component_of=component_of,component_sub_of=group_sub_of,component_modified=modified_fn,collapsible=true},{__index=row})
            end
            g.rows=wrapped;g.loaded=true
            g.header.component_count=#wrapped
        end
        g.header = { id = 'collapsed_' .. g.type, label = g.type, section = g.type .. ':collapsed',
            component = g.type, component_of = component_of, component_sub = group_sub, component_sub_of = group_sub_of,
            component_count = g.count or #g.rows, component_modified = modified_fn,
            collapsed_component = true, collapsible = true, parts = {} }
        if not g.ensure_rows then g.load()end
    end
    local function sync_rows(focus)
        local visible, target = {}, nil
        for _, g in ipairs(kept) do
            if focus == g.type then target = #visible + 1 end
            if ui.expanded_components[entry.hash .. ':' .. g.type] then
                g.load()
                for _, row in ipairs(g.rows) do visible[#visible + 1] = row end
            else
                visible[#visible + 1] = g.header
            end
        end
        entry.rows = visible
        if target then
            ui.row = target
            if target < (ui.scroll or 1) then ui.scroll = target end
        end
        ui.row = math.max(1, math.min(ui.row or 1, #visible))
        ui.scroll = math.max(1, math.min(ui.scroll or 1, #visible))
    end
    ui.expanded_components = ui.expanded_components or {}
    entry.component_groups = kept
    entry.sync_rows = sync_rows
    sync_rows()
end
function MOD.component_groups.stratagem_page(entry)
    if entry.component_groups then return end
    local s = entry.stratagem
    if not s then return end
    local strat, rest = {}, {}
    for _, r in ipairs(entry.rows or {}) do
        if r.section and r.section:match('^StratagemType') then strat[#strat + 1] = r
        else rest[#rest + 1] = r end
    end
    local groups = {}
    if #strat > 0 then
        groups[#groups + 1] = { type = 'StratagemType', rows = strat,
            label = { 'Stratagem component', '战备组件', '戰備組件' } }
    end
    if s.family == 'orbital' then
        local bomb = {}
        for _, r in ipairs(rest) do
            if r.section == 'BombardmentType' then
                r.section, r.section_level = 'BombardmentType:identity', 'group'
                r.section_of = function() return MOD.nav.text({ 'Identity', '标识', '標識' }) end
                bomb[#bomb + 1] = r
            elseif r.section == 'Barrage' then
                r.section, r.section_level = 'BombardmentType:barrage', 'group'
                r.section_of = function() return MOD.nav.text({ 'Barrage parameters', '轰炸参数', '轟炸參數' }) end
                bomb[#bomb + 1] = r
            else
                bomb[#bomb + 1] = r
            end
        end
        if #bomb > 0 then
            groups[#groups + 1] = { type = 'BombardmentType', rows = bomb,
                label = { 'Bombardment component', '轰炸组件', '轟炸組件' } }
        end
        MOD.component_groups.wrap(entry, groups, { 'Orbital components', '轨道组件', '軌道組件' })
    elseif s.family == 'eagle' then
        local eagle, spawner = {}, {}
        for _, r in ipairs(rest) do
            if r.component == 'EagleComponentData' then eagle[#eagle + 1] = r
            elseif r.component == 'EagleSpawnerComponentData' then spawner[#spawner + 1] = r end
        end
        if #eagle > 0 then
            groups[#groups + 1] = { type = 'EagleComponentData', rows = eagle,
                label = { 'Eagle component', '飞鹰组件', '飛鷹組件' } }
        end
        if #spawner > 0 then
            groups[#groups + 1] = { type = 'EagleSpawnerComponentData', rows = spawner,
                label = { 'Eagle spawner component', '飞鹰生成器组件', '飛鷹生成器組件' } }
        end
        MOD.component_groups.wrap(entry, groups, { 'Eagle components', '飞鹰组件', '飛鷹組件' })
    end
end
function MOD.attach_eagle_components()
    for _, weapon in ipairs(weapons) do
        local s = weapon.stratagem
        if s and s.family == 'eagle' then
            local kept, hidden = {}, {}
            for _, r in ipairs(weapon.hidden_rows or {}) do hidden[#hidden + 1] = r end
            weapon.field_keys = weapon.field_keys or {}
            for _, r in ipairs(weapon.rows) do
                if r.section and r.section:match('^StratagemType') then
                    kept[#kept + 1] = r
                    for _, p in ipairs(r.parts) do
                        if p.field and p.field.key then weapon.field_keys[p.field.key] = true end
                    end
                else
                    hidden[#hidden + 1] = r
                    for _, p in ipairs(r.parts) do
                        local users = p.field and p.field.users
                        if users then
                            for i = #users, 1, -1 do
                                if users[i] == weapon then table.remove(users, i) end
                            end
                        end
                    end
                end
            end
            local function attach_page(comp_page, prefix, keep_existing_id)
                if not comp_page then return end
                if comp_page.ensure_rows then comp_page.ensure_rows() end
                for _, row in ipairs(comp_page.rows) do
                    kept[#kept + 1] = row
                    for _, p in ipairs(row.parts) do
                        weapon.field_keys[p.field.key] = true
                        p.health_owner = { weapon = weapon, part = { id = p.id, field = p.field } }
                        local seen = false
                        for _, u in ipairs(p.field.users) do
                            if u == weapon then seen = true; break end
                        end
                        if not seen then p.field.users[#p.field.users + 1] = weapon end
                        if not keep_existing_id or not weapon.by_id[p.id] then weapon.by_id[p.id] = p end
                        weapon.by_id[prefix .. '_' .. p.id] = p
                    end
                end
            end
            local seen_pages = {}
            local spawner_by_eagle = require('eagle_spawner_components').BY_EAGLE_ENTITY or {}
            for _, key in ipairs(s.payloads or {}) do
                local hex = string.format('%08X%08X', u32(key, 4), u32(key, 0))
                local comp_page = MOD.eagle_components and MOD.eagle_components.by_entity and MOD.eagle_components.by_entity[hex]
                if comp_page and not seen_pages[comp_page] then
                    seen_pages[comp_page] = true
                    attach_page(comp_page, 'eagle', false)
                end
                local spawner_hex = spawner_by_eagle[hex]
                local spawner_page = spawner_hex and MOD.eagle_spawner_components and MOD.eagle_spawner_components.by_entity and MOD.eagle_spawner_components.by_entity[spawner_hex]
                if spawner_page and not seen_pages[spawner_page] then
                    seen_pages[spawner_page] = true
                    attach_page(spawner_page, 'eagle_spawner', true)
                end
            end
            local strat_id = s.def and peek4(s.def.at)
            if strat_id and strat_id > 0 and MOD.eagle_spawner_components then
                for _, spawner_page in ipairs(MOD.eagle_spawner_components.pages or {}) do
                    local ep = spawner_page.by_id and spawner_page.by_id.eagle_type
                    if ep and read_field(ep.field) == strat_id and not seen_pages[spawner_page] then
                        seen_pages[spawner_page] = true
                        attach_page(spawner_page, 'eagle_spawner', true)
                    end
                end
            end
            weapon.rows = kept
            weapon.hidden_rows = hidden
            MOD.component_groups.stratagem_page(weapon)
        end
    end
end
-- Both lists are component data-array indices, not StratagemTypeID or EntityHash.
-- Full ECS component aggregation for Armory > Stratagem editing.
function MOD.attach_stratagem_components()
    local views={}
    for _,spec in ipairs(MOD.weapon_components.SPECS)do views[spec.HASH]=MOD.weapon_component_views[spec.KEY]end
    for _,entry in ipairs({{TYPES.health,MOD.health_components},{TYPES.drown,MOD.drown_components},
        {TYPES.shield,MOD.shield_components},{TYPES.throwable,MOD.throwable_components},
        {TYPES.thrower,MOD.thrower_components},{TYPES.minefield,MOD.minefield_components},
        {TYPES.mine_spawner,MOD.mine_spawner_components},{TYPES.faction,MOD.faction_components},
        {TYPES.mount,MOD.mount_components},{TYPES.inventory,MOD.inventory_components},
        {TYPES.sensor,MOD.sensor_eye_components},{TYPES.turret,MOD.turret_components}})do if entry[1]then views[entry[1]]=entry[2]end end
    local specs={}
    for _,spec in ipairs(MOD.weapon_components.SPECS)do specs[#specs+1]=spec end
    for _,name in ipairs({'throwable_components','thrower_components','minefield_components','mine_spawner_components',
        'faction_components','mount_components','inventory_components','sensor_eye_components','turret_components'})do
        local spec=require(name);specs[#specs+1]=spec
    end
    specs[#specs+1]=require('health_schema')
    MOD.stratagem_entity_model=require('stratagem_entity_editor').attach({
        tables=tables,weapons=weapons,by_hash=by_hash,specs=specs,views=views,
        entities=MOD.component_catalog.records,tr=settings.tr,open_entity=function(page)return MOD.open_stratagem_entity(page)end,
        overrides=function()return overrides end,parts=MOD.parts_of,change_version=function()return state.writes end,
        schemas=(rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE')or{}).schemas,
        names=rawget(_G,'SHODAN_COMPONENT_NAMES'),field_at=field_at,read=read_field,default_of=default_of,
        add_row=add_row,lang=function()return settings.lang end,wrap=MOD.component_groups.wrap,tab_of=MOD.nav.tab_of,log=log,
        archive_rows=MOD.physics.owned_rows,
        bytes=function(kind,offset,n)local t=tables[kind];return t and api.read(t.copies[1]+HEADER_BYTES+offset,n)end,
        array_bytes=function(kind,offset,stride)
            local t=tables[kind];local base=t.copies[1]+HEADER_BYTES
            local desc=api.read(base+offset,16);if not desc then return end
            local at=u32(desc,0)+u32(desc,4)*4294967296;local count=u32(desc,8)
            if at>=base and at<base+t.payload then at=at-base end
            if count<=100000 and at>=0 and at+count*stride<=t.payload then return api.read(base+at,count*stride),count end
        end,
        reference=function(row,ref,f,value)
            row.reference_type=ref;row.choice='reference'
            local target=tables[MOD.references.KINDS[ref]]
            if target then f.allowed=f.allowed or setmetatable({[0]=true,[value]=true,why='No matching record in this game build.'},
                {__index=function(_,id)return target.index[id]~=nil end})end
        end})
end
function MOD.build_component_records()
    for i=#weapons,1,-1 do
        if weapons[i].component_index~=nil then by_hash[weapons[i].hash]=nil;table.remove(weapons,i)end
    end
    MOD.component_records=require('component_records').new({weapons=weapons,by_hash=by_hash,
        wrap=MOD.component_groups.wrap,read=read_field})
    local function build(tab,kind,typ,prefix)
        local t=tables[kind];if not t or not t.records_layout then return end
        MOD.component_records:build({tab=tab,kind=kind,type=typ,prefix=prefix,table=t,
            make_rows=function(page,offset,key)
                if kind==TYPES.bombard then
                    MOD.orbital.bomb_rows(page,offset)
                    for _,row in ipairs(page.rows)do
                        row.section='BombardmentType:barrage';row.section_level='group'
                        row.section_of=function()return MOD.nav.text({'Barrage parameters','轰炸参数','轟炸參數'})end
                    end
                else
                    local spec=require('eagle_components')
                    require('component_view').build(spec,{table={index={[key or string.rep('\0',8)]=offset}},
                        kind=kind,weapons=weapons,by_hash=by_hash,page_for=function()return page end,
                        field_at=field_at,read=read_field,add_row=add_row,default_of=default_of,
                        schemas=(rawget(_G,'SHODAN_COMPONENT_CATALOG_SOURCE')or{}).schemas,
                        names=rawget(_G,'SHODAN_COMPONENT_NAMES'),lang=function()return settings.lang end,
                        reference=function(row,ref,f,value)
                            row.reference_type=ref;row.choice='reference'
                            local target=tables[MOD.references.KINDS[ref]]
                            if target then f.allowed=f.allowed or setmetatable({[0]=true,[value]=true,
                                why='No matching record in this game build.'},
                                {__index=function(_,id)return target.index[id]~=nil end})end
                        end})
                end
            end,
            label=typ=='bombardment'and{'Bombardment component','轰炸组件','轟炸組件'}or{'Eagle component','飞鹰组件','飛鷹組件'},
            component=typ=='bombardment'and'BombardmentType'or'EagleComponentData',
            sub=tab=='Orbital'and{'Orbital components','轨道组件','軌道組件'}or{'Eagle components','飞鹰组件','飛鷹組件'}})
    end
    build('Orbital',TYPES.bombard,'bombardment','F8')
    build('Eagle',TYPES.eagle,'eagle','F9')
end
function MOD.component_kind(tab)
    tab=tab or ui.tab
    return tab=='HealthComponents'and'health'or tab=='DemolitionComponents'and'demolition'or tab=='DrownComponents'and'drown'
        or tab=='ShieldComponents'and'shield'or tab=='ThrowableComponents'and'throwable'or tab=='ThrowerComponents'and'thrower'
        or tab=='MinefieldComponents'and'minefield'or tab=='MineSpawnerComponents'and'mine_spawner'
        or tab=='FactionComponents'and'faction'or tab=='MountComponents'and'mount'or tab=='InventoryComponents'and'inventory'
        or tab=='SensorEyeComponents'and'sensor_eye'or tab=='TurretComponents'and'turret'
        or tab=='EagleComponents'and'eagle'or tab=='EagleSpawnerComponents'and'eagle_spawner'
        or MOD.component_tab_kind[tab]or nil
end
function MOD.record_names.seed_tables()
    MOD.record_names.ensure()
    for _,kind in ipairs(MOD.records.KINDS)do
        local names={}
        for _,id in ipairs(MOD.records.ids(kind))do names[id]=MOD.records.name(kind,id)or''end
        MOD.record_names.seed(MOD.record_names.type_of({kind=kind}),names)
    end
    local names={};for _,page in ipairs(MOD.stratagem.all())do names[page.id]=page.name end
    MOD.record_names.seed('stratagem',names)
    for _,list in pairs(MOD.component_records and MOD.component_records.lists or{})do
        local entries={};for _,page in ipairs(list)do entries[page.component_index]=page.name end
        if list[1]then MOD.record_names.seed(list[1].component_type,entries)end
    end
end
function MOD.component_rows()return(MOD.component_kind()or MOD.record_names.is_tab(ui.tab))and 21 or(MOD.weapon_browser_active()or MOD.enemy_browser())and 26 or LIST_ROWS end
local W, H = 1000, 980       -- panel size in its own units

-- The weapons (or stratagems) of a tab; tab '?search': those of every tab whose name holds every
-- word of the search (any case). The Records tab: its records, and searching there searches them.
state.preload_query=function()return ui.search.text end
state.player_save_active=function()return not ui.settings and ui.tab=='CurrentLoadout'and ui.nav.page=='armory'end
local function weapons_in(tab)
    -- '*' (ui.search.edited): only the pages with a change, of what the search (or, with no text, every tab) finds
    if tab == '?search' and ui.search.edited and not ui.search.filtering then
        ui.search.filtering = true
        local ok, found = pcall(weapons_in, tab)
        ui.search.filtering = nil
        if not ok then error(found, 0) end
        local out = {}
        for _, w in ipairs(found) do if MOD.page_changed(w) then out[#out + 1] = w end end
        return out
    end
    local list, words = {}, nil
    if tab == '?search' then
        words = {}
        for word in ui.search.text:lower():gmatch('%S+') do words[#words + 1] = word end
    end
    local named=MOD.identity.list(tab=='?search'and ui.tab or tab,words and ui.search.text or'',settings.tr)
    if named then return named end
    local packages=MOD.preload.list(tab=='?search'and ui.tab or tab,words and ui.search.text or'',settings.tr)
    if packages then return packages end
    local planets=MOD.planet.list(tab=='?search'and ui.tab or tab,words and ui.search.text or'',settings.tr)
    if planets then return planets end
    local saved=MOD.player_save_view.list(tab=='?search'and ui.tab or tab,words and ui.search.text or'')
    if saved then return saved end
    local enum_list=MOD.component_records and MOD.component_records.lists[words and ui.tab or tab]
    if enum_list then
        for _,page in ipairs(enum_list)do
            local text=MOD.record_names.search_text(page):lower();local matches=true
            for _,word in ipairs(words or{})do if not text:find(word,1,true)then matches=false;break end end
            if matches then list[#list+1]=page end
        end
        return list
    end
    local component_kind=MOD.component_kind(tab)or words and MOD.component_kind()
    if component_kind and MOD.component_catalog then
        return MOD.component_catalog:list(component_kind,settings.component_category,settings.component_show_missing,words and ui.search.text or'',settings.tr)
    end
    -- Each TypeID has its own local index namespace, including while searching.
    local function records(t) return t == 'Records' or MOD.nav.BASE[t] == 'Records' end
    if records(tab) or words and records(ui.tab) then
        for _, page in ipairs(MOD.records.all()) do
            local text = MOD.record_names.search_text(page):lower()
            local current=words and ui.tab or tab
            local all = current == 'Records' or MOD.nav.tab_of(page) == current
            for _, word in ipairs(words or {}) do
                if not text:find(word, 1, true) then all = false; break end
            end
            if all then list[#list + 1] = page end
        end
        return list
    end
    local entity_list=MOD.stratagem_entity_model and MOD.stratagem_entity_model.lists[words and ui.tab or tab]
    if entity_list then
        for _,page in ipairs(entity_list)do
            local hay=MOD.record_names.search_text(page):lower();local include=true
            for _,word in ipairs(words or{})do if not hay:find(word,1,true)then include=false;break end end
            if include then list[#list+1]=page end
        end
        return list
    end
    local weapon_all = MOD.WEAPON_SLOTS[tab] and settings.weapon_category == 'all'
    local enemy_all = MOD.ENEMY_SLOTS[tab] and settings.enemy_category == 'all' and not words
    local buckets = enemy_all and { Terminids = {}, Automatons = {}, Illuminate = {} }
    for _, weapon in ipairs(weapons) do
        if buckets and MOD.ENEMY_SLOTS[weapon.slot] and #weapon.rows > 0 and not settings.hidden[weapon.slot] then
            local b = buckets[weapon.slot]; b[#b + 1] = weapon
        elseif #weapon.rows > 0 and not settings.hidden[weapon.slot] and not weapon.nav_hidden then
            if words then
                local name = MOD.record_names.is_page(weapon) and MOD.record_names.search_text(weapon) or weapon.name
                if weapon.stratagem_entity_groups then name=name..' '..(weapon.entity_hash or'')end
                name = name:lower()
                local all = true
                for _, word in ipairs(words) do
                    if not name:find(word, 1, true) then all = false; break end
                end
                if all then list[#list + 1] = weapon end
            elseif weapon_all and MOD.WEAPON_SLOTS[weapon.slot] or MOD.nav.tab_of(weapon) == tab then
                list[#list + 1] = weapon
            end
        end
    end
    for _, slot in ipairs(buckets and { 'Terminids', 'Automatons', 'Illuminate' } or {}) do
        for _, w in ipairs(buckets[slot]) do list[#list + 1] = w end
    end
    return list
end

-- (a value saved for a stat the weapon has no row for, e.g. one an update removed, stays saved, not shown)
local function modified(weapon)
    if MOD.rename.texts[weapon.hash] then return true end   -- a typed name or description (offline)
    if weapon.stratagem_entity_groups and weapon.custom_modified then return weapon.custom_modified()end
    if weapon.ensure_rows then weapon.ensure_rows() end
    if weapon.custom_modified and weapon.custom_modified()then return true end
    if weapon.component_entry then
        for _,r in ipairs(weapon.rows)do for _,p in ipairs(r.parts)do
            if p.field.demolition and p.field.demolition:own(p.field)~=nil then return true end
        end end
    end
    for _, o in ipairs(overrides) do
        if o.hash == weapon.hash and MOD.parts_of(weapon, o.id) then return true end
        if weapon.health_component or weapon.drown_component or weapon.shield_component or weapon.component_view or weapon.field_keys then
            local owner=by_hash[o.hash];local p=owner and owner.by_id[o.id]
            if p and weapon.field_keys[p.field.key] then return true end
        end
    end
    -- an armor passive with passives stacked on it (offline)
    local t = weapon.passive and tables[weapon.passive]
    return t ~= nil and (settings.stacks[t.index.id] ~= nil or settings.own_off[t.index.id] ~= nil)
end

-- A page with a change (search '*'): its own saved values, a faction-wide or the Helldiver's weapon sway row's,
-- a field it shares with a changed page (component views: field_keys, once their rows are made), or its own kind of
-- change (custom_modified: names, preloads, saves). Pages made lazily are not built for this; the overrides are
-- gathered once per change.
function MOD.page_changed(w)
    if w.stratagem_entity_groups then return modified(w)end
    local cache = MOD.page_changed_cache
    if not cache or cache.writes ~= state.writes or cache.n ~= #overrides then
        cache = { writes = state.writes, n = #overrides, hashes = {}, keys = {}, offsets = {} }
        local function changed_offset(f)
            if f and f.kind and f.offset then
                cache.offsets[f.kind]=cache.offsets[f.kind]or{}
                cache.offsets[f.kind][f.offset]=true
            end
        end
        for _, o in ipairs(overrides) do
            cache.hashes[o.hash] = true
            local owner = by_hash[o.hash]
            local p = owner and owner.by_id[o.id]
            if p and p.field then cache.keys[p.field.key] = true;changed_offset(p.field) end
        end
        for key in pairs(MOD.enemy.by_all or{})do changed_offset(fields[key])end
        MOD.page_changed_cache = cache
    end
    if cache.hashes[w.hash] or MOD.rename.texts[w.hash] or (MOD.enemy.by_all_pages and MOD.enemy.by_all_pages[w.hash]) then return true end
    if w.component_kind_hash and w.component_offset then
        for offset in pairs(cache.offsets[w.component_kind_hash]or{})do
            if offset>=w.component_offset and offset<w.component_offset+w.component_size then return true end
        end
    end
    if not w.ensure_rows then
        if modified(w) then return true end
    elseif w.custom_modified and w.custom_modified() then return true end
    for key in pairs(w.field_keys or {}) do if cache.keys[key] or (MOD.enemy.by_all and MOD.enemy.by_all[key]) then return true end end
    for _, r in ipairs(w.ensure_rows and {} or w.rows) do
        for _, p in ipairs(r.parts) do
            if p.field and MOD.enemy.by_all and MOD.enemy.by_all[p.field.key] then return true end
        end
    end
    return false
end

-- Font: the game's UI font (the resource ids HD2 HUD Plus and DiverKit read from game.dll
-- of this build), else the engine's debug font.
local font = nil
local GAME_STAMP, FONT_RVA, ATLAS_RVA, MATERIAL_RVA = 0x6AB3B43F, 0x3772268, 0x3772EE8, 0x37C5478

local function resource_hex(bytes)
    if not bytes or #bytes ~= 8 or bytes == string.rep('\0', 8) then return nil end
    return string.format('%08x%08x', u32(bytes, 4), u32(bytes, 0))
end

-- The ids are read again for every new gui (the game can switch them), and nothing is bound
-- unless the engine says all three resources are loaded: binding a texture that is not there
-- crashes the game (Material.set_texture, seen in-game on 2026-09-28).
local DEBUG_FONT = 'core/performance_hud/debug'

local function read_font_ids()
    if state.font_ids then return state.font_ids end
    local base = ffi.load('kernel32').GetModuleHandleA('game.dll')
    if base == nil then return nil, 'game.dll not found' end
    base = tonumber(ffi.cast('uintptr_t', base))
    local dos = api.read(base, 64)
    local pe = dos and u32(dos, 60)
    local head = pe and api.read(base + pe, 16)
    if not head or head:sub(1, 4) ~= 'PE\0\0' or u32(head, 8) ~= GAME_STAMP then return nil, 'game.dll is another build' end
    local font_id = resource_hex(api.read(base + FONT_RVA, 8))
    local atlas_id = resource_hex(api.read(base + ATLAS_RVA, 8))
    local owner = api.read(base + MATERIAL_RVA, 8)
    local owner_at = owner and (u32(owner, 0) + u32(owner, 4) * 4294967296)
    local material_id = owner_at and owner_at ~= 0 and resource_hex(api.read(owner_at + 24, 8))
    if not (font_id and atlas_id and material_id) then return nil, 'font ids not set yet' end
    state.font_ids = { font = font_id, material = material_id, atlas = atlas_id }
    return state.font_ids
end

-- true / false when the engine answers, nil when it cannot be asked
local function loaded(kind, name)
    local can_get = sr.Application and rawget(sr.Application, 'can_get')
    if type(can_get) ~= 'function' then return nil end
    local ok, value = pcall(function()
        return can_get(kind, name:match('^%x+$') and #name == 16 and sr.IdString64.from_hex(name) or name)
    end)
    if not ok then return nil end
    return value == true
end

-- Picks the font for a new gui and binds it: for a panel language the game UI font has no glyphs
-- for (Chinese while the game runs in English), the game's own font for that language when loaded;
-- else the game UI font when all its parts are loaded, else the engine debug font when loaded,
-- else none (the panel is drawn without text).
local function choose_font(gui)
    local ids, why = read_font_ids()
    local function bind(font_id, atlas, text)
        step('Gui.material')
        local ink = sr.Gui.material(gui, sr.IdString64.from_hex(ids.material))
        if not ink then return nil end
        step('Material.set_texture')
        sr.Material.set_texture(ink, sr.IdString64.from_hex('88bac99b00000000'), sr.IdString64.from_hex(atlas))
        return { font = sr.IdString64.from_hex(font_id), material = sr.IdString64.from_hex(ids.material), text = text }
    end
    local l, lang_why = settings.LANGS[settings.lang], nil
    if ids and l and l.fonts then
        local own = false
        for _, f in ipairs(l.fonts) do own = own or f.font == ids.font end
        if not own and loaded('material', ids.material) then
            local said = {}
            for _, f in ipairs(l.fonts) do
                local ff, t = loaded('font', f.font), loaded('texture', f.atlas)
                local chosen = ff and t and bind(f.font, f.atlas, 'game ' .. l.id .. ' font ' .. f.font .. ' (atlas ' .. f.atlas .. ')')
                if chosen then return chosen end
                said[#said + 1] = string.format('font %s %s, texture %s %s', f.font, tostring(ff), f.atlas, tostring(t))
            end
            lang_why = l.id .. ' fonts not loaded: ' .. table.concat(said, '; ')
        end
    end
    if ids then
        local f, m, t = loaded('font', ids.font), loaded('material', ids.material), loaded('texture', ids.atlas)
        if f and m and t then
            local chosen = bind(ids.font, ids.atlas, 'game UI font ' .. ids.font .. ' (atlas ' .. ids.atlas .. ')'
                                .. (lang_why and '; ' .. lang_why or ''))
            if chosen then return chosen end
            why = 'no font material instance'
        else
            why = string.format('game UI font not loaded (font %s, material %s, texture %s)', tostring(f), tostring(m), tostring(t))
        end
    end
    if loaded('font', DEBUG_FONT) and loaded('material', DEBUG_FONT) then
        return { font = DEBUG_FONT, material = DEBUG_FONT, text = 'debug font (' .. why .. ')' }
    end
    return { text = 'no text: ' .. why .. '; debug font not loaded either' }
end

local function clear_gui()
    if ui.gui and ui.world then
        for _, w in ipairs(sr.Application.worlds() or {}) do
            if w == ui.world then pcall(sr.World.destroy_gui, ui.world, ui.gui) break end
        end
    end
    ui.gui, ui.world, ui.signature, ui.regions = nil, nil, nil, {}
end

local function fmt(v, storage)
    if v == nil then return '?' end
    if storage=='f32'and math.abs(v)==3.4028234663852886e38 then return v<0 and'-FLT_MAX'or'FLT_MAX'end
    if storage=='f32' then return string.format('%.9g',v)end
    if storage == 'gun' then   -- its place in the list of weapons
        local g = MOD.enemy.gun_choices().by_id[v]
        return g and ('#' .. g.n) or '?'
    end
    if storage == 'flag' then return v >= 0.5 and 'On' or 'Off' end
    if storage == 'u32' or storage == 'i32' or storage == 'u16' or storage == 'u8' or storage=='i8' then return tostring(math.floor(v + 0.5)) end
    if math.abs(v - math.floor(v + 0.5)) < 1e-4 then return tostring(math.floor(v + 0.5)) end
    if math.abs(v) < 1 then return (string.format('%.3f', v):gsub('0+$', '')) end
    return (string.format('%.2f', v):gsub('0+$', ''):gsub('%.$', ''))
end

function MOD.stratagem.set_hash(weapon,row,text)
    if not settings.changes then return nil,'Changes are off.'end
    if weapon.preload_parameters then text=MOD.preload.hash_input(text)end
    local lo,hi=MOD.stratagem.schema.parse_u64(text)
    if lo==nil then return nil,hi end
    local values={lo,hi};local before={}
    for i,p in ipairs(row.parts)do before[i]=read_field(p.field);if before[i]==nil then return nil,'Hash field unavailable.'end;default_of(p.field)end
    for i,p in ipairs(row.parts)do
        if before[i]~=values[i]then
            local ok,why=write_field(p.field,values[i])
            if not ok then for j=1,i-1 do write_field(row.parts[j].field,before[j])end;return nil,why end
        end
    end
    for i,p in ipairs(row.parts)do set_override(weapon,p,unless_default(values[i],default_of(p.field)))end
    if row.id and row.id:match('^strat_Payload%d+$') and (lo ~= 0 or hi ~= 0) and MOD.component_catalog then
        local hex_str = string.format('%08X%08X', hi, lo)
        local found = false
        for _, r in ipairs(MOD.component_catalog.records or {}) do
            if r.hash == hex_str then found = true; break end
        end
        if not found then
            MOD.notify(MOD.nav.text({
                'Warning: entity hash 0x' .. hex_str .. ' is not in the game entity catalog (check for typos).',
                '注意：实体哈希 0x' .. hex_str .. ' 不在当前游戏实体表中（可能输入有误），请核对。',
                '注意：實體雜湊 0x' .. hex_str .. ' 不在目前遊戲實體表中（可能輸入有誤），請核對。',
            }), 6)
        end
    end
    ui.version=ui.version+1
    return true
end
function MOD.projectile.set_flag(weapon,row,value)
    local p=row.parts[1];local current=read_field(p.field)
    if current==nil or value==nil then return end
    local mask=row.packed_flag
    local target=current-(math.floor(current/mask)%2)*mask+(value>=.5 and mask or 0)
    if target~=current then
        local ok,why=write_field(p.field,target)
        if not ok then ui.message={text=why,till=api.now()+5};return end
        set_override(weapon,p,unless_default(target,default_of(p.field)))
        ui.version=ui.version+1
    end
end
function MOD.stratagem.set_button(weapon,row,value)
    if not settings.changes then return nil,'Changes are off.'end
    value=math.floor(value+.5)
    if value<0 or value>4 then return nil,'Button must be 0, 1, 2, 3 or 4.'end
    local arrows=MOD.code.arrows(read_field(row.parts[1].field))or{}
    local slot=row.button_slot
    if slot>#arrows+1 and value~=0 then return nil,'Fill the preceding button slots first.'end
    if value==0 then for i=#arrows,slot,-1 do arrows[i]=nil end
    else arrows[slot]=value end
    if #arrows==0 then return nil,'A call-in code needs at least one arrow.'end
    local ok,why=MOD.code.check(row.def,arrows)
    if not ok then return nil,why end
    local p=row.parts[1];local v=MOD.code.number(arrows)
    if v==read_field(p.field)then return true end
    local done,err=write_field(p.field,v)
    if not done then return nil,err end
    set_override(weapon,p,unless_default(v,default_of(p.field)))
    ui.version=ui.version+1
    if why then ui.message={text=why,till=api.now()+6}end
    return true
end

local function step_of(row, value, big)
    local step = big and row.big or row.small
    if row.storage == 'f32' and value and value > 0 and value < row.small then
        step = 10 ^ math.floor(math.log10(value) + 1e-9)
        if big then step = step * 10 end
    end
    return step
end

local function select_weapon(weapon)
    if weapon and weapon.ensure_rows then weapon.ensure_rows() end
    if weapon and weapon.sync_rows then weapon.sync_rows() end
    ui.reference_click = nil
    ui.weapon = weapon
    ui.row, ui.scroll, ui.settings, ui.binding, ui.stack_pick, ui.code, ui.context_menu = 1, 1, false, nil, nil, nil, nil
    local last = settings.last[MOD.enemy.on and 'enemy' or 'stat']
    if weapon and state.phase == 'ready' and (last.weapon ~= weapon.hash or last.tab ~= MOD.nav.tab_of(weapon)) then
        last.tab, last.weapon = MOD.nav.tab_of(weapon), weapon.hash
        mark_config_dirty()
    end
    if weapon then
        if weapon.component_entry then ui.component_selected=weapon.entity_id end
        if MOD.WEAPON_SLOTS[weapon.slot] and settings.weapon_category ~= 'all' and settings.weapon_category ~= weapon.slot then
            settings.weapon_category = weapon.slot
        end
        if MOD.ENEMY_SLOTS[weapon.slot] and settings.enemy_category ~= 'all' and settings.enemy_category ~= weapon.slot then
            settings.enemy_category = weapon.slot
        end
        ui.tab = MOD.nav.tab_of(weapon)
        ui.nav.weapon[ui.tab] = weapon.hash
        local list = weapons_in((ui.search.text ~= '' or ui.search.edited) and '?search' or ui.tab)
        local rows = ui.list_rows or MOD.component_rows()
        for n, w in ipairs(list) do
            if w == weapon and n < ui.page then ui.page = n
            elseif w == weapon and n >= ui.page + rows then ui.page = n - rows + 1 end
        end
    end
end

function MOD.open_stratagem_entity(page)
    ui.search={text='',active=false};ui.page=1
    select_weapon(page);MOD.nav.sync();ui.version=ui.version+1;return true
end

-- Direct jump by enum/record row id (or a component EntityHash, hex or decimal): 轨道飞鹰 / 游戏数据 lists.
function MOD.record_names.jump(tab, text)
    local kind=MOD.component_kind(tab)
    if kind and MOD.component_catalog then
        for _,hash in ipairs(MOD.name_ids.hashes(text))do
            for _,page in ipairs(MOD.component_catalog.views[kind])do
                if page.entity_hash==hash then return page end
            end
        end
        return nil
    end
    local list=weapons_in(tab)
    local index=MOD.name_ids.index(text)
    local hash_only=tab=='OrbitalBeam'
    if index and not hash_only then
        for _,page in ipairs(list)do
            local id=MOD.record_names.id_of(page)
            if type(id)=='number'and tostring(id)==index then return page end
        end
    end
    -- An index list must never jump by any of its backing EntityHashes or related component IDs.
    if tab=='Orbital'or tab=='Eagle'or tab:match('^Rec')then return nil end
    for _,hash in ipairs(MOD.name_ids.hashes(text))do
        for _,page in ipairs(list)do
            if page.entity_hash==hash or page.orbital_beam and page.hash==hash
               or MOD.record_names.payload_component(page)==hash then return page end
        end
    end
end
function MOD.record_names.jump_active()
    local page=MOD.record_names.jump(ui.tab,ui.record_id.text)
    if not page then return false end
    if page.component_entry then
        if settings.component_category~='all'and settings.component_category~=page.category then settings.component_category='all'end
        if not page.has_component then settings.component_show_missing=true end
    end
    ui.search={text='',active=false};ui.page=1
    select_weapon(page);ui.message=nil;ui.version=ui.version+1
    return true
end

function MOD.references.open(row)
    local ref, id = MOD.references.type_of(row), row_value(row)
    local function unavailable(reason)
        ui.message = { text = reason, till = api.now() + 4 }
        ui.version = ui.version + 1
        return false
    end
    if not ref then return false end
    if not id or id <= 0 then
        return unavailable(MOD.nav.text({ 'No referenced record: ID is 0 or unavailable.',
            '此引用为 0 或不可读取，没有可跳转的记录。', '此引用為 0 或不可讀取，沒有可跳轉的記錄。' }))
    end
    local target
    if ref == 'stratagem_id' then
        target=MOD.stratagem.page(id)
        for _, w in ipairs(not target and weapons or{}) do
            local def = w.stratagem and w.stratagem.def
            if def and peek4(def.at) == id then target = w; break end
        end
    else
        local kind = MOD.references.KINDS[ref]
        if kind then target = MOD.records.page(kind, id) end
    end
    if not target then
        return unavailable(MOD.nav.text({ 'Referenced record is not loaded: ', '未加载对应记录：', '未載入對應記錄：' }) .. ref .. ' ' .. id)
    end
    MOD.enemy.on, settings.enemy_last = false, false
    ui.search, ui.page, ui.value = { text = '', active = false }, 1, nil
    select_weapon(target)
    MOD.nav.sync()
    ui.message = nil
    ui.version = ui.version + 1
    return true
end
-- Pair clicks by source page AND row, within the OS double-click interval and a small movement.
-- The first click keeps the editor's normal single-click behavior.
function MOD.references.double_click(weapon, n, now, x, y)
    local last = ui.reference_click
    local seconds = .5
    if user then
        local ok, ms = pcall(function() return user.GetDoubleClickTime() end)
        if ok then seconds = ms / 1000 end
    end
    if last and last.weapon == weapon and last.n == n and now >= last.time and now - last.time <= seconds
       and (not x or not last.x or math.abs(x - last.x) <= 5)
       and (not y or not last.y or math.abs(y - last.y) <= 5) then
        ui.reference_click = nil
        return true
    end
    ui.reference_click = { weapon = weapon, n = n, time = now, x = x, y = y }
    return false
end

-- Suppressed on / off: the flag, and the noise template the game's suppressed guns use (10; a silent one, 0, stays 0);
-- off on a gun the game suppresses: a loud template (7). Off on any other: its own again.
function MOD.component_reselect()
    if MOD.component_catalog and settings.component_category~='all'and not MOD.component_catalog.config.by_id[settings.component_category]then settings.component_category='all'end
    local list=weapons_in((ui.search.text~=''or ui.search.edited)and'?search'or ui.tab)
    local wanted=ui.component_selected;local found
    for _,page in ipairs(list)do if page.entity_id==wanted then found=page;break end end
    select_weapon(found or list[1]);ui.version=ui.version+1
end

function MOD.suppress(weapon, row, target)
    local flag, noise = row.parts[1], row.parts[2]
    local f0, n0 = default_of(flag.field), default_of(noise.field)
    if f0 == nil or n0 == nil then return end
    local n = target == 1 and (n0 == 0 and 0 or 10) or (f0 == 1 and 7 or n0)
    if write_field(noise.field, n) and write_field(flag.field, target) then
        set_override(weapon, flag, unless_default(target, f0))
        set_override(weapon, noise, unless_default(n, n0))
    end
    ui.version = ui.version + 1
end

local function change(row, delta_sign, big, exact)
    MOD.numeric.row(row)
    if row.custom_change then
        if not settings.changes then return end
        local ok,why=row.custom_change(exact or math.max(row.min,math.min(row.max,row_value(row)+delta_sign)))
        if not ok then ui.message={text=tostring(why),till=api.now()+6}end
        ui.version=ui.version+1;return
    end
    if row.collapsed_component or row.link_only then return end
    if row.hash64 then return end   -- exact decimal input; never increment a rounded double
    if row.button_slot then
        local target=exact or row_value(row)+delta_sign
        local ok,why=MOD.stratagem.set_button(ui.weapon,row,math.max(0,math.min(4,target)))
        if not ok then ui.message={text=why,till=api.now()+5}end
        return
    end
    local weapon = ui.weapon
    local current = row_value(row)
    if not weapon or current == nil then return end
    if row.code then return end   -- (recorded with the arrows: MOD.code.start)
    if not settings.changes then
        ui.message = { text = 'Your changes are off: turn them on in Settings to edit.', till = api.now() + 4 }
        return
    end
    if row.suppression then   -- the flag and the noise template together (MOD.suppress)
        local target = math.max(0, math.min(1, math.floor((exact or current + delta_sign) + 0.5)))
        if target ~= current then MOD.suppress(weapon, row, target) end
        return
    end
    if row.packed_flag then
        MOD.projectile.set_flag(weapon,row,exact or math.max(0,math.min(1,current+delta_sign)))
        return
    end
    if row.choice then
        if row.choice=='reference'then
            local kind=MOD.references.KINDS[row.reference_type]
            local target=exact and math.floor(exact+.5)or MOD.records.step(kind,current,delta_sign*(big and 10 or 1))
            if exact==nil and target~=0 and not(tables[kind]and tables[kind].index[target])then
                ui.message={text='No matching record in this game build: '..tostring(target),till=api.now()+5};return
            end
            if target==current then return end
            local p=row.parts[1];local ok,why=write_field(p.field,target)
            if ok then set_override(weapon,p,unless_default(target,default_of(p.field)))
            else ui.message={text=why,till=api.now()+5}end
            ui.version=ui.version+1
            return
        end
        if row.choice == 'grenade' then
            local spec = KINDS[TYPES.throwable]
            local target = exact and math.floor(exact + 0.5) or spec.step(current, delta_sign * (big and 10 or 1))
            if not spec.entity_bytes(target) then
                ui.message = { text = 'No grenade choice ' .. tostring(target) .. ' in this game build.', till = api.now() + 4 }
                return
            end
            local p = row.parts[1]
            if target ~= 0 and not exact then
                -- stepping through the list: applied once the choice settles, so only the grenade
                -- you stop on has its assets loaded (they stay loaded for the session)
                local ok, why = spec.ensure_launch()
                if ok then set_override(weapon, p, unless_default(target, default_of(p.field)))
                else ui.message = { text = why, till = api.now() + 4 } end
                ui.version = ui.version + 1
                return
            end
            local ok, why = write_field(p.field, target)
            if ok or why == 'grenade assets loading' then
                set_override(weapon, p, unless_default(target, default_of(p.field)))
            end
            if not ok then ui.message = { text = why, till = api.now() + 4 } end
            ui.version = ui.version + 1
            return
        end
        if row.choice == 'gun' then   -- an enemy's weapon: the next / previous in the list (typed: its number there)
            local c = MOD.enemy.gun_choices()
            local g = c.by_id[current]
            local at = exact and math.floor(exact + 0.5) or ((g and g.n or 0) + delta_sign * (big and 10 or 1))
            local pick = c.list[math.max(1, math.min(#c.list, at))]
            if not pick or pick.id == current then return end
            local p = row.parts[1]
            local ok, err = true, nil
            for _, q in ipairs(row.parts) do
                local done, why = write_field(q.field, pick.id)
                if done then set_override(weapon, q, unless_default(pick.id, default_of(q.field)))
                else ok, err = false, why end
            end
            if not ok then ui.message = { text = err, till = api.now() + 4 } end
            ui.version = ui.version + 1
            return
        end
        if row.choice == 'weight' then
            -- 0 light, 1 medium, 2 heavy, on every piece of the armor (back to the default: each piece's own)
            local target = exact and math.floor(exact+.5)or math.max(0,math.min(2,current+delta_sign))
            if target == nil or target == current then return end
            local back = target == default_of(row.parts[1].field)
            for _, p in ipairs(row.parts) do
                local d = default_of(p.field)
                local new = back and d or target
                local ok, why = write_field(p.field, new)
                if ok then set_override(weapon, p, unless_default(new, d))
                else log('write refused: ' .. weapon.name .. ' ' .. p.id .. ': ' .. why) end
            end
            ui.version = ui.version + 1
            return
        end
        if row.choice == 'faction' then   -- the next / previous side (typed: its number, 1 2 4 8), every part
            local order, at = MOD.faction.ORDER, 1
            for k, v in ipairs(order) do if v == current then at = k end end
            local target = exact and math.floor(exact + 0.5) or order[math.max(1, math.min(#order, at + delta_sign))]
            if target == current then return end
            for _, p in ipairs(row.parts) do
                local ok, err = write_field(p.field, target)
                if ok then set_override(weapon, p, unless_default(target, default_of(p.field)))
                else ui.message = { text = err, till = api.now() + 4 } end
            end
            ui.version = ui.version + 1
            return
        end
        if row.choice == 'slot' then   -- primary (1) or secondary (3)
            local target = exact and math.floor(exact + 0.5) or (current == 1 and 3 or 1)
            if target == current then return end
            local p = row.parts[1]
            local ok, err = write_field(p.field, target)
            if ok then set_override(weapon, p, unless_default(target, default_of(p.field)))
            else ui.message = { text = err, till = api.now() + 4 } end
            ui.version = ui.version + 1
            return
        end
        if row.choice == 'holster' then   -- 0 back (the weapon's own node and offsets), 1 hip (the pistols')
            local target = exact and math.floor(exact + 0.5) or 1 - current
            if not MOD.holster.NAMES[target] then
                ui.message = { text = 'Holster: 0 back or 1 hip.', till = api.now() + 4 }
                return
            end
            if target == current then return end
            for k, p in ipairs(row.parts) do
                local d = default_of(p.field)
                local new = target == 0 and d or (k == 1 and MOD.holster.HIP or 0)
                local ok, why = write_field(p.field, new)
                if ok then set_override(weapon, p, unless_default(new, d))
                else log('write refused: ' .. weapon.name .. ' ' .. p.id .. ': ' .. why) end
            end
            ui.version = ui.version + 1
            return
        end
        if row.choice == 'pod_twin' then   -- 1 the game's, 2 a copy of the left slot on the right, both dropped
            local target = math.max(1, math.min(2, exact and math.floor(exact + 0.5) or 3 - current))
            if target == current then return end
            local rt = tables[TYPES.rack]
            local left = api.read(rt.copies[1] + HEADER_BYTES + row.rack, 64)
            if not left or #left ~= 64 then return end
            for k, p in ipairs(row.parts) do
                local d = default_of(p.field)
                local new = d
                if target == 2 then
                    new = k == 17 and math.max(2, d or 0) or k == 3 and MOD.pod.RIGHT or k == 14 and 1 or u32(left, (k - 1) * 4)
                end
                local ok, why = write_field(p.field, new)
                if ok then set_override(weapon, p, unless_default(new, d))
                else log('write refused: ' .. weapon.name .. ' ' .. p.id .. ': ' .. why) end
            end
            ui.version = ui.version + 1
            return
        end
        if row.choice == 'stratagem' then
            local target = exact and math.floor(exact + 0.5) or MOD.extra.step(row.def, current, delta_sign * (big and 10 or 1))
            if target == nil or target == current then return end
            local why = exact==nil and MOD.extra.refused(row.def, target)
            if why then ui.message = { text = why, till = api.now() + 4 }; return end
            local p = row.parts[1]
            local ok, err = write_field(p.field, target)
            if ok then set_override(weapon, p, unless_default(target, default_of(p.field)))
            else ui.message = { text = err, till = api.now() + 4 } end
            ui.version = ui.version + 1
            return
        end
        if row.choice == 'status' then
            local target = exact and math.floor(exact + 0.5) or (row.status_all and MOD.records.step(T_STATUS,current,delta_sign*(big and 10 or 1))or MOD.status.step(current, delta_sign * (big and 10 or 1)))
            if target == current then return end
            local why = exact==nil and MOD.status.refused(row, target)
            if why then ui.message = { text = why, till = api.now() + 4 }; return end
            local p = row.parts[1]
            local ok, err = write_field(p.field, target)
            if ok then
                set_override(weapon, p, unless_default(target, default_of(p.field)))
                -- a status with no strength does nothing: it gets the usual one
                local sp = row.strength and row.strength.parts[1]
                if target ~= 0 and sp and (read_field(sp.field) or 0) == 0 and (MOD.status.by[target]or row.status_all) then
                    local strength=MOD.status.by[target]and MOD.status.by[target].strength or 1
                    if write_field(sp.field, strength) then
                        set_override(weapon, sp, unless_default(strength, default_of(sp.field)))
                    end
                end
            else ui.message = { text = err, till = api.now() + 4 } end
            ui.version = ui.version + 1
            return
        end
        if row.choice == 'explosion' or row.choice == 'shrapnel' then
            -- an explosion id, or the projectile shrapnel pieces are: none (0) or any record of this build
            local kind = row.choice == 'explosion' and T_EXPLOSION or T_PROJECTILE
            local target = exact and math.floor(exact + 0.5) or MOD.records.step(kind, current, delta_sign * (big and 10 or 1))
            if exact==nil and target ~= 0 and not (tables[kind] and tables[kind].index[target]) then
                ui.message = { text = (kind == T_EXPLOSION and 'No explosion ' or 'No projectile ') .. tostring(target) .. ' in the game.',
                               till = api.now() + 4 }
                return
            end
            if target == current then return end
            for _, p in ipairs(row.parts) do
                local d = default_of(p.field)
                local ok, why = write_field(p.field, target)
                if ok then set_override(weapon, p, unless_default(target, d))
                else log('write refused: ' .. weapon.name .. ' ' .. p.id .. ': ' .. why) end
            end
            ui.version = ui.version + 1
            return
        end
        -- a projectile swap: the next / previous weapon's projectile (++ / --: 10 on), or a typed id
        local target = exact and math.floor(exact + 0.5) or KINDS[T_PROJECTILE].step(current, delta_sign * (big and 10 or 1))
        if exact==nil and not (tables[T_PROJECTILE] and tables[T_PROJECTILE].index[target]) then
            ui.message = { text = 'No projectile ' .. tostring(target) .. ' in the game.', till = api.now() + 4 }
            return
        end
        if target == current then return end
        for _, p in ipairs(row.parts) do
            local d = default_of(p.field)
            local ok, why = write_field(p.field, target)
            if ok then set_override(weapon, p, unless_default(target, d))
            else log('write refused: ' .. weapon.name .. ' ' .. p.id .. ': ' .. why) end
        end
        ui.version = ui.version + 1
        return
    end
    local target = exact or current + delta_sign * step_of(row, current, big)
    if row.storage == 'u32' or row.storage=='i32' or row.storage=='u16' or row.storage=='u8' or row.storage=='i8' then target = math.floor(target + 0.5)
    end
    if row.limit and delta_sign > 0 and current >= row.max then
        ui.message = { text = row.limit, till = api.now() + 4 }
    end
    target = math.max(row.min, math.min(row.max, target))
    if target == current then return end
    if row.span and not ((row.span() or 0) > 0) then   -- a time of nothing (the Hover Pack at recharge 0)
        ui.message = { text = 'The recharge time is 0: set it above 0 first.', till = api.now() + 4 }
        return
    end
    local keep = MOD.times_of(row)
    for _, p in ipairs(row.parts) do
        local v = read_field(p.field)
        default_of(p.field)
        local new = target
        if row.mult then
            local d = defaults[p.field.key]
            if p == row.parts[1] then new = target
            elseif d == nil then new = nil
            else new = row.inverse and d / target or d * target end
        elseif row.span then new = row.span() / target - (row.rate_plus or 0)
        elseif #row.parts > 1 then new = (current > 0) and v * target / current or target / (row.scale or 1)
        elseif row.zero and math.abs(target - row.zero) < 1e-4 and defaults[p.field.key] == 0 then new = 0
        elseif row.scale then new = target / row.scale end
        local ok, why = false, 'its game value unread'
        if new ~= nil then ok, why = write_field(p.field, new) end
        local d = defaults[p.field.key]
        if ok then
            set_override(weapon, p, MOD.enemy.keep_own(weapon, p, new, d))
        else
            log('write refused: ' .. weapon.name .. ' ' .. p.id .. ': ' .. why)
        end
    end
    MOD.keep_times(weapon, keep)
    ui.version = ui.version + 1
end

-- Ends typing a value: keep = true sets it (out of the stat's range: the nearest end, and says so).
local function finish_value(keep)
    local edit = ui.value
    ui.value = nil
    if edit and edit.setting == 'render_height' then
        if keep then
            local wrong = settings.set_render(edit.text)
            local r = settings.RANGE.render_height
            if wrong then ui.message = { text = string.format('Resolution: %d to %d pixels high; set to %d.', r[1], r[2], settings.render_height), till = api.now() + 4 } end
            settings.apply_display()
            mark_config_dirty()
        end
        ui.version = ui.version + 1
        return
    end
    if edit and edit.setting then
        local typed = keep and tonumber((edit.text:gsub(',', '.')))
        if not typed then return end
        local r = settings.RANGE[edit.setting]
        if settings.set_percent(edit.setting, typed) then
            local label = settings.DISPLAY[edit.setting] and MOD.nav.text(settings.DISPLAY[edit.setting])
                          or edit.setting == 'size' and 'Panel size' or 'Background opacity'
            ui.message = { text = edit.setting == 'font_px' and string.format('%s can be %d to %d px: set to %d px.', label, r[1], r[2], settings.font_px)
                                  or string.format('%s can be %d%% to %d%%: set to %d%%.', label, r[1], r[2], settings[edit.setting]), till = api.now() + 4 }
        end
        if settings.DISPLAY[edit.setting] then settings.apply_display() end
        mark_config_dirty()
        ui.version = ui.version + 1
        return
    end
    local row = edit and keep and edit.weapon == ui.weapon and ui.weapon.rows[edit.n]
    if row and row.custom_edit then
        if not settings.changes then ui.value=edit;return end
        local ok,why=row.custom_edit(edit.text)
        if not ok then ui.value=edit;ui.message={text=tostring(why),till=api.now()+7}end
        ui.version=ui.version+1;return
    end
    if row and row.hash64 then
        local ok,why=MOD.stratagem.set_hash(edit.weapon,row,edit.text)
        if not ok then ui.value=edit;ui.message={text=why,till=api.now()+5}end
        return
    end
    if row then MOD.numeric.row(row)end
    local typed = row and tonumber((edit.text:gsub(',', '.')))
    if not typed or not MOD.parse_number(typed)then
        if row then ui.value=edit;ui.message={text='Enter a finite number.',till=api.now()+5}end
        return
    end
    local rounded = row.storage == 'u32' and math.floor(typed + 0.5) or typed
    local target = math.max(row.min, math.min(row.max, rounded))
    change(row, 0, false, target)
    if target ~= rounded then
        local text = string.format('%s can be %s to %s: set to %s.', row.label, fmt(row.min, row.storage),
                                   fmt(row.max, row.storage), fmt(target, row.storage))
        if row.limit and rounded > row.max then text = row.limit .. ' Set to ' .. fmt(target, row.storage) .. '.' end
        ui.message = { text = text, till = api.now() + 4 }
    end
end

-- A call-in code row: recording starts (the arrow keys or WASD add arrows), or ends with keep = true / false.
if MOD.offline then
    state.commit_value = function()
        if not ui.value then return true end
        local edit = ui.value
        local exact_row=edit.weapon and edit.weapon.rows[edit.n]
        if exact_row and(exact_row.hash64 or exact_row.custom_edit)then
            finish_value(true)
            return not ui.value or nil,ui.value and(ui.message and ui.message.text or'Enter a valid field value.')or nil
        end
        if edit.setting == 'render_height' then
            finish_value(true)
            return true
        end
        local value = tonumber((edit.text:gsub(',', '.')))
        if not value or not MOD.parse_number(value) then return nil, 'Enter a finite number before switching pages or installing.' end
        local row = edit.weapon and edit.weapon.rows[edit.n]
        finish_value(true)
        if row and row.parts[1] and row.parts[1].field.demolition then
            local expected = math.max(row.min, math.min(row.max, math.floor(value + .5)))
            if row_value(row) ~= expected then return nil, 'Could not save the current demolition value.' end
        end
        return true
    end
end

function MOD.code.start(n)
    local weapon = ui.weapon
    if not settings.changes then
        ui.message = { text = 'Your changes are off: turn them on in Settings to edit.', till = api.now() + 4 }
        return
    end
    ui.value, ui.code = nil, { n = n, weapon = weapon, arrows = {} }
end
function MOD.code.finish(keep)
    local rec = ui.code
    ui.code = nil
    ui.version = ui.version + 1
    local weapon = rec and keep and rec.weapon
    local row = weapon and weapon == ui.weapon and weapon.rows[rec.n]
    if not (row and row.code) or #rec.arrows == 0 then return end
    local p = row.parts[1]
    local ok, warning = MOD.code.check(p.field.def, rec.arrows)
    if not ok then ui.message = { text = warning, till = api.now() + 6 }; return end
    local value = MOD.code.number(rec.arrows)
    local done, why = write_field(p.field, value)
    if not done then ui.message = { text = why, till = api.now() + 4 }; return end
    set_override(weapon, p, unless_default(value, default_of(p.field)))
    if warning then ui.message = { text = 'Set. ' .. warning, till = api.now() + 8 } end
end

local function reset_row(weapon, row)
    if row.custom_reset then local ok,why=row.custom_reset();if not ok then ui.message={text=tostring(why),till=api.now()+6}end;ui.version=ui.version+1;return end
    if row.packed_flag then MOD.projectile.set_flag(weapon,row,row_value(row,true));return end
    local keep = MOD.times_of(row)
    for _, p in ipairs(row.parts) do
        if p.field.demolition then
            local ok, why = p.field.demolition:write(p.field, nil)
            if not ok then ui.message = {text=tostring(why),till=api.now()+5}; return end
        else
            local d = default_of(p.field)
            if d ~= nil then write_field(p.field, d) end
            set_override(weapon, p, nil)
        end
    end
    MOD.keep_times(weapon, keep)
    ui.version = ui.version + 1
end

local function reset_weapon(weapon)
    if MOD.rename.texts[weapon.hash] then MOD.rename.set(weapon, 'name', nil); MOD.rename.set(weapon, 'desc', nil) end
    if weapon.custom_reset then local ok,why=weapon.custom_reset();if not ok then ui.message={text=tostring(why),till=api.now()+6};return end end
    if weapon.component_groups then
        for _, g in ipairs(weapon.component_groups) do
            if g.load then g.load()end
            for _, row in ipairs(g.rows) do
                if not(weapon.custom_reset and row.custom_value)then reset_row(weapon, row)end
            end
        end
    else
        for _, row in ipairs(weapon.rows) do if not(weapon.custom_reset and row.custom_value)then reset_row(weapon, row)end end
    end
    for _, row in ipairs(weapon.hidden_rows or {}) do reset_row(weapon, row) end   -- (an orbital's stats not laid out)
    local t = weapon.passive and tables[weapon.passive]   -- an armor passive: its stacked passives go too
    if t and (settings.stacks[t.index.id] or settings.own_off[t.index.id]) then
        settings.stacks[t.index.id], settings.own_off[t.index.id] = nil, nil
        state.writes = state.writes + 1
        mark_config_dirty()
    end
end

function MOD.nav.tabs_and_kinds(nav_page)
    if not nav_page then return {}, {}, {} end
    if nav_page._tabs_cache then return nav_page._tabs_cache, nav_page._tab_set, nav_page._kind_set end
    local tabs, tab_set, kind_set = {}, {}, {}
    local spec_hash = {}
    for _, spec in ipairs(MOD.weapon_components and MOD.weapon_components.SPECS or {}) do
        spec_hash[spec.SLOT] = spec.HASH
    end
    local fixed = {
        HealthComponents = TYPES.health, DrownComponents = TYPES.drown, ShieldComponents = TYPES.shield,
        ThrowableComponents = TYPES.throwable, ThrowerComponents = TYPES.thrower,
        MinefieldComponents = TYPES.minefield, MineSpawnerComponents = TYPES.mine_spawner,
        FactionComponents = TYPES.faction, MountComponents = TYPES.mount, InventoryComponents = TYPES.inventory,
        SensorEyeComponents = TYPES.sensor, TurretComponents = TYPES.turret,
        EagleComponents = TYPES.eagle, EagleSpawnerComponents = TYPES.eagle_spawner,
        Orbital = TYPES.bombard, Eagle = TYPES.eagle, OrbitalBeam = T_ORBITAL,
        RecDamage = T_DAMAGE, RecProjectile = T_PROJECTILE, RecExplosion = T_EXPLOSION,
        RecArc = TYPES.arc, RecBeam = T_BEAM, RecStatus = T_STATUS,
        CharacterNameFields = MOD.identity and MOD.identity.CHAR,
    }
    for _, sub in ipairs(nav_page.subs or {}) do
        for _, t in ipairs(sub.tabs or {}) do
            if not tab_set[t] then
                tab_set[t] = true
                tabs[#tabs + 1] = t
                local kh = fixed[t] or spec_hash[t]
                if kh then kind_set[kh] = true end
                if t == 'RecStratagem' or t == 'Stratagems' then
                    for _, g in ipairs(stratagem_groups or {}) do kind_set[g] = true end
                end
            end
        end
    end
    nav_page._tabs_cache, nav_page._tab_set, nav_page._kind_set = tabs, tab_set, kind_set
    return tabs, tab_set, kind_set
end

function MOD.nav.page_modified(nav_page)
    if not nav_page then return false end
    local _, tab_set, kind_set = MOD.nav.tabs_and_kinds(nav_page)
    if ui.weapon and tab_set[ui.tab] and (modified(ui.weapon) or MOD.page_changed(ui.weapon)) then return true end
    for _, o in ipairs(overrides) do
        local owner = by_hash[o.hash]
        if owner and tab_set[MOD.nav.tab_of(owner)] then return true end
        local parts = owner and MOD.parts_of(owner, o.id)
        local p = parts and parts[1]
        if p and p.field then
            if p.field.kind and kind_set[p.field.kind] then return true end
            if tab_set['DemolitionComponents'] and p.field.demolition then return true end
        end
    end
    for hash in pairs(MOD.rename.texts or {}) do
        local w = by_hash[hash]
        if w and tab_set[MOD.nav.tab_of(w)] then return true end
    end
    if tab_set['Armors'] and (next(settings.stacks or {}) ~= nil or next(settings.own_off or {}) ~= nil) then return true end
    if tab_set['CurrentLoadout'] then
        local save = rawget(_G, 'SHODAN_PLAYER_SAVE_MODEL')
        if save and save.count and save:count() > 0 then return true end
    end
    if tab_set['PreloadExtra'] then
        local preload = rawget(_G, 'SHODAN_PRELOAD_MODEL')
        if preload and preload.has_changes and preload:has_changes() then return true end
    end
    for _, t in ipairs({ 'PlanetModifierLists', 'GalacticModifierLists' }) do
        if tab_set[t] then
            for _, w in ipairs(weapons_in(t)) do
                if w.custom_modified and w.custom_modified() then return true end
            end
        end
    end
    return false
end

function MOD.nav.reset_page(nav_page)
    if not nav_page then return end
    local tabs, tab_set, kind_set = MOD.nav.tabs_and_kinds(nav_page)
    if ui.weapon and tab_set[ui.tab] then reset_weapon(ui.weapon) end
    for _, t in ipairs(tabs) do
        local ckind = MOD.component_kind(t)
        if ckind and MOD.component_catalog then
            if not MOD.component_catalog.lazy[ckind] then
                for _, w in ipairs(MOD.component_catalog.views[ckind] or {}) do
                    if MOD.page_changed(w) then reset_weapon(w) end
                end
            end
        else
            for _, w in ipairs(weapons_in(t)) do
                if MOD.page_changed(w) or modified(w) then reset_weapon(w) end
            end
        end
    end
    local kept = {}
    for _, o in ipairs(overrides) do
        local owner = by_hash[o.hash]
        local parts = owner and MOD.parts_of(owner, o.id)
        local p = parts and parts[1]
        local match = (owner and tab_set[MOD.nav.tab_of(owner)])
                      or (p and p.field and p.field.kind and kind_set[p.field.kind])
                      or (tab_set['DemolitionComponents'] and p and p.field and p.field.demolition)
        if match then
            for _, part in ipairs(parts or {}) do
                if part.field.demolition then
                    part.field.demolition:write(part.field, nil)
                else
                    local d = default_of(part.field)
                    if d ~= nil then write_field(part.field, d) end
                end
            end
        else
            kept[#kept + 1] = o
        end
    end
    if #kept ~= #overrides then
        overrides = kept
        mark_config_dirty()
    end
    if tab_set['DemolitionComponents'] then
        local bridge = MOD.offline and rawget(_G, 'SHODAN_DEMOLITION_BRIDGE')
        if bridge then bridge:clear(); MOD.sync_demolition(); mark_config_dirty() end
    end
    if tab_set['Armors'] and (next(settings.stacks or {}) ~= nil or next(settings.own_off or {}) ~= nil) then
        settings.stacks, settings.own_off = {}, {}
        state.writes = state.writes + 1
        mark_config_dirty()
    end
    if tab_set['PreloadExtra'] then
        local preload = rawget(_G, 'SHODAN_PRELOAD_MODEL')
        if preload and preload.reset then preload:reset('all') end
    end
    MOD.enemy.faction_refresh()
    ui.version = ui.version + 1
end

function MOD.nav.reset_component(weapon, comp_type)
    if not weapon or not comp_type then return end
    if weapon.component_groups then
        for _, g in ipairs(weapon.component_groups) do
            if g.type == comp_type then
                if g.load then g.load() end
                for _, r in ipairs(g.rows) do
                    if not (weapon.custom_reset and r.custom_value) then reset_row(weapon, r) end
                end
            end
        end
    else
        for _, r in ipairs(weapon.rows) do
            if r.component == comp_type and not (weapon.custom_reset and r.custom_value) then
                reset_row(weapon, r)
            end
        end
    end
    ui.version = ui.version + 1
end

-- The Enemy Editor's values (enemy and spawning pages) or the Stat Editor's: presets of one leave the other's alone.
function MOD.is_enemy_value(hash)
    local w = by_hash[hash]
    return w and (w.enemy or w.health_enemy_scope) and true or false
end

-- Every change of one side back to the game's (enemy: the Enemy Editor's, else the Stat Editor's).
function MOD.reset_side(enemy)
    local keep = {}
    for _, o in ipairs(overrides) do
        if MOD.is_enemy_value(o.hash) == enemy then
            local weapon = by_hash[o.hash]
            local p = weapon and weapon.by_id[o.id]
            local d = p and default_of(p.field)
            if p and p.field.demolition then p.field.demolition:write(p.field, nil)
            elseif d ~= nil then write_field(p.field, d) end
        else
            keep[#keep + 1] = o
        end
    end
    overrides = keep
    mark_config_dirty()
    ui.version = ui.version + 1
end

local function reset_all()
    local preload=rawget(_G,'SHODAN_PRELOAD_MODEL');if preload then local ok,why=preload:reset('all');if not ok then ui.message={text=tostring(why),till=api.now()+6};return nil,why end end
    apply_at = 1
    MOD.clear_grenade_pending()
    for n = #pending, 1, -1 do
        if pending[n].id == 'grenade' then table.remove(pending, n) end
    end
    for _, o in ipairs(overrides) do
        local weapon = by_hash[o.hash]
        local p = weapon and weapon.by_id[o.id]
        local d = p and default_of(p.field)
        if d ~= nil and not p.field.demolition then write_field(p.field, d) end
    end
    local bridge = MOD.offline and rawget(_G, 'SHODAN_DEMOLITION_BRIDGE')
    if bridge then
        local ok, why = bridge:clear()
        if not ok then ui.message = {text=tostring(why),till=api.now()+5}; return nil,why end
    end
    overrides = {}
    mark_config_dirty()
    ui.version = ui.version + 1
    return true
end

-- The cache: every change the editor keeps between runs — the values (reset_all: values, preload plans and the
-- demolition overrides), the passive stacks, the typed names and descriptions, and the loadout edits of the player
-- save. Cleared by the Settings page's button, and (Settings > Clear the cache on close) when the editor closes. The
-- presets and the game's own files are left alone: only Install writes to the game.
local function clear_editor_cache()
    local ok, why = reset_all()
    if not ok then return nil, why end
    settings.stacks, settings.own_off = {}, {}
    MOD.rename.texts = {}
    ui.rename = nil
    local save = rawget(_G, 'SHODAN_PLAYER_SAVE_MODEL')
    if save then
        local done, err = pcall(save.reset, save)
        if not done then return nil, tostring(err) end
    end
    MOD.restore_installed({},math.huge)
    -- (the host: the buffers hold the files' values again, so nothing is waiting to be installed)
    state.cache_cleared = (state.cache_cleared or 0) + 1
    mark_config_dirty()
    ui.version = ui.version + 1
    return true
end

function settings.set_changes(on)
    if settings.changes == on then return end
    settings.changes = on
    if on then
        pending, apply_at = {}, 1
        for _, o in ipairs(overrides) do
            local w = by_hash[o.hash]
            local p = w and w.by_id[o.id]
            if not (p and p.field.demolition) then pending[#pending + 1] = { hash = o.hash, id = o.id, value = o.value } end
            if p and p.field.storage == 'grenade' then p.field.pending_value = o.value end
        end
        log('settings: changes on (' .. #pending .. ' value(s) applied again)')
    else
        pending = {}
        MOD.clear_grenade_pending()
        for _, o in ipairs(overrides) do
            local weapon = by_hash[o.hash]
            local p = weapon and weapon.by_id[o.id]
            local d = p and default_of(p.field)
            if d ~= nil and not p.field.demolition then write_field(p.field, d) end
        end
        log('settings: changes off (' .. #overrides .. ' value(s) kept, the game\'s values written)')
    end
    mark_config_dirty()
    ui.version = ui.version + 1
end

-- ---------------------------------------------------------------- presets
-- One global snapshot across parameters, demolition, equipment and preload plans.
local presets = require('preset_controller').new({
    ui=ui,by_hash=by_hash,lang=function()return settings.lang end,tr=function(v)return settings.tr(v)end,
    navigation=MOD.nav.PAGES,tab_of=MOD.nav.tab_of,tab_label=MOD.nav.tab_label,
    default_value=function(hash,id)return state.vanilla(hash,id)end,
    detail_version=function()
        local save=rawget(_G,'SHODAN_PLAYER_SAVE_MODEL')
        return tostring(save)..':'..tostring(save and save.version)..':'..tostring(save and save.save)
    end,
    passive_name=function(id)return settings.tr(KINDS[TYPES.passive].NAMES[tonumber(id)]or('Passive '..id))end,
    folder=function()return assert(data_dir('StatEditor'),'Preset directory unavailable')end,
    preset_folder=function()return rawget(_G,'SHODAN_PRESET_DIRECTORY')or(assert(data_dir('StatEditor'))..'/Presets')end,
    open_folder=function(path)return settings.open(path:gsub('/','\\'))end,
    sync=function()MOD.sync_demolition();mark_config_dirty()end,
    now=function()return api.now()end,log=log,parse_number=MOD.parse_number,
    enabled=function()return settings.changes end,
    values=function(enemy)
        local out={}
        for _,o in ipairs(overrides)do if (enemy==nil or MOD.is_enemy_value(o.hash)==enemy)and(enemy~=nil or not o.demolition)then
            out[#out+1]={hash=o.hash,id=o.id,value=o.value}
        end end
        return out
    end,
    preload_values=function()
        local out={};for _,o in ipairs(overrides)do local w=by_hash[o.hash]
            if w and w.preload_parameters then out[#out+1]={hash=o.hash,id=o.id,value=o.value}end
        end;return out
    end,
    game_settings=function()
        local stacks,own_off={},{}
        for id,values in pairs(settings.stacks or{})do
            local a={};for i,v in ipairs(values)do a[i]=v end;stacks[tostring(id)]=a
        end
        for id,value in pairs(settings.own_off or{})do own_off[tostring(id)]=value end
        return {stacks=stacks,own_off=own_off}
    end,
    apply=function(preset)
        local stacks,own_off
        if preset.data and((preset.scope=='game'and preset.kind=='snapshot')or preset.scope=='global')then
            assert(type(preset.data.stacks)=='table'and type(preset.data.own_off)=='table','Invalid armor configuration in preset')
            stacks,own_off={},{}
            for id,values in pairs(preset.data.stacks)do
                local key=tonumber(id);assert(key and key%1==0 and key>=0 and type(values)=='table','Invalid passive stacking entry')
                stacks[key]={};for i,v in ipairs(values)do assert(type(v)=='number'and v%1==0 and v>=0,'Invalid passive ID');stacks[key][i]=v end
            end
            for id,value in pairs(preset.data.own_off)do local key=tonumber(id)
                assert(key and key%1==0 and key>=0 and type(value)=='boolean','Invalid passive switch');own_off[key]=value
            end
        end
        if preset.scope=='global'and preset.kind~='patch'then
            local ok,why=reset_all();assert(ok,why)
            pending,apply_at={},1
        elseif preset.scope=='preload'and preset.kind~='patch'then
            local kept={};for _,o in ipairs(overrides)do local w=by_hash[o.hash]
                if w and w.preload_parameters then
                    for _,part in ipairs(MOD.parts_of(w,o.id)or{})do local value=default_of(part.field);if value~=nil then write_field(part.field,value)end end
                else kept[#kept+1]=o end
            end
            overrides=kept;mark_config_dirty()
        elseif preset.kind~='patch'then MOD.reset_side(preset.scope=='enemy')end
        if stacks then settings.stacks,settings.own_off=stacks,own_off;state.writes=state.writes+1;mark_config_dirty()end
        local refused=0
        for _,o in ipairs(preset.values)do
            local weapon=by_hash[o.hash]
            local parts=weapon and MOD.parts_of(weapon,o.id)
            local ok,why=false,weapon and('no stat '..o.id)or('unknown entity '..o.hash)
            for _,p in ipairs(parts or{})do
                local default=default_of(p.field)
                ok,why=write_field(p.field,o.value)
                if p.field.storage=='grenade'and why=='grenade assets loading'then ok=true end
                if ok then set_override(weapon,p,(weapon.enemy and not weapon.enemy.faction)and o.value or unless_default(o.value,default))end
                if ok and #parts==1 and p.row and p.row.mult and p.row.parts[1]==p then MOD.enemy.mult_fields(weapon,p.row,o.value)end
            end
            if not ok then refused=refused+1;log('preset '..preset.name..': '..o.hash..' '..o.id..': '..tostring(why))end
        end
        ui.version=ui.version+1
        return true,refused>0 and(tostring(refused)..' 个参数在当前版本不可用。')or nil
    end,
})

-- Workspaces preserve the complete editor selection while presets/settings are open.
MOD.workspace={}
function MOD.workspace.mode()return ui.settings and'settings'or ui.tab=='Presets'and'presets'or'editor'end
function MOD.workspace.open(mode)
    local current=MOD.workspace.mode()
    if mode==current then mode='editor'end
    if state.commit_value then local ok,why=state.commit_value();if not ok then
        ui.message={text=tostring(why),till=api.now()+7};return nil,why
    end end
    if ui.editing then local ok,why=presets.finish_rename(true);if not ok then return nil,why end end
    if mode=='editor'then
        local saved=ui.workspace_return
        if saved then
            ui.tab,ui.weapon,ui.page,ui.row,ui.scroll,ui.search=saved.tab,saved.weapon,saved.page,saved.row,saved.scroll,saved.search
            MOD.enemy.on=saved.enemy
        end
        ui.workspace_return=nil;ui.settings=false;ui.confirm=nil;ui.context_menu=nil
    else
        if not ui.workspace_return then
            ui.workspace_return={tab=ui.tab,weapon=ui.weapon,page=ui.page,row=ui.row,scroll=ui.scroll,
                search={text=ui.search.text,active=false},enemy=MOD.enemy.on}
        end
        ui.stack_pick,ui.component_menu,ui.weapon_menu,ui.binding,ui.context_menu=nil,nil,nil,nil,nil
        if mode=='presets'then
            presets.select_scope('global')
            ui.tab='Presets';ui.settings=false
        elseif mode=='settings'then ui.tab=ui.workspace_return.tab;ui.settings=true
        else return nil,'Unknown workspace'end
        ui.search={text='',active=false};ui.confirm=nil
    end
    ui.version=ui.version+1;return true
end

-- Draws the whole panel into a fresh screen gui. Coordinates are 1080p units from the panel's
-- top left; the gui itself counts pixels from the bottom left.
local function draw(width, height)
    if ui.weapon and ui.weapon.ensure_rows then ui.weapon.ensure_rows() end
    local Gui, Vector3, Vector2, Color = sr.Gui, sr.Vector3, sr.Vector2, sr.Color
    local s = height / 1080 * (MOD.offline and 100 or settings.size) / 100   -- panel units -> 1080p units (offline: the window is the panel's)
    -- sx / sy: panel units -> pixels across / down; s: the text's (the smaller). In game the panel keeps its shape;
    -- offline it fills the window at any shape: its layout stretches, its text keeps its proportions.
    local sx, sy = s, s
    if MOD.offline then sx, sy = width / (W + 60), height / (H + 100); s = math.min(sx, sy) end
    local ox, oy = settings.side == 'left' and 30 * sx or width - (W + 30) * sx, (height - H * sy) / 2
    local gui = ui.gui
    local regions = {}
    local shared_overlay = nil   -- set while the cursor is on a cut-short 'shared with' list
    local tip_overlay = nil      -- set while the cursor is on a row with a tip (row.tip: its lines)
    local ink_font, ink_material = font.font, font.material

    local function color(r, g, b, a) return Color(a or 255, r, g, b) end
    local function vx(v)
        for _, get in ipairs({ function() return Vector2.x(v) end, function() return Vector3.x(v) end,
                               function() return v[1] end }) do
            local ok, x = pcall(get)
            if ok and type(x) == 'number' then return x end
        end
        return nil
    end
    local GOLD, WHITE, MUTED, DIM = MOD.enemy.on and ui.tab~='Presets'and not ui.settings and color(255, 72, 60) or color(255, 213, 0), color(238, 242, 246), color(153, 171, 184), color(95, 108, 120)
    MOD.enemy.ALL_INK = MOD.enemy.ALL_INK or color(120, 200, 255)   -- a value only an 'All <faction>' row changed
    local WARN, GOOD = color(255, 150, 60), color(120, 220, 140)

    local function rect(x, y, w, h, c, z)
        step('Gui.rect')
        Gui.rect(gui, Vector3(ox + x * sx, height - oy - (y + h) * sy, z or 951), Vector2(w * sx, h * sy), c)
    end
    -- a text's width on screen at a (scaled) size; measured once per text, size and font (the panel redraws often)
    local function measure_text(value, size)
        local key = value .. '|' .. size
        local measure = ui.measured[key]
        if not measure then
            step('Gui.text_extents')
            local ok, lo, hi = pcall(Gui.text_extents, gui, value, ink_font, size)
            if ok and lo and hi then
                local a, b = vx(lo), vx(hi)
                if a and b and b > a then measure = b - a end
            end
            if not measure then   -- per character: CJK is about twice as wide as Latin
                local units = 0
                for c in value:gmatch('[^\128-\191]') do units = units + (c < '\128' and 0.5 or 1) end
                measure = units * size
            end
            if ui.measures > 5000 then ui.measured, ui.measures = {}, 0 end
            ui.measured[key], ui.measures = measure, ui.measures + 1
        end
        return measure
    end
    local function width(value, size) return measure_text(settings.tr(value), size) end
    local function text(value, x, y, size, c, limit, align_right, z)
        if value == nil or value == '' or not ink_font then return end
        value = settings.tr(value)
        local design = size
        size = size * s
        local px = ox + x * sx
        if limit or align_right then
            local measure = measure_text(value, size)
            if limit and measure > limit * sx then size = size * limit * sx / measure; measure = limit * sx end
            if align_right then px = px - measure end
        end
        -- (its middle where the layout's is: the boxes around it stretch with sy, the text with s)
        local top = (y + design / 2) * sy - design * s / 2
        step('Gui.text')
        Gui.text(gui, value, ink_font, size, ink_material, Vector3(px, height - oy - top - size * 0.8, z or 953), c or WHITE)
    end
    local function outline(x, y, w, h, c, z)
        z = z or 952
        rect(x, y, w, 2, c, z); rect(x, y + h - 2, w, 2, c, z)
        rect(x, y, 2, h, c, z); rect(x + w - 2, y, 2, h, c, z)
    end
    local function region(key, x, y, w, h, enabled)
        regions[#regions + 1] = { key = key, x = ox + x * sx, y = height - oy - (y + h) * sy, w = w * sx, h = h * sy,
                                  enabled = enabled ~= false }
    end
    -- z: over an overlay (its buttons at z, z + 1, z + 2)
    local function button(key, label, x, y, w, h, enabled, active, ink, z)
        local hovered = ui.hover == key and enabled ~= false
        local fill = active and (MOD.enemy.on and ui.tab~='Presets'and not ui.settings and color(96, 20, 16) or color(90, 74, 8)) or hovered and color(52, 66, 80) or color(28, 34, 42)
        rect(x, y, w, h, fill, z or 951)
        outline(x, y, w, h, enabled == false and DIM or (active or hovered) and GOLD or color(70, 82, 94), z and z + 1)
        text(label, x + 8, y + (h - 16) / 2, 16, enabled == false and DIM or ink or WHITE, w - 12, false, z and z + 2)
        region(key, x, y, w, h, enabled)
    end

    -- frame
    rect(0, 0, W, H, color(8, 11, 15, math.floor(255 * settings.opacity / 100 + 0.5)), 950)
    local frame_top=state.phase=='ready'and ui.tab=='Presets'and not ui.settings and 48 or 0
    outline(0, frame_top, W, H-frame_top, GOLD)
    region('panel', 0, frame_top, W, H-frame_top, false)
    if state.phase=='ready'and ui.tab=='Presets'and not ui.settings then
        ui.lbar=nil;ui.split_gx=ox+343*sx
        button('workspace_back',MOD.nav.text({'Back to editor','返回编辑','返回編輯'}),W-156,8,140,32,true)
        require('preset_panel').draw({presets=presets,ui=ui,W=W,H=H-frame_top,lang=function()return settings.lang end,
            text=function(v,x,y,...)return text(v,x,y+frame_top,...)end,
            button=function(k,v,x,y,...)return button(k,v,x,y+frame_top,...)end,
            rect=function(x,y,...)return rect(x,y+frame_top,...)end,
            outline=function(x,y,...)return outline(x,y+frame_top,...)end,
            region=function(k,x,y,...)return region(k,x,y+frame_top,...)end,
            GOLD=GOLD,WHITE=WHITE,MUTED=MUTED,selected=color(90,74,8),hover=color(40,52,64),
            line=color(70,82,94),input=color(20,26,34),status=state.host_status})
        return regions
    end
    -- the page's name (the layout document's; before the stats are found, the editor's)
    local nav_page, nav_sub, nav_k
    if state.phase == 'ready' then MOD.nav.sync(); nav_page, nav_sub, nav_k = MOD.nav.current() end
    local title = ui.settings and settings.tr('Settings') or nav_page and MOD.nav.text(nav_page.name) or (MOD.enemy.on and 'SHODAN ENEMY EDITOR' or 'SHODAN STAT EDITOR')
    text(title, 18, 12, 24, GOLD)
    if ui.settings then button('workspace_back',MOD.nav.text({'Back to editor','返回编辑','返回編輯'}),W-156,10,140,32,true)end
    if not MOD.offline then   -- (offline the panel is the window)
        text(hotkey_name .. ' to open/close', W - 56, 16, 15, MUTED, nil, true)
        button('close', 'X', W - 16 - 30, 10, 30, 30, true)
    end
    if rawget(_G, 'SHODAN_PACK_HUB') or rawget(_G, 'SHODAN_SCAN_HUB') then
        text('SHODAN weapon mods are running too: they put their own values back every 5 s', 290, 17, 14, WARN, 540)
    end

    if state.phase ~= 'ready' then
        local found = 0
        for _, kind in ipairs(KIND_ORDER) do if tables[kind] then found = found + 1 end end
        text('Reading the game\'s weapon tables... (' .. found .. ' of ' .. #KIND_ORDER .. ' found)', 18, 70, 18, WHITE)
        return regions
    end

    -- the page's sub-pages, each as wide as its (translated) name, the row shrunk to end before the reset button
    -- (offline the reset button sits up on the title's line: the sub-pages get the whole row); a placeholder's name
    -- dimmer, and one whose tabs Settings > Tabs shown all turned off left out
    if not ui.settings then
        local shown, widths, total = {}, {}, 0
        for k, sub in ipairs(nav_page.subs) do
            local on = sub.tabs == nil
            for _, t in ipairs(sub.tabs or {}) do on = on or not settings.hidden[MOD.nav.base(t)] end
            if on then
                shown[#shown + 1] = k
                widths[#shown] = math.max(48, width(MOD.nav.text(sub.name), 16) + 22)
                total = total + widths[#shown]
            end
        end
        local room = W - 16 - (MOD.offline and 0 or 124 + 16) - 4 * (#shown - 1)
        local fit, tab_x = math.min(1, room / math.max(1, total)), 16
        for i, k in ipairs(shown) do
            local sub, w = nav_page.subs[k], math.floor(widths[i] * fit + 0.5)
            button('nav:' .. nav_page.id .. ':' .. k, MOD.nav.text(sub.name), tab_x, 52, w, 32, true,
                   k == nav_k and ui.tab ~= 'Presets', sub.todo and k ~= nav_k and MUTED or nil)
            tab_x = tab_x + w + 4
        end
        -- the sub-page's tabs when it has several (after the page's name; Weapon editing filters in the left list)
        local cats, merged = {}, false
        for _, t in ipairs(not nav_sub.weapon_browser and nav_sub.tabs or {}) do
            if settings.hidden[MOD.nav.base(t)] then
            elseif nav_sub.enemy_browser and MOD.ENEMY_SLOTS[t] then   -- (敌人编辑: the factions in one tab)
                if not merged then merged = true; cats[#cats + 1] = 'Enemies' end
            else cats[#cats + 1] = t end
        end
        if #cats > 1 then
            local cx = 18 + width(title, 24) + 24
            local right = MOD.offline and W - 16 - 124 - 16 or W - 320
            local cw, ctotal = {}, 0
            for i, t in ipairs(cats) do
                cw[i] = math.max(60, width(MOD.nav.tab_label(t), 16) + 24)
                ctotal = ctotal + cw[i]
            end
            local cfit = math.min(1, (right - cx - 4 * (#cats - 1)) / ctotal)
            for i, t in ipairs(cats) do
                local w = math.floor(cw[i] * cfit + 0.5)
                button('cat:' .. t, MOD.nav.tab_label(t), cx, 10, w, 30, true, ui.tab == t or t == 'Enemies' and MOD.ENEMY_SLOTS[ui.tab] == true)
                cx = cx + w + 4
            end
        end
    end
    if not ui.settings then button('reset_nav_page', settings.tr('Reset this page'), W - 16 - 124, MOD.offline and 10 or 52, 124, MOD.offline and 30 or 32, MOD.nav.page_modified(nav_page))end

    -- a list's scroll bar (the weapon list, or the full presets): a thin track between the list and the
    -- line that parts the panel's halves, shown when the list is longer than LIST_ROWS
    ui.lbar, ui.split_gx = nil, ox + 343 * sx
    local function list_bar(id, total)
        local count=ui.list_rows or(id=='page'and MOD.component_rows()or LIST_ROWS)
        if total <= count then return end
        local top = ui.list_top or(id=='page'and(MOD.component_kind()and 154 or(MOD.weapon_browser_active()or MOD.enemy_browser())and 126)or 96)
        local len, span = count * 26 - 1, total - count
        local th = math.max(24, len * count / total)
        local ty = top + (len - th) * math.min(1, (ui[id] - 1) / span)
        rect(336, top, 5, len, color(28, 34, 42), 951)
        local hot = (ui.drag and ui.drag.bar == 'lbar') or ui.hover == 'lbar:thumb'
        rect(336, ty, 5, th, hot and GOLD or color(110, 124, 138), 952)
        region('lbar:track', 335, top, 8, len)
        region('lbar:thumb', 335, ty, 8, th)
        ui.lbar = { id = id, top = height - oy - top * sy, bottom = height - oy - (top + len) * sy,
                    thumb_top = height - oy - ty * sy, thumb = th * sy, span = span, page = count }
    end

    local presets_tab = ui.tab == 'Presets'
    -- a placeholder sub-page: what it is to hold, over the whole panel (a search shows the list as ever)
    local todo_view = not presets_tab and not ui.settings and nav_sub and (nav_sub.todo or MOD.nav.TODO_TABS[ui.tab]) and ui.search.text == ''
                      and not ui.search.active
    -- a sub-page of one page (人物数据): no list beside it, its stats across the panel (the wheel scrolls them anywhere)
    local solo_view = not presets_tab and not ui.settings and nav_sub and nav_sub.solo
    if solo_view then ui.split_gx = ox end
    -- weapon list
    local component_kind=MOD.component_kind()
    local component_browser=component_kind and MOD.component_catalog and not ui.settings
    local weapon_browser=MOD.weapon_browser_active()
    local enemy_categories,enemy_key=nil,nil
    if not component_browser and not weapon_browser and MOD.enemy_browser()then enemy_categories,enemy_key=MOD.enemy_categories()end
    local record_tab = MOD.record_names.is_tab(ui.tab)
    local list_rows=(component_browser or record_tab)and 21 or(weapon_browser or enemy_key)and 26 or LIST_ROWS
    local list_top=(component_browser or record_tab)and 222 or(weapon_browser or enemy_key)and 126 or 96
    ui.list_top, ui.list_rows = list_top, list_rows
    if component_browser then
        local catalog=MOD.component_catalog
        local categories=catalog:categories();local selected=1
        for i,category in ipairs(categories)do if category.id==settings.component_category then selected=i end end
        if settings.component_category~='all'and not catalog.config.by_id[settings.component_category]then settings.component_category='all' end
        button('component_cat:prev','<',16,94,32,28,true)
        button('component_cat:menu',categories[selected].name,52,94,246,28,true,ui.component_menu)
        button('component_cat:next','>',302,94,32,28,true)
        local checked=settings.component_show_missing
        rect(18,132,16,16,color(20,26,34),951);outline(18,132,16,16,checked and GOLD or MUTED)
        if checked then text('✓',19,129,17,GOLD)end
        text(MOD.nav.text({'Show entities without this component','显示无本组件的实体','顯示無本組件的實體'}),42,131,14,WHITE,210)
        region('component_missing',16,126,246,26)
    elseif weapon_browser then
        local categories=MOD.weapon_categories();local selected=1
        for i,category in ipairs(categories)do if category.id==settings.weapon_category then selected=i end end
        if selected==1 then settings.weapon_category='all'end
        button('weapon_cat:prev','<',16,94,32,28,true)
        button('weapon_cat:menu',categories[selected].name,52,94,246,28,true,ui.weapon_menu)
        button('weapon_cat:next','>',302,94,32,28,true)
    elseif enemy_key then
        local selected=1
        for i,category in ipairs(enemy_categories)do if category.id==settings[enemy_key]then selected=i end end
        if selected==1 then settings[enemy_key]='all'end
        button('enemy_cat:prev','<',16,94,32,28,true)
        button('enemy_cat:menu',enemy_categories[selected].name,52,94,246,28,true,ui.enemy_menu)
        button('enemy_cat:next','>',302,94,32,28,true)
    end
    -- Hash and TypeID lists share the same jump/reload/folder control geometry.
    if (component_browser or record_tab)and not presets_tab and not ui.settings and not todo_view and not solo_view then
        local rid,active=ui.record_id,ui.record_id.active
        local hash_mode=component_browser or ui.tab=='OrbitalBeam'
        if record_tab then
            text(hash_mode and 'EntityHash' or 'TypeID / ComponentIndexData.index',24,102,16,MUTED,302)
            text(MOD.nav.text({'Jump as you type; search this list below','输入即跳转；下方搜索当前列表','輸入即跳轉；下方搜尋目前列表'}),24,134,14,DIM,302)
        end
        rect(16,158,318,30,active and color(20,26,34)or color(28,34,42),951)
        outline(16,158,318,30,active and GOLD or(ui.hover=='record_id'and GOLD or color(70,82,94)))
        if rid.text==''and not active then
            text(hash_mode and MOD.nav.text({'Jump to hash (hex / decimal)','跳转哈希（十六进制 / 十进制）','跳轉雜湊（十六進位 / 十進位）'})
                or MOD.nav.text({'Jump to current TypeID index','跳转当前 TypeID 的索引','跳轉目前 TypeID 的索引'}),24,165,14,DIM,302)
        else text(rid.text..(active and '_'or''),24,164,16,WHITE,302)end
        region('record_id',16,158,318,30)
        button(component_browser and'component_reload'or'record_names_reload',MOD.nav.text({'Reload JSON','重载JSON','重載JSON'}),16,194,116,26,true)
        button(component_browser and'component_config'or'record_names_folder',MOD.nav.text({'Open JSON folder','打开JSON文件夹','開啟JSON資料夾'}),138,194,196,26,true)
    end
    local searching = ui.search.text ~= '' or ui.search.active
    local list = (presets_tab or ui.settings or todo_view or solo_view) and {} or weapons_in((ui.search.text ~= '' or ui.search.edited) and '?search' or ui.tab)
    local last_top = math.max(1, #list - list_rows + 1)
    ui.page = math.max(1, math.min(ui.page, last_top))
    for k = 1, list_rows do
        local weapon = list[ui.page + k - 1]
        if not weapon then break end
        local y = list_top + (k - 1) * 26
        local key = 'weapon:' .. weapon.hash
        if searching and not component_browser then text(MOD.nav.tab_label(MOD.nav.tab_of(weapon)), 326, y + 5, 13, DIM, 80, true) end
        local selected = weapon == ui.weapon
        if selected then rect(16, y, 318, 25, (MOD.enemy.on and color(96, 20, 16) or color(90, 74, 8)), 951)
        elseif ui.hover == key then rect(16, y, 318, 25, color(40, 52, 64), 951) end
        local changed = modified(weapon)
        local ink = changed and GOLD or WHITE
        if weapon.component_entry and not weapon.has_component then ink=DIM end
        if not changed and MOD.enemy.by_all_pages and MOD.enemy.by_all_pages[weapon.hash] then changed, ink = true, MOD.enemy.ALL_INK end
        -- a stratagem: its number as an extra stratagem after its name
        if (weapon.stratagem or weapon.sentry_defs) and not MOD.extra.list then MOD.extra.choices() end
        local id = (not record_tab) and weapon.extra_id and ' (' .. weapon.extra_id .. ')' or ''
        -- a part of the page above it ("Annihilator Tank: mounted weapon 1" under Annihilator Tank): indented,
        -- smaller, without the name it shares
        local owner = not searching and weapon.name:match('^(.+): [^:]+$')
        if owner then
            local j = ui.page + k - 2
            while list[j] and list[j].name:sub(1, #owner + 2) == owner .. ': ' do j = j - 1 end
            if not (list[j] and list[j].name == owner) then owner = nil end
        end
        if owner then
            local full, top = settings.tr(weapon.name), settings.tr(owner)
            local rest = full:sub(1, #top) == top and full:sub(#top + 1):gsub('^%s*:%s*', ''):gsub('^\239\188\154%s*', '') or full
            rest = rest:gsub('^%l', string.upper)
                       :gsub('^\208([\176-\191])', function(c) return '\208' .. string.char(c:byte() - 32) end)   -- а-п
                       :gsub('^\209([\128-\143])', function(c) return '\208' .. string.char(c:byte() + 32) end)   -- р-я
            text((changed and '* ' or '') .. rest .. id, 44, y + 5, 14, ink, searching and 206 or 282)
        else
            local category=component_browser and settings.component_category=='all'and('['..weapon.catalog_record.category_name..'] ')
                or weapon_browser and settings.weapon_category=='all'and('['..settings.tr(weapon.slot)..'] ')
                or enemy_key and not searching and settings[enemy_key]=='all'and('['..settings.tr(weapon.slot)..'] ')or''
            local label = record_tab and MOD.record_names.label(weapon, settings.tr) or settings.tr(weapon.name)
            text((changed and '* ' or '') .. category .. label .. id, 24, y + 4, 16, ink, (component_browser or weapon_browser or enemy_key) and 302 or searching and 226 or 302)
        end
        region(key, 16, y, 318, 25)
    end
    -- the Boosters tab: why only some boosters are there, under the list
    if ui.tab == 'Boosters' and not searching and not presets_tab and #list > 0 and #list <= LIST_ROWS - 5 then
        local line, y, words = '', 96 + #list * 26 + 12, settings.tr(MOD.boosters.WHY)
        local spaced = words:find(' ')
        for word in words:gmatch(spaced and '%S+' or '[^\128-\191][\128-\191]*') do
            local next_line = line == '' and word or (line .. (spaced and ' ' or '') .. word)
            if line ~= '' and width(next_line, 14) > 306 then
                text(line, 24, y, 14, MUTED); y, line = y + 19, word
            else
                line = next_line
            end
        end
        text(line, 24, y, 14, MUTED)
    end
    local py = list_top + list_rows * 26 + 8
    if not presets_tab and not ui.settings and not todo_view and not solo_view then
        if ui.search.text ~= '' and #list == 0 then text('Nothing matches.', 24, 100, 16, MUTED)
        elseif ui.search.edited and #list == 0 then text('No changes.', 24, 100, 16, MUTED) end
        button('page:prev', '<', 16, py, 40, 30, ui.page > 1)
        list_bar('page', #list)
        text((#list > list_rows and (ui.page .. '-' .. math.min(#list, ui.page + list_rows - 1) .. ' of ') or '') ..
             #list .. ((ui.search.text ~= '' or ui.search.edited) and ' found' or ' listed'),
             70, py + 7, 16, MUTED, 214)
        button('page:next', '>', 294, py, 40, 30, ui.page < last_top)
        -- search box: click it (or Ctrl+F) and type; the list shows what matches, from every tab
        local sy, active = py + 40, ui.search.active
        rect(16, sy, 234, 30, active and color(20, 26, 34) or color(28, 34, 42), 951)
        outline(16, sy, 234, 30, active and GOLD or (ui.hover == 'search' and GOLD or color(70, 82, 94)))
        if ui.search.text == '' and not active then
            text(record_tab and MOD.nav.text({'Search name or design name','搜索名称或策划名','搜尋名稱或策劃名'})or component_browser and MOD.nav.text({'Search design name / hex / decimal','搜索策划名 / 十六进制 / 十进制','搜尋策劃名 / 十六進位 / 十進位'})or MOD.enemy.on and 'Search enemies' or 'Search weapons and stratagems', 24, sy + 7, 15, DIM, 218)
        else
            text(ui.search.text .. (active and '_' or ''), 24, sy + 6, 16, WHITE, 218)
        end
        region('search', 16, sy, 234, 30)
        -- '*': only the pages with a change (with no text: every tab's)
        button('search:edited', '*', 256, sy, 34, 30, true, ui.search.edited)
        button('search:clear', 'X', 296, sy, 38, 30, ui.search.text ~= '')
        rect(343, 96, 2, H - 96 - 70, color(70, 82, 94), 951)
    end

    -- stats of the selected weapon
    local weapon = ui.weapon
    local x0 = (solo_view or ui.settings) and 24 or 356
    if ui.settings then
        local y = 56
        local function choice(label, key, options, current)
            text(label, x0, y + 6, 16, WHITE, 270)
            for k, o in ipairs(options) do
                button('set:' .. key .. ':' .. tostring(o[1]), o[2], 640 + (k - 1) * 64, y, 60, 28, true, o[1] == current)
            end
            y = y + 36
        end
        local ONOFF = { { 'on', 'On' }, { 'off', 'Off' } }
        local function onoff(v) return v and 'on' or 'off' end
        if MOD.offline then
            text('Language', x0, y + 6, 16, WHITE, 270)
            local options = { { id = 'en', name = 'English' } }
            for _, l in ipairs(MOD.langs or {}) do options[#options + 1] = l end
            for k, l in ipairs(options) do
                button('set:lang:' .. l.id, l.name, 640 + (k - 1) * 86, y, 82, 28, true, settings.lang == l.id)
            end
        else
            text('Open / close key', x0, y + 6, 16, WHITE, 270)
            button('set:bind', ui.binding and 'Press a key (Esc cancels)' or hotkey_name, 640, y, ui.binding and 316 or 124, 28, true, ui.binding)
        end
        y = y + 36
        if MOD.offline then
            -- Both display controls share one row, leaving the existing settings
            -- and repository links visible above the footer.
            local function display_field(key, label_x, control_x, value_width, shown, reset_id, reset_label, reset_on)
                text(MOD.nav.text(settings.DISPLAY[key]), label_x, y + 6, 16, WHITE, control_x - label_x - 12)
                button('set:' .. key .. ':down', '<', control_x, y, 36, 28, true)
                local value_x = control_x + 40
                local typing = ui.value and ui.value.setting == key
                local hovered = ui.hover == 'value:' .. key
                rect(value_x, y, value_width, 28, hovered and color(40, 52, 64) or color(20, 26, 34), 951)
                outline(value_x, y, value_width, 28, (typing or hovered) and GOLD or color(56, 66, 78))
                text(typing and (ui.value.text .. '_') or shown, value_x + value_width - 8, y + 6, 17, WHITE, value_width - 16, true)
                region('value:' .. key, value_x, y, value_width, 28)
                button('set:' .. key .. ':up', '>', value_x + value_width + 4, y, 36, 28, true)
                button('set:' .. key .. ':' .. reset_id, MOD.nav.text(reset_label), value_x + value_width + 48, y, 84, 28, reset_on)
            end
            display_field('font_px', x0, 166, 120, settings.font_px .. ' px', 'reset', { 'Reset', '重置', '重置' }, settings.font_px ~= 16)
            local dw, dh = settings.display_size()
            local resolution = dw and (dw .. ' × ' .. dh) or '-'
            display_field('render_height', 516, 640, 150,
                          settings.render_height > 0 and resolution or (MOD.nav.text({ 'Auto', '自动', '自動' }) .. '  ' .. resolution),
                          'auto', { 'Auto', '自动', '自動' }, settings.render_height > 0)
            y = y + 38
        end
        -- offline (the panel is the window, edits go into the game's files) only the rows that apply there
        if not MOD.offline then choice('Block game input while open', 'block_input', ONOFF, onoff(settings.block_input)) end
        choice('Apply my changes', 'changes', ONOFF, onoff(settings.changes))
        text(settings.changes and ('On: your ' .. #overrides .. ' change(s) are applied.')
             or ('Off: the game\'s values everywhere; your ' .. #overrides .. ' change(s) are kept for when you turn them on.'),
             x0 + 16, y - 6, 14, settings.changes and MUTED or WARN, W - x0 - 40)
        y = y + 14
        local function percent(label, key)
            text(label, x0, y + 6, 16, WHITE, 270)
            local r = settings.RANGE[key]
